{
  "name": "Florida B.E.S.T. Math Architect",
  "description": "An AI-powered platform for generating K-12 math quizzes aligned with Florida B.E.S.T. standards, analyzing student learning gaps, and creating instant remedial learning materials."
}

export enum GradeLevel {
  K = 'Kindergarten',
  G1 = 'Grade 1',
  G2 = 'Grade 2',
  G3 = 'Grade 3',
  G4 = 'Grade 4',
  G5 = 'Grade 5',
  G6 = 'Grade 6',
  G7 = 'Grade 7',
  G8 = 'Grade 8',
  Alg1 = 'Algebra 1',
  Geo = 'Geometry'
}

export interface Standard {
  code: string;
  description: string;
  grade: GradeLevel;
  clarifications?: string[];
  examples?: string[];
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
  animationDescription: string; // Description for a potential animation
}

export interface Quiz {
  standardCode: string;
  questions: Question[];
}

export interface QuizResult {
  questionIndex: number;
  selectedOptionIndex: number;
  isCorrect: boolean;
  timeTaken: number; // seconds
}

export enum GapType {
  Conceptual = 'Conceptual Understanding',
  Procedural = 'Procedural Fluency',
  Computational = 'Computational Error',
  Unknown = 'Needs More Data'
}

export interface GapAnalysis {
  standardCode: string;
  identifiedGaps: {
    gapType: GapType;
    description: string;
    relatedQuestions: number[]; // Indices
  }[];
  confidenceScore: number; // 0-100
  summary: string;
}

export interface RemedialSlide {
  slideNumber: number;
  title: string;
  content: string; // Markdown supported
  visualDescription: string;
  vocabulary: string[];
}

export interface AppState {
  view: 'setup' | 'quiz' | 'analysis' | 'remedial';
  selectedStandard: Standard | null;
  quiz: Quiz | null;
  quizResults: QuizResult[];
  analysis: GapAnalysis | null;
  slides: RemedialSlide[];
  loading: boolean;
  loadingMessage: string;
}

import { GradeLevel, Standard } from './types';

// A subset of standards extracted from the provided PDF to serve as selection options
export const FLORIDA_STANDARDS: Standard[] = [
  {
