import { GoogleGenAI, Schema, Type } from "@google/genai";
import { Standard, Quiz, GapAnalysis, RemedialSlide, GapType, QuizResult, Question } from '../types';
import { MTR_STANDARDS } from '../constants';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const generateQuiz = async (standard: Standard): Promise<Quiz> => {
  if (!apiKey) throw new Error("API Key not found");

  const prompt = `
    You are an expert Florida B.E.S.T. Mathematics Standards curriculum designer.
    Create a 5-question multiple-choice quiz for the following standard:

    Code: ${standard.code}
    Description: ${standard.description}
    Clarifications: ${standard.clarifications?.join(' ') || 'None provided.'}
    Examples: ${standard.examples?.join(' ') || 'None provided.'}

    The questions must:
    1. Be strictly aligned to the standard.
    2. Incorporate the Florida MTR (Mathematical Thinking and Reasoning) standards where possible.
    3. Include 4 options (A-D) with one correct answer.
    4. Provide a visual animation description that would help explain the concept to a student.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      text: { type: Type.STRING },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Must contain exactly 4 options"
      },
      correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
      explanation: { type: Type.STRING },
      animationDescription: { type: Type.STRING }
    },
    required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: {
        type: Type.ARRAY,
        items: questionSchema
      }
    },
    required: ["standardCode", "questions"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-lite-latest',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a rigid JSON generator for educational content."
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as Quiz;
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    throw error;
  }
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  if (!apiKey) throw new Error("API Key not found");

  const incorrectIndices = results
    .map((r, i) => (!r.isCorrect ? i : -1))
    .filter(i => i !== -1);

  const incorrectQuestionsText = incorrectIndices.map(i => {
    const q = questions[i];
    const r = results[i];
    return `Question: ${q.text} \n Correct Answer: ${q.options[q.correctAnswerIndex]} \n Student Selected: ${q.options[r.selectedOptionIndex]}`;
  }).join('\n---\n');

  const prompt = `
    Analyze the following student performance on a quiz for Florida Standard ${standard.code}: ${standard.description}.

    The student got ${questions.length - incorrectIndices.length} out of ${questions.length} correct.

    Here are the specific mistakes made:
    ${incorrectQuestionsText}

    Based on these mistakes, diagnose the learning gaps. Classify them into:
    - Conceptual Understanding
    - Procedural Fluency
    - Computational Error

    Provide a confidence score (0-100) for your diagnosis.
  `;

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "confidenceScore", "summary"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-lite-latest',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GapAnalysis;
  } catch (error) {
    console.error("Gap Analysis Error:", error);
    throw error;
  }
};

export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  if (!apiKey) throw new Error("API Key not found");

  const prompt = `
    Create a remedial lesson plan consisting of 5-7 slides for Florida Standard ${standard.code}.
    Focus specifically on these identified gaps:
    ${analysis.identifiedGaps.map(g => `- ${g.gapType}: ${g.description}`).join('\n')}

    The slides should follow this progression:
    1. Learning Objective (Clear & Student-friendly)
    2. Concept Visualization (Description of visual)
    3. Worked Example (Step-by-step)
    4. Common Pitfalls (Based on the gaps)
    5. Guided Practice
    6. Independent Practice

    Each slide needs a title, markdown content, visual description, and key vocabulary.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING },
      visualDescription: { type: Type.STRING },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slides: { type: Type.ARRAY, items: slideSchema }
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-lite-latest',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data.slides as RemedialSlide[];
  } catch (error) {
    console.error("Slide Generation Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { GradeLevel, Standard } from '../types';
import { FLORIDA_STANDARDS } from '../constants';
import { BookOpen, Sparkles } from 'lucide-react';

interface Props {
  onGenerate: (standard: Standard) => void;
  isLoading: boolean;
}

const QuizGenerator: React.FC<Props> = ({ onGenerate, isLoading }) => {
  const [selectedGrade, setSelectedGrade] = useState<GradeLevel | ''>('');
  const [selectedStandardCode, setSelectedStandardCode] = useState<string>('');

  const filteredStandards = FLORIDA_STANDARDS.filter(s => s.grade === selectedGrade);

  const handleGenerate = () => {
    const standard = FLORIDA_STANDARDS.find(s => s.code === selectedStandardCode);
    if (standard) {
      onGenerate(standard);
    }
  };

  return (
    <div className="max-w-2xl mx-auto bg-white rounded-2xl shadow-xl p-8 border border-slate-100">
      <div className="text-center mb-8">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-blue-100 mb-4">
          <BookOpen className="w-8 h-8 text-blue-600" />
        </div>
        <h2 className="text-3xl font-bold text-slate-800">New Quiz</h2>
        <p className="text-slate-500 mt-2">Select a grade and standard to generate a custom assessment aligned with Florida B.E.S.T.</p>
      </div>

      <div className="space-y-6">
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">Grade Level</label>
          <select 
            className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white transition-shadow"
            value={selectedGrade}
            onChange={(e) => {
              setSelectedGrade(e.target.value as GradeLevel);
              setSelectedStandardCode('');
            }}
          >
            <option value="">Select Grade</option>
            {Object.values(GradeLevel).map(grade => (
              <option key={grade} value={grade}>{grade}</option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">Standard</label>
          <select 
            className="w-full px-4 py-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white transition-shadow disabled:bg-slate-50 disabled:text-slate-400"
            value={selectedStandardCode}
            onChange={(e) => setSelectedStandardCode(e.target.value)}
            disabled={!selectedGrade}
          >
            <option value="">Select Standard</option>
            {filteredStandards.map(std => (
              <option key={std.code} value={std.code}>
                {std.code}: {std.description.substring(0, 60)}...
              </option>
            ))}
          </select>
        </div>

        {selectedStandardCode && (
          <div className="bg-blue-50 p-4 rounded-lg border border-blue-100 text-sm text-blue-800">
            <strong>Selected Standard:</strong> {FLORIDA_STANDARDS.find(s => s.code === selectedStandardCode)?.description}
          </div>
        )}

        <button
          onClick={handleGenerate}
          disabled={!selectedStandardCode || isLoading}
          className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-semibold py-4 rounded-xl shadow-lg hover:shadow-xl hover:from-blue-700 hover:to-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center gap-2"
        >
          {isLoading ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
              Generating...
            </>
          ) : (
            <>
              <Sparkles className="w-5 h-5" />
              Generate Quiz with AI
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default QuizGenerator;

import React, { useState, useEffect } from 'react';
import { Quiz, QuizResult } from '../types';
import { CheckCircle, XCircle, ArrowRight, Clock } from 'lucide-react';

interface Props {
  quiz: Quiz;
  onComplete: (results: QuizResult[]) => void;
}

const QuizTaker: React.FC<Props> = ({ quiz, onComplete }) => {
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [results, setResults] = useState<QuizResult[]>([]);
  const [startTime, setStartTime] = useState(Date.now());
  const [showFeedback, setShowFeedback] = useState(false);

  useEffect(() => {
    setStartTime(Date.now());
  }, [currentQuestionIdx]);

  const handleSelect = (idx: number) => {
    if (showFeedback) return;
    setSelectedOption(idx);
  };

  const handleSubmitAnswer = () => {
    if (selectedOption === null) return;

    const timeTaken = (Date.now() - startTime) / 1000;
    const isCorrect = selectedOption === quiz.questions[currentQuestionIdx].correctAnswerIndex;

    const result: QuizResult = {
      questionIndex: currentQuestionIdx,
      selectedOptionIndex: selectedOption,
      isCorrect,
      timeTaken
    };

    const newResults = [...results, result];
    setResults(newResults);
    setShowFeedback(true);
  };

  const handleNext = () => {
    if (currentQuestionIdx < quiz.questions.length - 1) {
      setCurrentQuestionIdx(curr => curr + 1);
      setSelectedOption(null);
      setShowFeedback(false);
    } else {
      onComplete(results);
    }
  };

  const question = quiz.questions[currentQuestionIdx];
  const progress = ((currentQuestionIdx) / quiz.questions.length) * 100;

  return (
    <div className="max-w-3xl mx-auto">
      {/* Progress Bar */}
      <div className="w-full bg-slate-200 h-2 rounded-full mb-8 overflow-hidden">
        <div 
          className="bg-blue-600 h-2 rounded-full transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>

      <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
        {/* Header */}
        <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <span className="text-sm font-semibold text-slate-500 uppercase tracking-wide">
            Question {currentQuestionIdx + 1} of {quiz.questions.length}
          </span>
          <span className="text-sm font-medium text-slate-400 flex items-center gap-1">
            <Clock className="w-4 h-4" />
            Standard: {quiz.standardCode}
          </span>
        </div>

        {/* Content */}
        <div className="p-8">
          <h3 className="text-xl font-bold text-slate-900 mb-6 leading-relaxed">
            {question.text}
          </h3>

          <div className="space-y-4">
            {question.options.map((option, idx) => {
              let btnClass = "w-full p-4 rounded-xl border-2 text-left transition-all relative flex items-center justify-between ";

              if (showFeedback) {
                if (idx === question.correctAnswerIndex) {
                  btnClass += "border-green-500 bg-green-50 text-green-800";
                } else if (idx === selectedOption && idx !== question.correctAnswerIndex) {
                  btnClass += "border-red-500 bg-red-50 text-red-800";
                } else {
                  btnClass += "border-slate-100 text-slate-400 opacity-50";
                }
              } else {
                if (selectedOption === idx) {
                  btnClass += "border-blue-600 bg-blue-50 text-blue-900 shadow-md ring-2 ring-blue-100";
                } else {
                  btnClass += "border-slate-200 hover:border-blue-300 hover:bg-slate-50 text-slate-700";
                }
              }

              return (
                <button
                  key={idx}
                  onClick={() => handleSelect(idx)}
                  className={btnClass}
                  disabled={showFeedback}
                >
                  <span className="font-medium text-lg">{String.fromCharCode(65 + idx)}. {option}</span>
                  {showFeedback && idx === question.correctAnswerIndex && (
                    <CheckCircle className="w-6 h-6 text-green-600" />
                  )}
                  {showFeedback && idx === selectedOption && idx !== question.correctAnswerIndex && (
                    <XCircle className="w-6 h-6 text-red-600" />
                  )}
                </button>
              );
            })}
          </div>

          {showFeedback && (
            <div className="mt-8 animate-fade-in">
              <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-100">
                <h4 className="font-semibold text-indigo-900 mb-2 flex items-center gap-2">
                  Explanation
                </h4>
                <p className="text-indigo-800 leading-relaxed mb-4">{question.explanation}</p>

                <div className="bg-white p-4 rounded-lg border border-indigo-100">
                  <span className="text-xs font-bold text-indigo-400 uppercase tracking-wider mb-1 block">Visual Concept</span>
                  <p className="text-sm text-slate-600 italic">
                    "{question.animationDescription}"
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-8 py-6 bg-slate-50 border-t border-slate-100 flex justify-end">
          {!showFeedback ? (
            <button
              onClick={handleSubmitAnswer}
              disabled={selectedOption === null}
              className="bg-blue-600 text-white px-8 py-3 rounded-xl font-semibold shadow-lg hover:bg-blue-700 disabled:opacity-50 disabled:shadow-none transition-all"
            >
              Check Answer
            </button>
          ) : (
            <button
              onClick={handleNext}
              className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-semibold shadow-lg hover:bg-indigo-700 flex items-center gap-2 transition-all"
            >
              {currentQuestionIdx === quiz.questions.length - 1 ? "Finish Quiz" : "Next Question"}
              <ArrowRight className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default QuizTaker;

import React from 'react';
import { GapAnalysis as GapAnalysisType, GapType } from '../types';
import { AlertTriangle, Brain, Calculator, Wrench, BarChart2, BookOpen } from 'lucide-react';

interface Props {
  analysis: GapAnalysisType;
  onStartRemediation: () => void;
  isLoadingSlides: boolean;
}

const GapAnalysis: React.FC<Props> = ({ analysis, onStartRemediation, isLoadingSlides }) => {
  const getIcon = (type: GapType) => {
    switch (type) {
      case GapType.Conceptual: return <Brain className="w-6 h-6 text-purple-600" />;
      case GapType.Procedural: return <Wrench className="w-6 h-6 text-orange-600" />;
      case GapType.Computational: return <Calculator className="w-6 h-6 text-red-600" />;
      default: return <AlertTriangle className="w-6 h-6 text-slate-600" />;
    }
  };

  const getColor = (type: GapType) => {
    switch (type) {
      case GapType.Conceptual: return "bg-purple-50 border-purple-100 text-purple-900";
      case GapType.Procedural: return "bg-orange-50 border-orange-100 text-orange-900";
      case GapType.Computational: return "bg-red-50 border-red-100 text-red-900";
      default: return "bg-slate-50 border-slate-100 text-slate-900";
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div className="text-center">
        <h2 className="text-3xl font-bold text-slate-900 mb-2">Learning Gap Analysis</h2>
        <p className="text-slate-500">AI-Diagnosis based on your quiz performance for standard {analysis.standardCode}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col items-center justify-center">
          <div className="radial-progress text-blue-600 text-2xl font-bold" style={{"--value": analysis.confidenceScore, "--size": "6rem"} as any}>
            {analysis.confidenceScore}%
          </div>
          <p className="mt-4 text-sm font-medium text-slate-500">AI Confidence Score</p>
        </div>

        <div className="md:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
            <BarChart2 className="w-5 h-5 text-blue-500" />
            Performance Summary
          </h3>
          <p className="text-slate-600 leading-relaxed">{analysis.summary}</p>
        </div>
      </div>

      <div className="space-y-4">
        <h3 className="text-xl font-bold text-slate-900">Identified Gaps</h3>
        {analysis.identifiedGaps.length === 0 ? (
          <div className="p-8 bg-green-50 rounded-2xl border border-green-100 text-center">
            <p className="text-green-800 font-medium text-lg">No significant gaps identified! Great job!</p>
          </div>
        ) : (
          analysis.identifiedGaps.map((gap, idx) => (
            <div key={idx} className={`p-6 rounded-2xl border flex gap-4 ${getColor(gap.gapType)}`}>
              <div className="mt-1 bg-white p-2 rounded-full h-fit shadow-sm">
                {getIcon(gap.gapType)}
              </div>
              <div>
                <h4 className="font-bold text-lg mb-1">{gap.gapType}</h4>
                <p className="opacity-90 mb-3">{gap.description}</p>
                <div className="flex gap-2">
                  {gap.relatedQuestions.map(qIdx => (
                    <span key={qIdx} className="px-2 py-1 bg-white/60 rounded text-xs font-bold uppercase tracking-wide">
                      Q{qIdx + 1}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      <div className="flex justify-center pt-8">
        <button
          onClick={onStartRemediation}
          disabled={isLoadingSlides || analysis.identifiedGaps.length === 0}
          className="bg-gradient-to-r from-emerald-500 to-teal-600 text-white px-10 py-4 rounded-xl font-bold shadow-lg hover:shadow-xl hover:scale-105 transform transition-all disabled:opacity-50 disabled:hover:scale-100 disabled:cursor-not-allowed flex items-center gap-3"
        >
          {isLoadingSlides ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
              Building Lesson Plan...
            </>
          ) : (
            <>
              <BookOpen className="w-6 h-6" />
              Generate Remedial Slides
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default GapAnalysis;

import React, { useState } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, Book, Lightbulb, PenTool, AlertOctagon } from 'lucide-react';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const slide = slides[currentSlide];

  // Helper to determine icon based on title keywords (naive but effective for visuals)
  const getSlideIcon = (title: string) => {
    const t = title.toLowerCase();
    if (t.includes('objective')) return <Book className="w-6 h-6 text-blue-500" />;
    if (t.includes('visual') || t.includes('concept')) return <Lightbulb className="w-6 h-6 text-yellow-500" />;
    if (t.includes('practice') || t.includes('example')) return <PenTool className="w-6 h-6 text-green-500" />;
    if (t.includes('mistake') || t.includes('pitfall')) return <AlertOctagon className="w-6 h-6 text-red-500" />;
    return <Book className="w-6 h-6 text-slate-500" />;
  };

  return (
    <div className="max-w-5xl mx-auto h-[calc(100vh-100px)] flex flex-col">
      <div className="flex-1 bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col relative">

        {/* Top Bar */}
        <div className="bg-slate-50 border-b border-slate-100 px-8 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-sm font-bold">
              Slide {currentSlide + 1}/{slides.length}
            </span>
            <span className="text-slate-400">|</span>
            <h3 className="font-semibold text-slate-700">{slide.title}</h3>
          </div>
          <div className="flex gap-2">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`h-1.5 rounded-full transition-all duration-300 ${idx === currentSlide ? 'w-8 bg-blue-600' : 'w-2 bg-slate-200'}`} 
              />
            ))}
          </div>
        </div>

        {/* Slide Content */}
        <div className="flex-1 p-12 overflow-y-auto no-scrollbar flex flex-col md:flex-row gap-12">

          {/* Left Column: Text Content */}
          <div className="flex-1 space-y-6">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-3 bg-slate-50 rounded-xl">
                {getSlideIcon(slide.title)}
              </div>
              <h2 className="text-3xl font-bold text-slate-900">{slide.title}</h2>
            </div>

            <div className="prose prose-slate prose-lg max-w-none text-slate-600 leading-relaxed whitespace-pre-wrap">
              {slide.content}
            </div>

            {slide.vocabulary.length > 0 && (
              <div className="mt-8 bg-indigo-50 p-6 rounded-xl border-l-4 border-indigo-500">
                <h4 className="text-sm font-bold text-indigo-900 uppercase tracking-wide mb-3">Key Vocabulary</h4>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((vocab, i) => (
                    <span key={i} className="bg-white px-3 py-1 rounded-md text-indigo-700 text-sm font-medium border border-indigo-100 shadow-sm">
                      {vocab}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column: Visual Description / Graphic Placeholder */}
          <div className="flex-1 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200 p-8 flex flex-col items-center justify-center text-center relative overflow-hidden group">
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/graphy.png')] opacity-10"></div>
            <div className="relative z-10 max-w-sm">
              <div className="w-20 h-20 bg-white rounded-full shadow-md flex items-center justify-center mx-auto mb-6">
                <Lightbulb className="w-10 h-10 text-yellow-400" />
              </div>
              <h4 className="font-bold text-slate-800 mb-2">Visual Explanation</h4>
              <p className="text-slate-500 italic text-sm leading-relaxed">
                "{slide.visualDescription}"
              </p>
              <div className="mt-6 text-xs text-slate-400 uppercase tracking-wider">
                Note: In a full production app, this would render dynamic D3/Recharts visualizations.
              </div>
            </div>
          </div>

        </div>

        {/* Bottom Navigation */}
        <div className="p-6 bg-white border-t border-slate-100 flex justify-between items-center">
          <button
            onClick={prevSlide}
            disabled={currentSlide === 0}
            className="flex items-center gap-2 px-6 py-3 rounded-lg text-slate-600 hover:bg-slate-50 disabled:opacity-30 disabled:hover:bg-white font-medium transition-colors"
          >
            <ChevronLeft className="w-5 h-5" />
            Previous
          </button>

          {currentSlide === slides.length - 1 ? (
            <button
              onClick={onRestart}
              className="bg-slate-900 text-white px-8 py-3 rounded-lg font-bold hover:bg-slate-800 transition-colors shadow-lg"
            >
              Return to Home
            </button>
          ) : (
            <button
              onClick={nextSlide}
              className="bg-blue-600 text-white px-8 py-3 rounded-lg font-bold hover:bg-blue-700 transition-colors shadow-lg flex items-center gap-2"
            >
              Next Slide
              <ChevronRight className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default RemedialSlides;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { AppState, Standard, Quiz, QuizResult, GapAnalysis, RemedialSlide } from './types';
import { generateQuiz, analyzeGaps, generateRemedialSlides } from './services/geminiService';
import QuizGenerator from './components/QuizGenerator';
import QuizTaker from './components/QuizTaker';
import GapAnalysisComponent from './components/GapAnalysis';
import RemedialSlides from './components/RemedialSlides';
import { GraduationCap } from 'lucide-react';

function App() {
  const [state, setState] = useState<AppState>({
    view: 'setup',
    selectedStandard: null,
    quiz: null,
    quizResults: [],
    analysis: null,
    slides: [],
    loading: false,
    loadingMessage: '',
  });

  const handleGenerateQuiz = async (standard: Standard) => {
    setState(prev => ({ ...prev, loading: true, loadingMessage: 'Generating Quiz Questions...', selectedStandard: standard }));
    try {
      const quiz = await generateQuiz(standard);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        quiz, 
        view: 'quiz',
        quizResults: [] // reset results
      }));
    } catch (error) {
      alert("Failed to generate quiz. Please check API Key configuration.");
      setState(prev => ({ ...prev, loading: false }));
    }
  };

  const handleQuizComplete = async (results: QuizResult[]) => {
    if (!state.quiz || !state.selectedStandard) return;

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Analyzing Performance & Identifying Gaps...', 
      quizResults: results 
    }));

    try {
      const analysis = await analyzeGaps(state.selectedStandard, state.quiz.questions, results);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        analysis, 
        view: 'analysis' 
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({ ...prev, loading: false }));
    }
  };

  const handleStartRemediation = async () => {
    if (!state.analysis || !state.selectedStandard) return;

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Creating Personalized Learning Slides...' 
    }));

    try {
      const slides = await generateRemedialSlides(state.selectedStandard, state.analysis);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        slides, 
        view: 'remedial' 
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({ ...prev, loading: false }));
    }
  };

  const restart = () => {
    setState({
      view: 'setup',
      selectedStandard: null,
      quiz: null,
      quizResults: [],
      analysis: null,
      slides: [],
      loading: false,
      loadingMessage: '',
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={restart}>
            <div className="bg-blue-600 p-2 rounded-lg">
              <GraduationCap className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-indigo-700">
              Florida B.E.S.T. Math Architect
            </h1>
          </div>
          {state.selectedStandard && (
            <div className="text-sm font-medium text-slate-500 bg-slate-100 px-3 py-1 rounded-full hidden sm:block">
              {state.selectedStandard.code}
            </div>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {state.loading ? (
          <div className="flex flex-col items-center justify-center h-[60vh] animate-fade-in">
            <div className="relative w-24 h-24 mb-8">
              <div className="absolute inset-0 border-4 border-slate-200 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">{state.loadingMessage}</h2>
            <p className="text-slate-500">Powered by Gemini AI</p>
          </div>
        ) : (
          <>
            {state.view === 'setup' && (
              <div className="animate-slide-up">
                <QuizGenerator onGenerate={handleGenerateQuiz} isLoading={state.loading} />
              </div>
            )}

            {state.view === 'quiz' && state.quiz && (
              <div className="animate-slide-up">
                <QuizTaker quiz={state.quiz} onComplete={handleQuizComplete} />
              </div>
            )}

            {state.view === 'analysis' && state.analysis && (
              <div className="animate-slide-up">
                <GapAnalysisComponent 
                  analysis={state.analysis} 
                  onStartRemediation={handleStartRemediation} 
                  isLoadingSlides={state.loading} 
                />
              </div>
            )}

            {state.view === 'remedial' && (
              <div className="animate-fade-in">
                <RemedialSlides slides={state.slides} onRestart={restart} />
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

