                    </div>
                  )}
                  {selectedStandard.clarifications && (
                    <div className="text-xs">
                      <span className="font-bold text-indigo-800 uppercase tracking-wide">Clarification:</span>
                      <p className="text-slate-600 mt-1 pl-2 border-l-2 border-indigo-300">
                        {selectedStandard.clarifications[0]}
