import React, { useState } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, Book, Lightbulb, PenTool, AlertOctagon, RotateCcw } from 'lucide-react';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const slide = slides[currentSlide];

  // Helper to determine icon based on title keywords
  const getSlideIcon = (title: string) => {
    const t = title.toLowerCase();
    if (t.includes('definition') || t.includes('concept')) return <Book className="w-6 h-6 text-blue-500" />;
    if (t.includes('visual')) return <Lightbulb className="w-6 h-6 text-yellow-500" />;
    if (t.includes('walkthrough') || t.includes('step')) return <PenTool className="w-6 h-6 text-purple-500" />;
    if (t.includes('gap') || t.includes('fix')) return <AlertOctagon className="w-6 h-6 text-red-500" />;
    return <Book className="w-6 h-6 text-slate-500" />;
  };

  return (
    <div className="max-w-6xl mx-auto h-[calc(100vh-100px)] flex flex-col">
      <div className="flex-1 bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col relative">

        {/* Top Bar */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-sm font-bold shadow-sm">
              Slide {currentSlide + 1} of {slides.length}
            </span>
            <span className="text-slate-300 text-xl font-light">|</span>
            <h3 className="font-semibold text-slate-700 truncate max-w-md">{slide.title}</h3>
          </div>
          <div className="flex gap-2">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`h-2 rounded-full transition-all duration-300 ${idx === currentSlide ? 'w-10 bg-blue-600' : 'w-2 bg-slate-200'}`} 
              />
            ))}
          </div>
        </div>

        {/* Slide Content */}
        <div className="flex-1 p-0 overflow-hidden flex flex-col md:flex-row">

          {/* Left Column: Instructional Content */}
          <div className="flex-1 p-8 md:p-12 overflow-y-auto no-scrollbar bg-white">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-3 bg-slate-50 rounded-xl shadow-sm border border-slate-100">
                {getSlideIcon(slide.title)}
              </div>
              <h2 className="text-3xl font-bold text-slate-900 leading-tight">{slide.title}</h2>
            </div>

            <div className="prose prose-slate prose-lg max-w-none text-slate-600 leading-relaxed">
              {/* Simple Markdown Rendering */}
              {slide.content.split('\n').map((line, i) => {
                if (line.startsWith('###')) return <h3 key={i} className="text-lg font-bold text-slate-800 mt-4 mb-2">{line.replace('###', '')}</h3>;
                if (line.startsWith('**')) return <p key={i} className="font-bold text-slate-800 my-2">{line.replace(/\*\*/g, '')}</p>;
                if (line.trim().startsWith('-')) return <li key={i} className="ml-4 list-disc marker:text-blue-500">{line.replace('-', '')}</li>;
                if (line.trim() === '') return <div key={i} className="h-2"></div>;
                return <p key={i} className="mb-2">{line}</p>;
              })}
            </div>

            {slide.vocabulary.length > 0 && (
              <div className="mt-10 pt-6 border-t border-slate-100">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Key Vocabulary</h4>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((vocab, i) => (
                    <span key={i} className="bg-indigo-50 px-3 py-1.5 rounded-lg text-indigo-700 text-sm font-semibold border border-indigo-100">
                      {vocab}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column: Visual Explanation */}
          <div className="flex-1 bg-slate-50 border-l border-slate-200 relative flex flex-col">
             <div className="absolute top-4 right-4 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-xs font-medium text-slate-500 border border-slate-200 z-10">
                AI Generated Visual
             </div>

             <div className="flex-1 flex items-center justify-center p-8 bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] [background-size:16px_16px]">
                {slide.svgVisual ? (
                  <div 
                    className="w-full h-full max-h-[400px] flex items-center justify-center bg-white rounded-2xl shadow-sm border border-slate-200 p-4"
                    dangerouslySetInnerHTML={{ __html: slide.svgVisual }}
                  />
                ) : (
                  <div className="text-center p-8">
                    <div className="w-20 h-20 bg-white rounded-full shadow-sm flex items-center justify-center mx-auto mb-4 border border-slate-100">
                      <Lightbulb className="w-10 h-10 text-yellow-400" />
                    </div>
                    <p className="text-slate-500 font-medium">Visual representation not available.</p>
                  </div>
                )}
             </div>

             <div className="p-6 bg-white border-t border-slate-200">
               <h4 className="font-bold text-slate-800 text-sm mb-2 flex items-center gap-2">
                 <span className="w-2 h-2 rounded-full bg-blue-500"></span>
                 Visual Description
               </h4>
               <p className="text-slate-600 text-sm leading-relaxed italic">
                 "{slide.visualDescription}"
               </p>
             </div>
          </div>

        </div>

        {/* Bottom Navigation */}
        <div className="p-5 bg-white border-t border-slate-100 flex justify-between items-center shrink-0">
          <button
            onClick={prevSlide}
            disabled={currentSlide === 0}
            className="flex items-center gap-2 px-6 py-3 rounded-xl text-slate-600 hover:bg-slate-100 disabled:opacity-30 disabled:hover:bg-white font-semibold transition-all"
          >
            <ChevronLeft className="w-5 h-5" />
            Previous
          </button>

          {currentSlide === slides.length - 1 ? (
            <button
              onClick={onRestart}
              className="bg-slate-900 text-white px-8 py-3 rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg hover:shadow-slate-900/20 flex items-center gap-2"
            >
              <RotateCcw className="w-4 h-4" />
              Finish Lesson
            </button>
          ) : (
            <button
              onClick={nextSlide}
              className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg hover:shadow-blue-600/30 flex items-center gap-2"
            >
              Next Concept
              <ChevronRight className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

