import { GoogleGenAI, Schema, Type } from "@google/genai";
import { Standard, Quiz, GapAnalysis, RemedialSlide, GapType, QuizResult, Question } from '../types';
import { MTR_STANDARDS } from '../constants';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const generateQuiz = async (standard: Standard): Promise<Quiz> => {
  if (!apiKey) throw new Error("API Key not found");

  const prompt = `
    You are an expert Florida B.E.S.T. Mathematics Standards curriculum designer.
    Create a 5-question multiple-choice quiz for the following standard:

    Code: ${standard.code}
    Description: ${standard.description}
    Clarifications: ${standard.clarifications?.join(' ') || 'None provided.'}
    Examples: ${standard.examples?.join(' ') || 'None provided.'}

    The questions must:
    1. Be strictly aligned to the standard.
    2. Incorporate the Florida MTR (Mathematical Thinking and Reasoning) standards where possible.
    3. Include 4 options (A-D) with one correct answer.
    4. Provide a visual animation description that would help explain the concept to a student.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      text: { type: Type.STRING },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Must contain exactly 4 options"
      },
      correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
      explanation: { type: Type.STRING },
      animationDescription: { type: Type.STRING }
    },
    required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: {
        type: Type.ARRAY,
        items: questionSchema
      }
    },
    required: ["standardCode", "questions"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a rigid JSON generator for educational content."
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as Quiz;
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    throw error;
  }
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  if (!apiKey) throw new Error("API Key not found");

  // Pass comprehensive question performance data to the AI
  const detailedAnalysis = questions.map((q, i) => {
    const r = results[i];
    return `
      Question ${i + 1}: ${q.text}
      Options: ${q.options.join(', ')}
      Correct Answer: ${q.options[q.correctAnswerIndex]}
      Student Selected: ${q.options[r.selectedOptionIndex]}
      Is Correct: ${r.isCorrect}
    `;
  }).join('\n---\n');

  const prompt = `
    Analyze the following student performance on a quiz for Florida Standard ${standard.code}: ${standard.description}.

    Detailed Performance:
    ${detailedAnalysis}

    Tasks:
    1. **Sub-skill Analysis**: Break down the standard into 2-4 distinct sub-skills or component skills relevant to these specific questions. For each sub-skill, determine how many questions related to it and how many were correct.
    2. **Misconception Detection**: For incorrect answers, analyze the specific distractor (wrong option) selected by the student. Does it indicate a common mathematical misconception (e.g., "adding denominators", "confusing perimeter with area", "place value alignment error")?
    3. **Gap Diagnosis**: Aggregate the errors into learning gaps.

    Provide a confidence score (0-100) for your diagnosis.
  `;

  const subSkillSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      description: { type: Type.STRING },
      correctCount: { type: Type.INTEGER },
      totalCount: { type: Type.INTEGER }
    },
    required: ["name", "description", "correctCount", "totalCount"]
  };

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } },
      misconception: { type: Type.STRING, description: "The specific misconception identified from the wrong answer chosen." }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      subSkills: { type: Type.ARRAY, items: subSkillSchema },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "subSkills", "confidenceScore", "summary"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GapAnalysis;
  } catch (error) {
    console.error("Gap Analysis Error:", error);
    throw error;
  }
};

export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  if (!apiKey) throw new Error("API Key not found");

  const prompt = `
    You are a compassionate and skilled mathematics tutor.
    Create a remedial lesson plan consisting of 5-7 slides for Florida Standard ${standard.code}.

    The student has the following learning gaps:
    ${analysis.identifiedGaps.map(g => `- ${g.gapType}: ${g.description} ${g.misconception ? `(Misconception: ${g.misconception})` : ''}`).join('\n')}

    CRITICAL INSTRUCTIONS FOR CONTENT:
    1.  **TEACH, DON'T JUST TEST**: The 'content' field must contain EXPLANATIONS, not just problems. Use analogies, clear definitions, and step-by-step logic.
    2.  **VISUALS**: For the 'svgVisual' field, generate valid, simple SVG code (starting with <svg> tag) that visually explains the concept (e.g., number lines, area models, fraction circles, geometric shapes). Use colors like #3b82f6 (blue), #ef4444 (red), #10b981 (green). 
    3.  **Progression**:
        - Slide 1: **Concept Definition**: What is this concept? Why does it matter? (No problems yet)
        - Slide 2: **Visual Explanation**: Explain how to visualize it.
        - Slide 3: **Step-by-Step Walkthrough**: Solve a problem completely, explaining every step.
        - Slide 4: **Fixing the Gap**: Directly address the specific misconceptions identified: ${analysis.identifiedGaps.map(g => g.misconception).filter(Boolean).join(', ')}. Explain why the wrong thinking happens and how to correct it.
        - Slide 5: **Guided Practice**: A problem with a hint.

    For the 'content' field, use Markdown for formatting (bolding key terms, using bullet points).
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING, description: "Detailed instructional text, explanations, and analogies. Use Markdown." },
      visualDescription: { type: Type.STRING, description: "Text description of the visual." },
      svgVisual: { type: Type.STRING, description: "A complete, valid SVG string starting with <svg> and ending with </svg>. Viewbox should be approx 0 0 400 300. Keep it simple and clear." },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slides: { type: Type.ARRAY, items: slideSchema }
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data.slides as RemedialSlide[];
  } catch (error) {
    console.error("Slide Generation Error:", error);
    throw error;
  }
};

import React from 'react';
import { GapAnalysis as GapAnalysisType, GapType } from '../types';
import { AlertTriangle, Brain, Calculator, Wrench, BarChart2, BookOpen, Target, AlertCircle } from 'lucide-react';

interface Props {
  analysis: GapAnalysisType;
  onStartRemediation: () => void;
  isLoadingSlides: boolean;
}

const GapAnalysis: React.FC<Props> = ({ analysis, onStartRemediation, isLoadingSlides }) => {
  const getIcon = (type: GapType) => {
    switch (type) {
      case GapType.Conceptual: return <Brain className="w-6 h-6 text-purple-600" />;
      case GapType.Procedural: return <Wrench className="w-6 h-6 text-orange-600" />;
      case GapType.Computational: return <Calculator className="w-6 h-6 text-red-600" />;
      default: return <AlertTriangle className="w-6 h-6 text-slate-600" />;
    }
  };

  const getColor = (type: GapType) => {
    switch (type) {
      case GapType.Conceptual: return "bg-purple-50 border-purple-100 text-purple-900";
      case GapType.Procedural: return "bg-orange-50 border-orange-100 text-orange-900";
      case GapType.Computational: return "bg-red-50 border-red-100 text-red-900";
      default: return "bg-slate-50 border-slate-100 text-slate-900";
    }
  };

  const getScoreColor = (correct: number, total: number) => {
    const percentage = correct / total;
    if (percentage >= 0.8) return 'text-green-600';
    if (percentage >= 0.5) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getProgressBarColor = (correct: number, total: number) => {
    const percentage = correct / total;
    if (percentage >= 0.8) return 'bg-green-500';
    if (percentage >= 0.5) return 'bg-yellow-500';
    return 'bg-red-500';
  };

  return (
    <div className="max-w-5xl mx-auto space-y-8 animate-fade-in">
      <div className="text-center">
        <h2 className="text-3xl font-bold text-slate-900 mb-2">Learning Gap Analysis</h2>
        <p className="text-slate-500">AI-Diagnosis based on your quiz performance for standard {analysis.standardCode}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col items-center justify-center">
          <div className="radial-progress text-blue-600 text-3xl font-bold" style={{"--value": analysis.confidenceScore, "--size": "7rem"} as any}>
            {analysis.confidenceScore}%
          </div>
          <p className="mt-4 text-sm font-medium text-slate-500">AI Confidence Score</p>
        </div>

        <div className="md:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
            <BarChart2 className="w-5 h-5 text-blue-500" />
            Performance Summary
          </h3>
          <p className="text-slate-600 leading-relaxed text-lg">{analysis.summary}</p>
        </div>
      </div>

      {/* Sub-skills Section */}
      {analysis.subSkills && analysis.subSkills.length > 0 && (
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-6 flex items-center gap-2">
            <Target className="w-5 h-5 text-indigo-500" />
            Skill Breakdown
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {analysis.subSkills.map((skill, idx) => (
              <div key={idx} className="bg-slate-50 p-5 rounded-xl border border-slate-100 hover:border-blue-200 transition-colors">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <h4 className="font-bold text-slate-700">{skill.name}</h4>
                    <p className="text-xs text-slate-500 mt-1">{skill.description}</p>
                  </div>
                  <span className={`text-lg font-bold ${getScoreColor(skill.correctCount, skill.totalCount)}`}>
                    {skill.correctCount}/{skill.totalCount}
                  </span>
                </div>
                {/* Progress bar */}
                <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-full rounded-full ${getProgressBarColor(skill.correctCount, skill.totalCount)} transition-all duration-1000`}
                    style={{ width: `${(skill.correctCount / skill.totalCount) * 100}%` }}
                  ></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="space-y-4">
        <h3 className="text-xl font-bold text-slate-900 flex items-center gap-2">
          <AlertCircle className="w-5 h-5 text-red-500" />
          Diagnosed Learning Gaps
        </h3>

        {analysis.identifiedGaps.length === 0 ? (
          <div className="p-8 bg-green-50 rounded-2xl border border-green-100 text-center">
            <p className="text-green-800 font-medium text-lg">No significant gaps identified! Great job mastering this standard.</p>
          </div>
        ) : (
          <div className="grid gap-4">
            {analysis.identifiedGaps.map((gap, idx) => (
              <div key={idx} className={`p-6 rounded-2xl border flex flex-col md:flex-row gap-4 ${getColor(gap.gapType)}`}>
                <div className="flex-shrink-0 mt-1">
                   <div className="bg-white/80 p-3 rounded-full h-fit shadow-sm backdrop-blur-sm">
                    {getIcon(gap.gapType)}
                  </div>
                </div>
                <div className="flex-1">
                  <div className="flex flex-wrap items-center gap-2 mb-2">
                    <h4 className="font-bold text-lg">{gap.gapType}</h4>
                    {gap.relatedQuestions.map(qIdx => (
                      <span key={qIdx} className="px-2 py-0.5 bg-white/60 rounded text-xs font-bold uppercase tracking-wide border border-black/5">
                        Q{qIdx + 1}
                      </span>
                    ))}
                  </div>
                  <p className="opacity-90 mb-4 leading-relaxed">{gap.description}</p>

                  {gap.misconception && (
                    <div className="bg-white/60 p-4 rounded-xl border border-black/5">
                      <span className="text-xs font-bold uppercase tracking-wider opacity-60 flex items-center gap-1 mb-1">
                        <AlertTriangle className="w-3 h-3" />
                        Detected Misconception
                      </span>
                      <p className="font-medium italic">"{gap.misconception}"</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="flex justify-center pt-8 pb-12">
        <button
          onClick={onStartRemediation}
          disabled={isLoadingSlides || analysis.identifiedGaps.length === 0}
          className="bg-gradient-to-r from-emerald-500 to-teal-600 text-white px-10 py-4 rounded-xl font-bold shadow-lg hover:shadow-xl hover:scale-[1.02] active:scale-[0.98] transform transition-all disabled:opacity-50 disabled:hover:scale-100 disabled:cursor-not-allowed flex items-center gap-3 border border-emerald-400/20"
        >
          {isLoadingSlides ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
              Building Personalized Lesson Plan...
            </>
          ) : (
            <>
              <BookOpen className="w-6 h-6" />
              Generate Remedial Slides
            </>
          )}
        </button>
      </div>
    </div>
  );
};

