export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  if (!apiKey) throw new Error("API Key not found");

  const prompt = `
    You are an expert K-12 mathematics intervention specialist.
    Create a highly effective remedial lesson plan (5-7 slides) for Florida Standard ${standard.code}.

    Target Audience: Student with the following specific gaps:
    ${analysis.identifiedGaps.map(g => `- [${g.gapType}] ${g.description} ${g.misconception ? `(Detected Misconception: ${g.misconception})` : ''}`).join('\n')}

    **CONTENT REQUIREMENTS:**
    1.  **Directly Address Misconceptions**: Explicitly state "You might think X, but actually Y..." referring to the specific misconceptions listed above.
    2.  **Step-by-Step Worked Examples**: When solving a problem, break it down into numbered steps (Step 1, Step 2...). Explain the *why* behind each step.
    3.  **Mathematical Precision**: Use correct terminology (e.g., "numerator", "coefficient", "perimeter") but explain it simply first.
    4.  **Formatting**: Use Markdown. Bold key terms. Use code blocks for equations if needed.

    **VISUAL REQUIREMENTS (SVG):**
    1.  **High-Quality Educational Vector Art**: Create a 'svgVisual' string that is detailed and illustrative.
    2.  **Responsive**: Do NOT set absolute width/height on the root <svg> tag. Use viewBox="0 0 600 400" (3:2 aspect ratio).
    3.  **Interactive/Animated**: Use SVG animations (e.g., <animate>, <set>, <animateTransform>) to show movement (e.g., a number line jump, a fraction piece filling in, a shape rotating).
    4.  **Style**: Use a clean, modern palette: Blue (#3b82f6), Green (#10b981), Red for errors (#ef4444), Slate (#64748b).
    5.  **Context**: The visual must directly illustrate the concept or the step-by-step process described in the text.

    **SLIDE PROGRESSION:**
    1.  **Hook & Definition**: Define the concept clearly.
    2.  **Visual Mental Model**: How should they picture this in their head?
    3.  **Addressing the Error**: "Watch out for this..." (Address the gap/misconception).
    4.  **Step-by-Step Walkthrough**: A full example with numbered steps.
    5.  **Guided Practice**: A try-it-yourself moment.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING, description: "Instructional text, step-by-step logic, and analogies using Markdown." },
      visualDescription: { type: Type.STRING, description: "Description of what the SVG depicts." },
      svgVisual: { type: Type.STRING, description: "Complete, valid, animated SVG string starting with <svg> and ending with </svg>. ViewBox 0 0 600 400." },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slides: { type: Type.ARRAY, items: slideSchema }
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data.slides as RemedialSlide[];
  } catch (error) {
    console.error("Slide Generation Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, Book, Lightbulb, PenTool, AlertOctagon, RotateCcw } from 'lucide-react';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const slide = slides[currentSlide];

  // Helper to determine icon based on title keywords
  const getSlideIcon = (title: string) => {
    const t = title.toLowerCase();
    if (t.includes('definition') || t.includes('concept')) return <Book className="w-6 h-6 text-blue-500" />;
    if (t.includes('visual')) return <Lightbulb className="w-6 h-6 text-yellow-500" />;
    if (t.includes('walkthrough') || t.includes('step')) return <PenTool className="w-6 h-6 text-purple-500" />;
    if (t.includes('gap') || t.includes('fix') || t.includes('error')) return <AlertOctagon className="w-6 h-6 text-red-500" />;
    return <Book className="w-6 h-6 text-slate-500" />;
  };

  return (
    <div className="max-w-6xl mx-auto h-[calc(100vh-100px)] flex flex-col">
      <div className="flex-1 bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col relative">

        {/* Top Bar */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-sm font-bold shadow-sm">
              Slide {currentSlide + 1} of {slides.length}
            </span>
            <span className="text-slate-300 text-xl font-light">|</span>
            <h3 className="font-semibold text-slate-700 truncate max-w-md">{slide.title}</h3>
          </div>
          <div className="flex gap-2">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`h-2 rounded-full transition-all duration-300 ${idx === currentSlide ? 'w-10 bg-blue-600' : 'w-2 bg-slate-200'}`} 
              />
            ))}
          </div>
        </div>

        {/* Slide Content */}
        <div className="flex-1 p-0 overflow-hidden flex flex-col md:flex-row">

          {/* Left Column: Instructional Content */}
          <div className="flex-1 p-8 md:p-12 overflow-y-auto no-scrollbar bg-white order-2 md:order-1">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-3 bg-slate-50 rounded-xl shadow-sm border border-slate-100">
                {getSlideIcon(slide.title)}
              </div>
              <h2 className="text-3xl font-bold text-slate-900 leading-tight">{slide.title}</h2>
            </div>

            <div className="prose prose-slate prose-lg max-w-none text-slate-600 leading-relaxed">
              {/* Simple Markdown Rendering */}
              {slide.content.split('\n').map((line, i) => {
                if (line.startsWith('###')) return <h3 key={i} className="text-lg font-bold text-slate-800 mt-6 mb-3 border-b border-slate-100 pb-2">{line.replace('###', '')}</h3>;
                if (line.startsWith('##')) return <h2 key={i} className="text-xl font-bold text-slate-900 mt-6 mb-3">{line.replace('##', '')}</h2>;
                if (line.trim().match(/^\d+\./)) {
                  // Numbered lists for step-by-step
                   return <div key={i} className="flex gap-3 mb-3 ml-1">
                      <span className="flex-shrink-0 w-6 h-6 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-sm font-bold mt-0.5">{line.trim().split('.')[0]}</span>
                      <p className="flex-1">{line.replace(/^\d+\./, '').trim().replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')}</p>
                   </div>
                }
                if (line.trim().startsWith('-')) return <li key={i} className="ml-6 list-disc marker:text-blue-500 pl-2 mb-2">{line.replace('-', '').trim()}</li>;
                if (line.trim() === '') return <div key={i} className="h-2"></div>;

                // Bold replacement
                const parts = line.split(/(\*\*.*?\*\*)/);
                return (
                  <p key={i} className="mb-4">
                    {parts.map((part, index) => {
                      if (part.startsWith('**') && part.endsWith('**')) {
                        return <strong key={index} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
                      }
                      return part;
                    })}
                  </p>
                );
              })}
            </div>

            {slide.vocabulary.length > 0 && (
              <div className="mt-10 pt-6 border-t border-slate-100">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Key Vocabulary</h4>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((vocab, i) => (
                    <span key={i} className="bg-indigo-50 px-3 py-1.5 rounded-lg text-indigo-700 text-sm font-semibold border border-indigo-100">
                      {vocab}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column: Visual Explanation */}
          <div className="flex-1 bg-slate-50 border-l border-slate-200 relative flex flex-col justify-center min-h-[300px] md:min-h-0 order-1 md:order-2">
             <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-blue-600 border border-blue-100 z-10 shadow-sm flex items-center gap-2">
                <Lightbulb className="w-3 h-3" />
                Live Visual
             </div>

             <div className="w-full h-full flex items-center justify-center p-4 md:p-8 bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] [background-size:20px_20px]">
                {slide.svgVisual ? (
                  <div 
                    className="w-full max-w-[600px] aspect-[3/2] bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden relative group transition-transform hover:scale-[1.01] duration-500"
                    dangerouslySetInnerHTML={{ __html: slide.svgVisual }}
                  />
                ) : (
                  <div className="text-center p-8 bg-white rounded-xl shadow-sm border border-slate-200 max-w-sm">
                    <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-blue-100">
                      <Lightbulb className="w-8 h-8 text-blue-400" />
                    </div>
                    <p className="text-slate-500 font-medium">Visual representation loading...</p>
                  </div>
                )}
             </div>

             <div className="p-4 bg-white/80 backdrop-blur border-t border-slate-200 absolute bottom-0 w-full">
               <p className="text-slate-600 text-xs md:text-sm leading-relaxed text-center font-medium">
                 {slide.visualDescription}
               </p>
             </div>
          </div>

        </div>

        {/* Bottom Navigation */}
        <div className="p-5 bg-white border-t border-slate-100 flex justify-between items-center shrink-0">
          <button
            onClick={prevSlide}
            disabled={currentSlide === 0}
            className="flex items-center gap-2 px-6 py-3 rounded-xl text-slate-600 hover:bg-slate-100 disabled:opacity-30 disabled:hover:bg-white font-semibold transition-all"
          >
            <ChevronLeft className="w-5 h-5" />
            Previous
          </button>

          {currentSlide === slides.length - 1 ? (
            <button
              onClick={onRestart}
              className="bg-slate-900 text-white px-8 py-3 rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg hover:shadow-slate-900/20 flex items-center gap-2"
            >
              <RotateCcw className="w-4 h-4" />
              Finish Lesson
            </button>
          ) : (
            <button
              onClick={nextSlide}
              className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg hover:shadow-blue-600/30 flex items-center gap-2"
            >
              Next Concept
              <ChevronRight className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

