    2.  **Addressing Misconceptions**: Dedicate parts of the content to explicitly correct errors. Use a format like "> **Stop & Think:** You might want to do X, but..."
    3.  **Step-by-Step Examples**: For procedural slides, use numbered lists (1. First... 2. Then...). Explain the *why* for each step.
    4.  **Visual Integration**: The text MUST reference the visual (e.g., "Look at the blue highlighted area in the diagram...").
    5.  **Terminology**: Define math terms simply in parentheses upon first use, e.g., "numerator (the top number)".

    **VISUAL GUIDELINES (SVG):**
    1.  **Format**: Return a valid SVG string. ViewBox="0 0 600 400". No width/height attributes on root.
    2.  **Content**: The visual must be a custom diagram specific to the current slide's text.
    3.  **Animation**: Use SMIL animations (<animate>, <set>, <animateTransform>) to make it dynamic (e.g., drawing lines, highlighting parts, moving numbers).
    4.  **Style**: Professional, educational style. Use clear strokes and readable text sizes (min 16px).

    **SLIDE PROGRESSION:**
    1.  **Hook & Definition**: Define the concept clearly. Visual: A clear diagram defining terms.
    2.  **Visual Mental Model**: How should they picture this? Visual: An analogy or model (e.g., area model).
    3.  **Misconception Alert**: Address the specific gap. Visual: Show the "Wrong" way vs "Right" way (use colors).
    4.  **Step-by-Step Walkthrough**: A full example. Visual: Animated steps of the calculation.
    5.  **Guided Practice**: A try-it-yourself moment. Visual: A problem setup.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING, description: "Instructional text using Markdown. Use > for warning boxes. Use numbered lists for steps." },
      visualDescription: { type: Type.STRING, description: "Description of what the SVG depicts." },
      svgVisual: { type: Type.STRING, description: "Complete, valid, animated SVG string starting with <svg> and ending with </svg>. ViewBox 0 0 600 400." },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slides: { type: Type.ARRAY, items: slideSchema }
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data.slides as RemedialSlide[];
  } catch (error) {
    console.error("Slide Generation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, Book, Lightbulb, PenTool, AlertOctagon, RotateCcw, AlertTriangle } from 'lucide-react';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Scroll content to top when slide changes
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentSlide]);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const slide = slides[currentSlide];

  // Helper to determine icon based on title keywords
  const getSlideIcon = (title: string) => {
    const t = title.toLowerCase();
    if (t.includes('definition') || t.includes('concept')) return <Book className="w-6 h-6 text-blue-500" />;
    if (t.includes('visual')) return <Lightbulb className="w-6 h-6 text-yellow-500" />;
    if (t.includes('walkthrough') || t.includes('step')) return <PenTool className="w-6 h-6 text-purple-500" />;
    if (t.includes('gap') || t.includes('fix') || t.includes('error') || t.includes('misconception')) return <AlertOctagon className="w-6 h-6 text-red-500" />;
    return <Book className="w-6 h-6 text-slate-500" />;
  };

  const renderMarkdown = (text: string) => {
    return text.split('\n').map((line, i) => {
      // Headlines
      if (line.startsWith('###')) return <h3 key={i} className="text-lg font-bold text-slate-800 mt-6 mb-3 border-b border-slate-100 pb-2">{line.replace('###', '')}</h3>;
      if (line.startsWith('##')) return <h2 key={i} className="text-xl font-bold text-slate-900 mt-6 mb-3">{line.replace('##', '')}</h2>;

      // Blockquotes / Warnings
      if (line.trim().startsWith('>')) {
        return (
          <div key={i} className="my-4 p-4 bg-amber-50 border-l-4 border-amber-400 rounded-r-lg">
             <div className="flex gap-3">
               <AlertTriangle className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
               <p className="text-amber-900 font-medium italic">
                 {line.replace('>', '').replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')}
               </p>
             </div>
          </div>
        );
      }

      // Numbered Lists (Step-by-step)
      if (line.trim().match(/^\d+\./)) {
         return (
           <div key={i} className="flex gap-4 mb-4 ml-1 group">
              <span className="flex-shrink-0 w-8 h-8 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center text-sm font-bold mt-0.5 shadow-sm group-hover:bg-blue-600 group-hover:text-white transition-colors">
                {line.trim().split('.')[0]}
              </span>
              <p className="flex-1 text-slate-700 leading-relaxed pt-1">
                {line.replace(/^\d+\./, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="text-slate-900 font-bold bg-blue-50/50 px-1 rounded">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                })}
              </p>
           </div>
         );
      }

      // Bullet Lists
      if (line.trim().startsWith('-')) {
        return <li key={i} className="ml-6 list-disc marker:text-blue-500 pl-2 mb-2 text-slate-700">{line.replace('-', '').trim()}</li>;
      }

      // Empty lines
      if (line.trim() === '') return <div key={i} className="h-3"></div>;

      // Standard Paragraphs with Bold support
      const parts = line.split(/(\*\*.*?\*\*)/);
      return (
        <p key={i} className="mb-4 text-slate-600 leading-relaxed">
          {parts.map((part, index) => {
            if (part.startsWith('**') && part.endsWith('**')) {
              return <strong key={index} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
            }
            return part;
          })}
        </p>
      );
    });
  };

  return (
    <div className="max-w-7xl mx-auto h-[calc(100vh-100px)] flex flex-col p-4 sm:p-0">
      <div className="flex-1 bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col relative">

        {/* Top Bar */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3 overflow-hidden">
            <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs sm:text-sm font-bold shadow-sm whitespace-nowrap">
              Slide {currentSlide + 1} / {slides.length}
            </span>
            <span className="text-slate-300 text-xl font-light hidden sm:inline">|</span>
            <h3 className="font-semibold text-slate-700 truncate max-w-xs sm:max-w-md">{slide.title}</h3>
          </div>
          <div className="flex gap-1.5 sm:gap-2">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`h-1.5 sm:h-2 rounded-full transition-all duration-300 ${idx === currentSlide ? 'w-8 sm:w-10 bg-blue-600' : 'w-2 bg-slate-200'}`} 
              />
            ))}
          </div>
        </div>

        {/* Slide Content Split */}
        <div className="flex-1 overflow-hidden flex flex-col lg:flex-row">

          {/* Left Column: Instructional Content */}
          <div 
            ref={contentRef}
            className="flex-1 p-6 sm:p-8 lg:p-12 overflow-y-auto no-scrollbar bg-white order-2 lg:order-1 scroll-smooth"
          >
            <div className="flex items-center gap-3 mb-6">
              <div className="p-3 bg-slate-50 rounded-xl shadow-sm border border-slate-100">
                {getSlideIcon(slide.title)}
              </div>
              <h2 className="text-2xl sm:text-3xl font-bold text-slate-900 leading-tight">{slide.title}</h2>
            </div>

            <div className="prose prose-slate prose-lg max-w-none">
              {renderMarkdown(slide.content)}
            </div>

            {slide.vocabulary.length > 0 && (
              <div className="mt-10 pt-6 border-t border-slate-100">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Key Vocabulary</h4>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((vocab, i) => (
                    <span key={i} className="bg-indigo-50 px-3 py-1.5 rounded-lg text-indigo-700 text-sm font-semibold border border-indigo-100 transition-colors hover:bg-indigo-100 cursor-default">
                      {vocab}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column: Visual Explanation */}
          <div className="flex-1 bg-slate-50/50 border-l border-slate-200 relative flex flex-col justify-center min-h-[350px] lg:min-h-0 order-1 lg:order-2">
             <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-blue-600 border border-blue-100 z-10 shadow-sm flex items-center gap-2">
                <Lightbulb className="w-3 h-3" />
                Live Visual
             </div>

             <div className="w-full h-full flex items-center justify-center p-4 lg:p-8 bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] [background-size:20px_20px]">
                {slide.svgVisual ? (
                  <div 
                    className="w-full max-w-[650px] aspect-[3/2] bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden relative group transition-all duration-500 hover:shadow-2xl"
                  >
                    <div 
                      className="w-full h-full"
                      dangerouslySetInnerHTML={{ __html: slide.svgVisual }}
                    />
                  </div>
                ) : (
                  <div className="text-center p-8 bg-white rounded-xl shadow-sm border border-slate-200 max-w-sm">
                    <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-blue-100 animate-pulse">
                      <Lightbulb className="w-8 h-8 text-blue-400" />
                    </div>
                    <p className="text-slate-500 font-medium">Generating visualization...</p>
                  </div>
                )}
             </div>

             <div className="p-4 bg-white/90 backdrop-blur border-t border-slate-200 lg:absolute lg:bottom-0 w-full z-20">
               <div className="flex gap-2 items-start max-w-2xl mx-auto">
                 <PenTool className="w-4 h-4 text-slate-400 mt-0.5 flex-shrink-0" />
                 <p className="text-slate-600 text-xs sm:text-sm leading-relaxed font-medium">
                   {slide.visualDescription}
                 </p>
               </div>
             </div>
          </div>

        </div>

        {/* Bottom Navigation */}
        <div className="p-4 sm:p-5 bg-white border-t border-slate-100 flex justify-between items-center shrink-0 z-30">
          <button
            onClick={prevSlide}
            disabled={currentSlide === 0}
            className="flex items-center gap-2 px-4 sm:px-6 py-2.5 sm:py-3 rounded-xl text-slate-600 hover:bg-slate-100 disabled:opacity-30 disabled:hover:bg-white font-semibold transition-all text-sm sm:text-base"
          >
            <ChevronLeft className="w-5 h-5" />
            Previous
          </button>

          {currentSlide === slides.length - 1 ? (
            <button
              onClick={onRestart}
              className="bg-slate-900 text-white px-6 sm:px-8 py-2.5 sm:py-3 rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg hover:shadow-slate-900/20 flex items-center gap-2 text-sm sm:text-base"
            >
              <RotateCcw className="w-4 h-4" />
              Finish Lesson
            </button>
          ) : (
            <button
              onClick={nextSlide}
              className="bg-blue-600 text-white px-6 sm:px-8 py-2.5 sm:py-3 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg hover:shadow-blue-600/30 flex items-center gap-2 text-sm sm:text-base"
            >
              Next Concept
              <ChevronRight className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default RemedialSlides;

