            </span>
            <span className="text-slate-300 text-xl font-light hidden sm:inline">|</span>
            <h3 className="font-semibold text-slate-700 truncate max-w-xs sm:max-w-md">{slide.title}</h3>
          </div>
          <div className="flex gap-1.5 sm:gap-2">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`h-1.5 rounded-full transition-all duration-300 ${idx === currentSlide ? 'w-8 bg-blue-600' : 'w-2 bg-slate-200'}`} 
              />
            ))}
          </div>
        </div>

        {/* Slide Content Split */}
        <div className="flex-1 overflow-hidden flex flex-col lg:flex-row">

          {/* Left Column: Instructional Content */}
          <div 
            ref={contentRef}
            className="flex-1 p-8 lg:p-12 overflow-y-auto no-scrollbar bg-white order-2 lg:order-1 scroll-smooth"
          >
            <div className="flex items-center gap-4 mb-8">
              <div className="p-3 bg-indigo-50 rounded-xl shadow-sm border border-indigo-100">
                {getSlideIcon(slide.title)}
              </div>
              <h2 className="text-3xl sm:text-4xl font-bold text-slate-900 leading-tight">{slide.title}</h2>
            </div>

            <div className="prose prose-slate prose-lg max-w-none">
              {renderMarkdown(slide.content)}
