            {slide.vocabulary.length > 0 && (
              <div className="mt-12 pt-8 border-t border-slate-100">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Core Vocabulary</h4>
                <div className="flex flex-wrap gap-3">
                  {slide.vocabulary.map((vocab, i) => (
                    <span key={i} className="bg-slate-100 px-4 py-2 rounded-lg text-slate-700 text-sm font-semibold border border-slate-200 transition-colors hover:bg-slate-200 cursor-default">
                      {vocab}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column: Visual Explanation */}
          <div className="flex-1 bg-slate-100 border-l border-slate-200 relative flex flex-col justify-center min-h-[400px] lg:min-h-0 order-1 lg:order-2">

             {/* Figure Label */}
             <div className="absolute top-6 right-6 bg-white px-4 py-2 rounded-lg text-sm font-bold text-slate-700 border border-slate-200 z-10 shadow-sm flex items-center gap-2">
                <span className="text-blue-500 font-black">FIGURE {currentSlide + 1}</span>
             </div>

             <div className="w-full h-full flex items-center justify-center p-6 lg:p-10 bg-slate-100">
