                    <div 
                      className="w-full aspect-[4/3] bg-white rounded-t-xl shadow-lg border border-slate-200 overflow-hidden relative group p-4 flex items-center justify-center"
                    >
                      <div 
                        className="w-full h-full"
                        dangerouslySetInnerHTML={{ __html: slide.svgVisual }}
                      />
                    </div>
                    {/* Caption attached to bottom of image */}
