                      <div className="flex gap-3 items-start">
                        <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-1 rounded uppercase tracking-wide mt-0.5">Caption</span>
                        <p className="text-slate-600 text-sm leading-relaxed font-medium">
