    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data.slides as RemedialSlide[];
  } catch (error) {
    console.error("Slide Generation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, Book, MonitorPlay, CheckCircle, AlertOctagon, RotateCcw, AlertTriangle, Layers, Type } from 'lucide-react';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentSlide]);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const slide = slides[currentSlide];

  // Helper to determine icon based on slide index/type
  const getSlideIcon = (index: number) => {
    switch(index) {
      case 0: return <Book className="w-5 h-5" />;
      case 1: return <Layers className="w-5 h-5" />;
      case 2: return <MonitorPlay className="w-5 h-5" />;
      case 3: return <AlertOctagon className="w-5 h-5" />;
      case 4: return <CheckCircle className="w-5 h-5" />;
      default: return <Type className="w-5 h-5" />;
    }
  };

  const getSlideLabel = (index: number) => {
    switch(index) {
      case 0: return "Introduction";
      case 1: return "Visual Model";
      case 2: return "Guided Example";
      case 3: return "Common Pitfall";
      case 4: return "Summary";
      default: return `Slide ${index + 1}`;
    }
  };

  const renderMarkdown = (text: string) => {
    return text.split('\n').map((line, i) => {
      // Bold Headers
      if (line.startsWith('###')) return <h3 key={i} className="text-xl font-bold text-slate-800 mt-6 mb-3">{line.replace('###', '')}</h3>;
      if (line.startsWith('##')) return <h2 key={i} className="text-2xl font-bold text-slate-900 mt-6 mb-3">{line.replace('##', '')}</h2>;

      // Warning/Important Box
      if (line.trim().startsWith('>')) {
        return (
          <div key={i} className="my-6 p-6 bg-amber-50 border-l-4 border-amber-400 rounded-r-xl">
             <div className="flex gap-4">
               <AlertTriangle className="w-6 h-6 text-amber-600 flex-shrink-0 mt-1" />
               <div className="text-amber-900 font-medium text-lg leading-relaxed">
                 {line.replace('>', '').split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="font-bold text-amber-950">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                 })}
               </div>
             </div>
          </div>
        );
      }

      // List Items (Bullet points)
      if (line.trim().startsWith('-')) {
        return (
          <li key={i} className="flex gap-3 mb-4 text-slate-700 text-lg leading-relaxed group">
            <span className="w-2 h-2 bg-blue-500 rounded-full mt-2.5 flex-shrink-0 group-hover:bg-blue-600 transition-colors" />
            <span>
              {line.replace('-', '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                if (part.startsWith('**') && part.endsWith('**')) {
                  return <strong key={idx} className="text-slate-900 font-bold bg-blue-50/50 px-1 rounded">{part.slice(2, -2)}</strong>;
                }
                return part;
              })}
            </span>
          </li>
        );
      }

      // Numbered Lists
      if (line.trim().match(/^\d+\./)) {
         return (
           <div key={i} className="flex gap-4 mb-4">
              <span className="flex-shrink-0 w-8 h-8 bg-slate-100 text-slate-600 rounded-full flex items-center justify-center font-bold text-sm mt-0.5 border border-slate-200">
                {line.trim().split('.')[0]}
              </span>
              <p className="flex-1 text-slate-700 text-lg leading-relaxed pt-1">
                {line.replace(/^\d+\./, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                })}
              </p>
           </div>
         );
      }

      if (line.trim() === '') return <div key={i} className="h-2"></div>;

      const parts = line.split(/(\*\*.*?\*\*)/);
      return (
        <p key={i} className="mb-4 text-slate-700 text-lg leading-relaxed">
          {parts.map((part, index) => {
            if (part.startsWith('**') && part.endsWith('**')) {
              return <strong key={index} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
            }
            return part;
          })}
        </p>
      );
    });
  };

  return (
    <div className="max-w-7xl mx-auto h-[calc(100vh-100px)] flex flex-col p-2 sm:p-6">
      <div className="flex-1 bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden flex flex-col">

        {/* Header - Lesson Plan Style */}
        <div className="bg-white border-b border-slate-100 px-8 py-5 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-4">
             <div className={`p-2.5 rounded-lg ${
               currentSlide === 3 ? 'bg-red-100 text-red-600' : 'bg-blue-50 text-blue-600'
             }`}>
               {getSlideIcon(currentSlide)}
             </div>
             <div>
                <div className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-0.5">
                  {getSlideLabel(currentSlide)}
                </div>
                <h2 className="text-xl font-bold text-slate-800">{slide.title}</h2>
             </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-slate-400 text-sm font-medium mr-2">
              {currentSlide + 1} / {slides.length}
            </span>
            <div className="flex gap-1">
              {slides.map((_, idx) => (
                <div 
                  key={idx} 
                  className={`h-1.5 rounded-full transition-all duration-500 ${idx === currentSlide ? 'w-6 bg-blue-600' : 'w-1.5 bg-slate-200'}`} 
                />
              ))}
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col lg:flex-row">

          {/* Content Area */}
          <div 
            ref={contentRef}
            className="flex-1 p-8 lg:p-12 overflow-y-auto bg-white flex flex-col"
          >
            <div className="flex-1">
              <div className="prose prose-slate prose-lg max-w-none">
                {renderMarkdown(slide.content)}
              </div>
            </div>

            {/* Vocabulary Footer in Content Area */}
            {slide.vocabulary.length > 0 && (
              <div className="mt-8 pt-6 border-t border-slate-100">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Key Terms</span>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((vocab, i) => (
                    <span key={i} className="bg-slate-50 px-3 py-1.5 rounded-md text-slate-600 text-sm font-medium border border-slate-200">
                      {vocab}
