import React, { useState, useEffect, useRef } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, BookOpen, Brain, Calculator, AlertTriangle, Lightbulb, RotateCcw, Map, CheckCircle2, ArrowRight } from 'lucide-react';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentSlide]);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const slide = slides[currentSlide];

  // Icons based on lesson phase
  const getPhaseIcon = (index: number) => {
    switch(index) {
      case 0: return <BookOpen className="w-5 h-5 text-blue-600" />;
      case 1: return <Brain className="w-5 h-5 text-purple-600" />;
      case 2: return <Calculator className="w-5 h-5 text-indigo-600" />;
      case 3: return <AlertTriangle className="w-5 h-5 text-amber-600" />;
      case 4: return <CheckCircle2 className="w-5 h-5 text-emerald-600" />;
      default: return <Map className="w-5 h-5 text-slate-600" />;
    }
  };

  const getPhaseLabel = (index: number) => {
    switch(index) {
      case 0: return "Concept Introduction";
      case 1: return "Visual Model";
      case 2: return "Guided Example";
      case 3: return "Common Misconception";
      case 4: return "Key Takeaway";
      default: return `Part ${index + 1}`;
    }
  };

  const getPhaseColor = (index: number) => {
    switch(index) {
      case 0: return "bg-blue-100 text-blue-700";
      case 1: return "bg-purple-100 text-purple-700";
      case 2: return "bg-indigo-100 text-indigo-700";
      case 3: return "bg-amber-100 text-amber-700";
      case 4: return "bg-emerald-100 text-emerald-700";
      default: return "bg-slate-100 text-slate-700";
    }
  };

  const renderMarkdown = (text: string) => {
    return text.split('\n').map((line, i) => {
      // Headlines
      if (line.startsWith('###')) return <h3 key={i} className="text-xl font-bold text-slate-800 mt-6 mb-3">{line.replace('###', '')}</h3>;
      if (line.startsWith('##')) return <h2 key={i} className="text-2xl font-bold text-slate-900 mt-6 mb-3">{line.replace('##', '')}</h2>;

      // Warning/Tip boxes
      if (line.trim().startsWith('>')) {
        return (
          <div key={i} className="my-6 p-5 bg-amber-50 border-l-4 border-amber-400 rounded-r-lg shadow-sm">
             <div className="flex gap-3">
               <AlertTriangle className="w-6 h-6 text-amber-600 flex-shrink-0 mt-0.5" />
               <div className="text-amber-900 font-medium leading-relaxed">
                 {line.replace('>', '').split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="font-bold text-amber-950">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                 })}
               </div>
             </div>
          </div>
        );
      }

      // Numbered Lists (Steps)
      if (line.trim().match(/^\d+\./)) {
         return (
           <div key={i} className="flex gap-4 mb-4 group">
              <span className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold mt-0.5 shadow-sm border border-white ${currentSlide === 3 ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
                {line.trim().split('.')[0]}
              </span>
              <p className="flex-1 text-slate-700 leading-relaxed pt-1 text-lg group-hover:text-slate-900 transition-colors">
                {line.replace(/^\d+\./, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="text-slate-900 font-bold bg-slate-100 px-1 rounded">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                })}
              </p>
           </div>
         );
      }

      // Bullet Lists
      if (line.trim().startsWith('-') || line.trim().startsWith('•')) {
        return (
          <li key={i} className="flex gap-3 mb-3 text-slate-700 text-lg leading-relaxed pl-2">
             <div className={`w-2 h-2 rounded-full mt-2.5 shrink-0 ${currentSlide === 3 ? 'bg-amber-400' : 'bg-blue-400'}`} />
             <span>
               {line.replace(/^-|•/, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                 if (part.startsWith('**') && part.endsWith('**')) {
                   return <strong key={idx} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
                 }
                 return part;
               })}
             </span>
          </li>
        );
      }

      if (line.trim() === '') return <div key={i} className="h-3"></div>;

      const parts = line.split(/(\*\*.*?\*\*)/);
      return (
        <p key={i} className="mb-4 text-slate-700 leading-relaxed text-lg">
          {parts.map((part, index) => {
            if (part.startsWith('**') && part.endsWith('**')) {
              return <strong key={index} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
            }
            return part;
          })}
        </p>
      );
    });
  };

  return (
    <div className="h-[calc(100vh-100px)] w-full max-w-7xl mx-auto flex flex-col gap-6 p-2 sm:p-4">

      {/* 1. Navigation Header */}
      <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-4 rounded-2xl shadow-sm border border-slate-200 gap-4">
         <div className="flex items-center gap-3">
           <div className="bg-slate-900 text-white px-3 py-1 rounded-lg text-xs font-bold uppercase tracking-widest shadow-lg shadow-slate-900/20">
             Lesson Plan
           </div>
           <div className="text-sm font-medium text-slate-500 hidden sm:block">
             Remediation Mode
           </div>
         </div>

         {/* Compact Stepper */}
         <div className="flex items-center gap-2">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`
                  h-2 rounded-full transition-all duration-300 
                  ${idx === currentSlide ? 'w-8 bg-blue-600' : 'w-2 bg-slate-200'}
                  ${idx < currentSlide ? 'bg-blue-400' : ''}
                `}
                title={getPhaseLabel(idx)}
              />
            ))}
            <span className="ml-2 text-sm font-bold text-slate-700 w-16 text-right">
              {currentSlide + 1} / {slides.length}
            </span>
         </div>
      </div>

      {/* 2. Main Lesson Card */}
      <div className="flex-1 bg-white rounded-3xl shadow-xl ring-1 ring-slate-900/5 overflow-hidden flex flex-col lg:flex-row">

        {/* LEFT PANEL: Content (40%) */}
        <div className="lg:w-5/12 flex flex-col border-r border-slate-100 bg-white relative z-10">
           {/* Top Label */}
           <div className="px-8 pt-8 pb-4">
              <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold uppercase tracking-wider ${getPhaseColor(currentSlide)}`}>
                 {getPhaseIcon(currentSlide)}
                 {getPhaseLabel(currentSlide)}
              </div>
           </div>

           {/* Scrollable Content */}
           <div 
             ref={contentRef}
             className="flex-1 overflow-y-auto px-8 pb-8 custom-scrollbar"
           >
              <h1 className="text-3xl font-bold text-slate-900 leading-tight mb-6">{slide.title}</h1>
              <div className="prose prose-slate prose-lg max-w-none">
                {renderMarkdown(slide.content)}
              </div>
           </div>

           {/* Fixed Vocabulary Footer */}
           {slide.vocabulary.length > 0 && (
             <div className="px-8 py-6 bg-slate-50 border-t border-slate-100">
                <div className="flex items-center gap-2 mb-3">
                  <BookOpen className="w-4 h-4 text-slate-400" />
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Key Vocabulary</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((v, i) => (
                    <span key={i} className="px-2.5 py-1 bg-white text-slate-600 rounded border border-slate-200 text-sm font-medium shadow-sm">
                      {v}
                    </span>
                  ))}
                </div>
             </div>
           )}
        </div>

        {/* RIGHT PANEL: Visual Board (60%) */}
        <div className="lg:w-7/12 bg-slate-50 relative flex flex-col min-h-[400px]">
            {/* Subtle Grid Background */}
            <div className="absolute inset-0 opacity-[0.05]" 
                 style={{ backgroundImage: 'linear-gradient(#64748b 1px, transparent 1px), linear-gradient(90deg, #64748b 1px, transparent 1px)', backgroundSize: '40px 40px' }}>
            </div>

            {/* Visual Area */}
            <div className="flex-1 flex items-center justify-center p-8 relative">
               <div className="w-full max-w-2xl bg-white rounded-2xl shadow-sm border border-slate-200 p-2 transform transition-all hover:shadow-md duration-500">
                 <div className="aspect-[4/3] bg-white rounded-xl overflow-hidden relative flex items-center justify-center">
                    {slide.svgVisual ? (
                      <div 
                        className="w-full h-full"
                        dangerouslySetInnerHTML={{ __html: slide.svgVisual }}
                      />
                    ) : (
                      <div className="flex flex-col items-center gap-3 text-slate-300">
                         <div className="w-12 h-12 rounded-full border-4 border-slate-200 border-t-slate-300 animate-spin"></div>
                         <span className="font-medium">Generating diagram...</span>
                      </div>
                    )}
                 </div>
               </div>
            </div>

            {/* Integrated Caption */}
            <div className="bg-white border-t border-slate-200 px-8 py-6">
               <div className="flex gap-4 items-start max-w-3xl">
                  <div className="bg-indigo-50 text-indigo-600 p-2.5 rounded-xl shrink-0">
                     <Lightbulb className="w-6 h-6" />
                  </div>
                  <div>
                     <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Visual Insight</h4>
                     <p className="text-slate-700 font-medium leading-relaxed text-lg">
                       {slide.visualDescription}
                     </p>
                  </div>
               </div>
            </div>
        </div>
      </div>

      {/* 3. Footer Controls */}
      <div className="flex justify-between items-center pb-2">
         <button
            onClick={prevSlide}
            disabled={currentSlide === 0}
            className="group flex items-center gap-2 px-5 py-3 rounded-xl text-slate-600 hover:text-slate-900 hover:bg-white hover:shadow-sm font-semibold transition-all disabled:opacity-30 disabled:hover:bg-transparent disabled:hover:shadow-none"
         >
            <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center group-hover:bg-slate-200 transition-colors">
              <ChevronLeft className="w-5 h-5" />
            </div>
            <span>Previous</span>
         </button>

         {currentSlide === slides.length - 1 ? (
            <button
               onClick={onRestart}
               className="bg-slate-900 text-white pl-6 pr-5 py-3 rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg hover:shadow-slate-900/20 flex items-center gap-3"
            >
               <span>Complete Lesson</span>
               <div className="bg-white/20 p-1 rounded-lg">
                 <RotateCcw className="w-4 h-4" />
               </div>
            </button>
         ) : (
            <button
               onClick={nextSlide}
               className="bg-blue-600 text-white pl-6 pr-5 py-3 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg hover:shadow-blue-600/30 flex items-center gap-3 group"
            >
               <span>Next Step</span>
               <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
