import { GoogleGenAI, Schema, Type } from "@google/genai";
import { Standard, Quiz, GapAnalysis, RemedialSlide, GapType, QuizResult, Question } from '../types';
import { MTR_STANDARDS } from '../constants';

// Helper to get client instance - ensures fresh connection for each request
const getAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateQuiz = async (standard: Standard): Promise<Quiz> => {
  const ai = getAiClient();

  const prompt = `
    You are an expert Florida B.E.S.T. Mathematics Standards curriculum designer.
    Create a 5-question multiple-choice quiz for the following standard:

    Code: ${standard.code}
    Description: ${standard.description}
    Clarifications: ${standard.clarifications?.join(' ') || 'None provided.'}
    Examples: ${standard.examples?.join(' ') || 'None provided.'}

    The questions must:
    1. Be strictly aligned to the standard.
    2. Incorporate the Florida MTR (Mathematical Thinking and Reasoning) standards where possible.
    3. Include 4 options (A-D) with one correct answer.
    4. Provide a visual animation description that would help explain the concept to a student.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      text: { type: Type.STRING },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Must contain exactly 4 options"
      },
      correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
      explanation: { type: Type.STRING },
      animationDescription: { type: Type.STRING }
    },
    required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: {
        type: Type.ARRAY,
        items: questionSchema
      }
    },
    required: ["standardCode", "questions"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a rigid JSON generator for educational content."
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as Quiz;
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    throw error;
  }
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  const ai = getAiClient();

  // Pass comprehensive question performance data to the AI
  const detailedAnalysis = questions.map((q, i) => {
    const r = results[i];
    return `
      Question ${i + 1}: ${q.text}
      Options: ${q.options.join(', ')}
      Correct Answer: ${q.options[q.correctAnswerIndex]}
      Student Selected: ${q.options[r.selectedOptionIndex]}
      Is Correct: ${r.isCorrect}
    `;
  }).join('\n---\n');

  const prompt = `
    Analyze the following student performance on a quiz for Florida Standard ${standard.code}: ${standard.description}.

    Detailed Performance:
    ${detailedAnalysis}

    Tasks:
    1. **Sub-skill Analysis**: Break down the standard into 2-4 distinct sub-skills or component skills relevant to these specific questions. For each sub-skill, determine how many questions related to it and how many were correct.
    2. **Misconception Detection**: For incorrect answers, analyze the specific distractor (wrong option) selected by the student. Does it indicate a common mathematical misconception (e.g., "adding denominators", "confusing perimeter with area", "place value alignment error")?
    3. **Gap Diagnosis**: Aggregate the errors into learning gaps.

    **Confidence Score Calculation**:
    Provide a confidence score (0-100) based on the consistency of the error pattern:
    - **High (85-100)**: The student makes the *same specific type of error* across multiple questions (e.g., always adds denominators).
    - **Medium (60-84)**: The student struggles with a general concept but errors vary slightly or there is only 1 error to analyze.
    - **Low (0-59)**: The errors appear random, suggesting guessing, or there is not enough data to form a strong conclusion.
  `;

  const subSkillSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      description: { type: Type.STRING },
      correctCount: { type: Type.INTEGER },
      totalCount: { type: Type.INTEGER }
    },
    required: ["name", "description", "correctCount", "totalCount"]
  };

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } },
      misconception: { type: Type.STRING, description: "The specific misconception identified from the wrong answer chosen." }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      subSkills: { type: Type.ARRAY, items: subSkillSchema },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "subSkills", "confidenceScore", "summary"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GapAnalysis;
  } catch (error) {
    console.error("Gap Analysis Error:", error);
    throw error;
  }
};

export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  const ai = getAiClient();

  const prompt = `
    You are a master math tutor designing a specialized 5-step lesson plan to fix a student's specific learning gap.

    Target Standard: ${standard.code} (${standard.description})

    **DIAGNOSED GAPS (Prioritize these):**
    ${analysis.identifiedGaps.map(g => `• ${g.description} (Misconception: ${g.misconception || 'General error'})`).join('\n')}

    **INSTRUCTIONAL STRATEGY:**
    Do not just provide information. TEACH the concept using a logical progression.
    The lesson must feel like a cohesive story, not random slides.

    **LESSON PLAN STRUCTURE (Exactly 5 Slides):**

    1.  **The Hook & Definition**: 
        - Title: "Understanding [Topic]"
        - Content: Define the concept simply. Why do we need it? Keep it short (2-3 sentences max).
        - **Visual Strategy**: Use a **Real-world Metaphor** or **Concept Map**.

    2.  **Visual Proof (Mental Model)**:
        - Title: "Seeing How It Works"
        - Content: Explain *why* the math works using a visual model. Connect the abstract numbers to the concrete visual.
        - **Visual Strategy**: Use a **Concrete Manipulative** (e.g., Number Line, Area Model/Grid, Base-10 Blocks, Fraction Strips).

    3.  **Guided Walkthrough (Step-by-Step)**:
        - Title: "Let's Solve One"
        - Content: A specific problem relevant to the gap. Break it down into 3 concise steps (use 1., 2., 3.).
        - **Visual Strategy**: Use a **Flowchart** or **Process Diagram** showing the transformation.

    4.  **Addressing the Error (The Fix)**:
        - Title: "Watch Out!"
        - Content: Directly address the user's likely misconception. "You might think X, but actually Y because...". Use a warning block (start line with >).
        - **Visual Strategy**: **Side-by-Side Comparison** (Red X vs Green Check) or **Balance Scale** to show inequality vs equality.

    5.  **The Golden Rule**:
        - Title: "Key Takeaway"
        - Content: The one rule they should memorize. A final confidence booster.
        - **Visual Strategy**: **Summary Infographic**, **Cheat Sheet Card**, or **Formula Visualization**.

    **VISUAL GUIDELINES (SVG Generation):**
    - **DIVERSITY IS CRITICAL**: Do not use the same type of visual for every slide. 
    - **Math Types**:
      - *Arithmetic*: Use **Number Lines** (with jumps), **Ten Frames**, **Array Models**.
      - *Fractions*: Use **Circular Sectors** (Pie), **Rectangular Bars**, **Number Lines**.
      - *Algebra*: Use **Tape Diagrams**, **Balance Scales**, **Coordinate Graphs** (plotted points).
      - *Geometry*: Use **Precise Shapes** with angle arcs, side ticks, and dimensions.
      - *Data*: Use **Bar Graphs**, **Dot Plots**, **Histograms**.
    - **Style**: Clean, modern, academic. Use soft colors (Blue #3b82f6, Emerald #10b981, Amber #f59e0b, Slate #64748b).
    - **ViewBox**: "0 0 800 600".
    - **Attributes**: Ensure the <svg> tag includes preserveAspectRatio="xMidYMid meet" so it scales correctly.
    - **Accessibility**: Use high contrast and large font sizes (>24px).
    - **No Animations**: Static SVG only.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING, description: "The teacher's script/explanation in Markdown. Use bolding for emphasis. Keep concise to fit 40% of screen." },
      visualDescription: { type: Type.STRING, description: "A caption that explicitly connects the image to the text (e.g. 'Notice how the numerator...')" },
      svgVisual: { type: Type.STRING, description: "Static SVG string. ViewBox 0 0 800 600. Use varied visualizations (Graphs, Charts, Models)." },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slides: { type: Type.ARRAY, items: slideSchema }
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data.slides as RemedialSlide[];
  } catch (error) {
    console.error("Slide Generation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, BookOpen, Brain, Calculator, AlertTriangle, Lightbulb, RotateCcw, Map, CheckCircle2, ArrowRight, Download, FileText, Loader2 } from 'lucide-react';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isDownloading, setIsDownloading] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);
  const printRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentSlide]);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const handleDownloadPDF = async () => {
    if (!printRef.current) return;
    setIsDownloading(true);

    try {
      const pdf = new jsPDF({
        orientation: 'landscape',
        unit: 'px',
        format: [1200, 800] // Match slide aspect ratio roughly
      });

      const slidesElements = printRef.current.children;

      for (let i = 0; i < slidesElements.length; i++) {
        const element = slidesElements[i] as HTMLElement;

        // Wait for fonts/images slightly
        await new Promise(resolve => setTimeout(resolve, 100));

        const canvas = await html2canvas(element, {
          scale: 2, // Higher resolution
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.95);

        if (i > 0) pdf.addPage();
        pdf.addImage(imgData, 'JPEG', 0, 0, 1200, 800);
      }

      pdf.save('Personalized-Lesson-Plan.pdf');
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('Could not generate PDF. Please try again.');
    } finally {
      setIsDownloading(false);
    }
  };

  const processSVG = (svgString: string | undefined) => {
    if (!svgString) return '';
    // Ensure the SVG has preserveAspectRatio to prevent cutting off
    let processed = svgString;
    if (!processed.includes('preserveAspectRatio')) {
      processed = processed.replace('<svg', '<svg preserveAspectRatio="xMidYMid meet"');
    }
    // Remove fixed width/height if present to allow scaling
    processed = processed.replace(/width="[^"]*"/, 'width="100%"').replace(/height="[^"]*"/, 'height="100%"');
    return processed;
  };

  const slide = slides[currentSlide];

  // Icons based on lesson phase
  const getPhaseIcon = (index: number) => {
    switch(index) {
      case 0: return <BookOpen className="w-5 h-5 text-blue-600" />;
      case 1: return <Brain className="w-5 h-5 text-purple-600" />;
      case 2: return <Calculator className="w-5 h-5 text-indigo-600" />;
      case 3: return <AlertTriangle className="w-5 h-5 text-amber-600" />;
      case 4: return <CheckCircle2 className="w-5 h-5 text-emerald-600" />;
      default: return <Map className="w-5 h-5 text-slate-600" />;
    }
  };

  const getPhaseLabel = (index: number) => {
    switch(index) {
      case 0: return "Concept";
      case 1: return "Model";
      case 2: return "Example";
      case 3: return "Pitfall";
      case 4: return "Takeaway";
      default: return `Part ${index + 1}`;
    }
  };

  const renderMarkdown = (text: string) => {
    return text.split('\n').map((line, i) => {
      // Headlines
      if (line.startsWith('###')) return <h3 key={i} className="text-xl font-bold text-slate-800 mt-6 mb-3">{line.replace('###', '')}</h3>;
      if (line.startsWith('##')) return <h2 key={i} className="text-2xl font-bold text-slate-900 mt-6 mb-3">{line.replace('##', '')}</h2>;

      // Warning/Tip boxes
      if (line.trim().startsWith('>')) {
        return (
          <div key={i} className="my-5 p-4 bg-amber-50 border-l-4 border-amber-400 rounded-r-lg shadow-sm">
             <div className="flex gap-3">
               <AlertTriangle className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
               <div className="text-amber-900 font-medium text-base leading-relaxed">
                 {line.replace('>', '').split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="font-bold text-amber-950">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                 })}
               </div>
             </div>
          </div>
        );
      }

      // Numbered Lists
      if (line.trim().match(/^\d+\./)) {
         return (
           <div key={i} className="flex gap-3 mb-3 group">
              <span className={`flex-shrink-0 w-7 h-7 rounded-full flex items-center justify-center text-sm font-bold mt-0.5 shadow-sm border border-white ${currentSlide === 3 ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
                {line.trim().split('.')[0]}
              </span>
              <p className="flex-1 text-slate-700 leading-relaxed pt-0.5 text-lg group-hover:text-slate-900 transition-colors">
                {line.replace(/^\d+\./, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="text-slate-900 font-bold bg-slate-100 px-1 rounded">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                })}
              </p>
           </div>
         );
      }

      // Bullet Lists
      if (line.trim().startsWith('-') || line.trim().startsWith('•')) {
        return (
          <li key={i} className="flex gap-3 mb-3 text-slate-700 text-lg leading-relaxed pl-2">
             <div className={`w-1.5 h-1.5 rounded-full mt-2.5 shrink-0 ${currentSlide === 3 ? 'bg-amber-400' : 'bg-blue-400'}`} />
             <span>
               {line.replace(/^-|•/, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                 if (part.startsWith('**') && part.endsWith('**')) {
                   return <strong key={idx} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
                 }
                 return part;
               })}
             </span>
          </li>
        );
      }

      if (line.trim() === '') return <div key={i} className="h-2"></div>;

      const parts = line.split(/(\*\*.*?\*\*)/);
      return (
        <p key={i} className="mb-3 text-slate-700 leading-relaxed text-lg">
          {parts.map((part, index) => {
            if (part.startsWith('**') && part.endsWith('**')) {
              return <strong key={index} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
            }
            return part;
          })}
        </p>
      );
    });
  };

  return (
    <div className="lg:h-[calc(100vh-100px)] h-auto w-full max-w-7xl mx-auto flex flex-col gap-4 p-2 sm:p-4">

      {/* 1. Header Bar */}
      <div className="flex flex-col sm:flex-row justify-between items-center bg-white px-4 sm:px-6 py-4 rounded-2xl shadow-sm border border-slate-200 gap-4 sm:gap-0">
         <div className="flex items-center gap-4 w-full sm:w-auto justify-between sm:justify-start">
           <div className="flex flex-col">
             <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Current Lesson</span>
             <span className="text-lg font-bold text-slate-800">Remediation Mode</span>
           </div>

           {/* Mobile Download Button */}
           <button 
             onClick={handleDownloadPDF}
             disabled={isDownloading}
             className="sm:hidden flex items-center justify-center p-2 bg-slate-100 text-slate-700 rounded-lg border border-slate-200"
             title="Download PDF"
           >
             {isDownloading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Download className="w-5 h-5" />}
           </button>
         </div>

         {/* Stepper */}
         <div className="flex items-center gap-1">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`
                  flex items-center justify-center w-8 h-8 rounded-full text-xs font-bold transition-all duration-300 border
                  ${idx === currentSlide 
                    ? 'bg-blue-600 text-white border-blue-600 scale-110 shadow-md' 
                    : idx < currentSlide 
