                `}
                title={getPhaseLabel(idx)}
              >
                {idx + 1}
              </div>
            ))}
         </div>

         {/* Desktop Download Button */}
         <button 
           onClick={handleDownloadPDF}
           disabled={isDownloading}
           className="hidden sm:flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-bold transition-colors border border-slate-200 disabled:opacity-50"
         >
           {isDownloading ? (
             <Loader2 className="w-4 h-4 animate-spin" />
           ) : (
             <Download className="w-4 h-4" />
           )}
           <span>{isDownloading ? 'Generating...' : 'Download PDF'}</span>
         </button>
      </div>

      {/* 2. Main Split Layout */}
      <div className="flex-1 bg-white rounded-3xl shadow-xl ring-1 ring-slate-900/5 flex flex-col lg:flex-row lg:overflow-hidden overflow-visible">

        {/* LEFT PANEL: Content (40% on Desktop, 100% on Mobile) */}
        <div className="lg:w-5/12 w-full flex flex-col border-r border-slate-100 bg-white relative z-10 lg:h-full h-auto">

           {/* Phase Label */}
           <div className="px-6 sm:px-8 pt-8 pb-2">
              <div className="flex items-center gap-2 text-sm font-bold text-blue-600 uppercase tracking-wider">
                 {getPhaseIcon(currentSlide)}
                 {getPhaseLabel(currentSlide)}
              </div>
           </div>

           {/* Scrollable Text Area - Scrollable on Desktop, Auto height on Mobile */}
           <div ref={contentRef} className="flex-1 lg:overflow-y-auto overflow-visible px-6 sm:px-8 pb-6 custom-scrollbar">
              <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 leading-tight mb-6">{slide.title}</h1>
              <div className="prose prose-slate prose-lg max-w-none">
                {renderMarkdown(slide.content)}
              </div>
           </div>

           {/* Vocabulary (Anchored) */}
           {slide.vocabulary.length > 0 && (
             <div className="px-6 sm:px-8 py-5 bg-slate-50 border-t border-slate-100 shrink-0">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Key Vocabulary</span>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((v, i) => (
                    <span key={i} className="px-2.5 py-1 bg-white text-slate-600 rounded border border-slate-200 text-xs font-bold shadow-sm">
                      {v}
