             {/* Print Header */}
             <div className="flex justify-between items-center mb-8 border-b border-slate-100 pb-4">
               <div>
                  <h1 className="text-4xl font-bold text-slate-900">{s.title}</h1>
                  <span className="text-slate-500 font-medium mt-2 block">{getPhaseLabel(idx)} - Step {idx + 1} of {slides.length}</span>
               </div>
               <div className="bg-slate-100 px-4 py-2 rounded-lg">
                 <span className="text-slate-500 font-bold tracking-widest">FLORIDA B.E.S.T. MATH</span>
               </div>
             </div>

             <div className="flex gap-12 flex-1">
                {/* Print Content */}
                <div className="w-5/12 text-xl leading-relaxed text-slate-700 space-y-4">
                  {renderMarkdown(s.content)}

                  {s.vocabulary.length > 0 && (
                    <div className="mt-8 pt-8 border-t border-slate-100">
                      <span className="text-sm font-bold text-slate-400 uppercase tracking-wider block mb-3">Vocabulary</span>
                      <div className="flex flex-wrap gap-2">
                        {s.vocabulary.map(v => (
                          <span key={v} className="px-3 py-1 bg-slate-100 text-slate-600 rounded border border-slate-200 text-sm font-bold">{v}</span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {/* Print Visual */}
                <div className="w-7/12 flex flex-col">
                  <div className="flex-1 bg-slate-50 rounded-xl border border-slate-200 p-8 flex items-center justify-center">
                    <div 
                      className="w-full h-full flex items-center justify-center [&>svg]:w-full [&>svg]:h-full [&>svg]:max-w-full [&>svg]:max-h-full"
                      dangerouslySetInnerHTML={{ __html: processSVG(s.svgVisual) }} 
                    />
                  </div>
                  <div className="mt-6 bg-blue-50 p-6 rounded-xl border-l-4 border-blue-500">
                     <h4 className="font-bold text-blue-900 mb-2 flex items-center gap-2">
                       <Lightbulb className="w-5 h-5" /> Visual Insight
                     </h4>
                     <p className="text-blue-800 text-lg">{s.visualDescription}</p>
                  </div>
                </div>
             </div>
          </div>
        ))}
      </div>

    </div>
  );
};

