import React, { useState, useEffect, useRef } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, BookOpen, Brain, Calculator, AlertTriangle, Lightbulb, RotateCcw, Map, CheckCircle2, ArrowRight, Download, FileText, Loader2, Presentation } from 'lucide-react';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';
import pptxgen from 'pptxgenjs';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);
  const [isDownloadingPpt, setIsDownloadingPpt] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);
  const printRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentSlide]);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const handleDownloadPDF = async () => {
    if (!printRef.current) return;
    setIsDownloadingPdf(true);

    try {
      const pdf = new jsPDF({
        orientation: 'landscape',
        unit: 'px',
        format: [1200, 800] // Match slide aspect ratio roughly
      });

      const slidesElements = printRef.current.children;

      for (let i = 0; i < slidesElements.length; i++) {
        const element = slidesElements[i] as HTMLElement;

        // Wait for fonts/images slightly
        await new Promise(resolve => setTimeout(resolve, 100));

        const canvas = await html2canvas(element, {
          scale: 2, // Higher resolution
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.95);

        if (i > 0) pdf.addPage();
        pdf.addImage(imgData, 'JPEG', 0, 0, 1200, 800);
      }

      pdf.save('Personalized-Lesson-Plan.pdf');
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('Could not generate PDF. Please try again.');
    } finally {
      setIsDownloadingPdf(false);
    }
  };

  // Helper to convert SVG string to PNG data URL for PPTX
  const svgToPng = (svgString: string): Promise<string> => {
    return new Promise((resolve, reject) => {
      // Clean up SVG string
      let cleanedSvg = svgString.trim();
      if (!cleanedSvg.includes('xmlns=')) {
        cleanedSvg = cleanedSvg.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
      }

      // Ensure specific dimensions for the canvas rasterization
      // Removing width/height attributes to rely on viewBox or defaults, then setting them on image
      // But simplest is to load into Image and draw to canvas of specific size

      const img = new Image();
      const svgBlob = new Blob([cleanedSvg], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);

      img.onload = () => {
        const canvas = document.createElement('canvas');
        // Set canvas size (high res)
        canvas.width = 1600;
        canvas.height = 1200;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = '#ffffff'; // White background just in case
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          const pngData = canvas.toDataURL('image/png');
          URL.revokeObjectURL(url);
          resolve(pngData);
        } else {
          reject(new Error('Canvas context failed'));
        }
      };

      img.onerror = (e) => {
        console.error('SVG Load Error', e);
        // Fallback or reject
        resolve(''); // Resolve empty to continue flow
      };

      img.src = url;
    });
  };

  const handleDownloadPPT = async () => {
    setIsDownloadingPpt(true);
    try {
      const pres = new pptxgen();

      // Define layout (16:9 is default)

      for (let i = 0; i < slides.length; i++) {
        const slideData = slides[i];
        const slide = pres.addSlide();

        // 1. Title
        slide.addText(slideData.title, {
          x: 0.5, y: 0.3, w: 9, h: 0.8,
          fontSize: 28,
          fontFace: 'Arial',
          bold: true,
          color: '1e293b' // Slate 800
        });

        // 2. Subtitle / Step info
        slide.addText(`${getPhaseLabel(i)} - Step ${i + 1}`, {
          x: 0.5, y: 0.9, w: 9, h: 0.4,
          fontSize: 14,
          color: '64748b' // Slate 500
        });

        // 3. Content Text (Left Side)
        // Clean markdown symbols roughly
        const cleanContent = slideData.content
          .replace(/\*\*(.*?)\*\*/g, '$1') // Remove bold markers
          .replace(/^###\s*/gm, '') // Remove h3
          .replace(/^##\s*/gm, '') // Remove h2
          .replace(/>\s*/gm, ''); // Remove blockquote arrow

        slide.addText(cleanContent, {
          x: 0.5, y: 1.5, w: 4.5, h: 4.0,
          fontSize: 16,
          color: '334155', // Slate 700
          valign: 'top',
          bullet: false,
          wrap: true
        });

        // Add Vocabulary if present
        if (slideData.vocabulary.length > 0) {
           slide.addText('Vocabulary: ' + slideData.vocabulary.join(', '), {
             x: 0.5, y: 5.8, w: 4.5, h: 0.8,
             fontSize: 12,
             color: '475569',
             bold: true
           });
        }

        // 4. Visual (Right Side)
        if (slideData.svgVisual) {
          try {
            const pngData = await svgToPng(slideData.svgVisual);
            if (pngData) {
              slide.addImage({
                data: pngData,
                x: 5.2, y: 1.5, w: 4.5, h: 3.5,
                sizing: { type: 'contain', w: 4.5, h: 3.5 }
              });
            }
          } catch (e) {
            console.error('Error adding image to slide', i, e);
          }
        }

        // 5. Visual Caption
        slide.addText(slideData.visualDescription, {
          x: 5.2, y: 5.1, w: 4.5, h: 1.0,
          fontSize: 11,
          color: '3b82f6', // Blue 500
          italic: true,
          shape: pres.ShapeType.rect,
          fill: { color: 'eff6ff' }, // Blue 50
          inset: 0.1
        });
      }

      await pres.writeFile({ fileName: `Math-Remediation-Lesson.pptx` });

    } catch (error) {
      console.error('PPT Generation failed', error);
      alert('Could not generate PPT. Please try again.');
    } finally {
      setIsDownloadingPpt(false);
    }
  };

  const processSVG = (svgString: string | undefined) => {
    if (!svgString) return '';
    // Ensure the SVG has preserveAspectRatio to prevent cutting off
    let processed = svgString;
    if (!processed.includes('preserveAspectRatio')) {
      processed = processed.replace('<svg', '<svg preserveAspectRatio="xMidYMid meet"');
    }
    // Remove fixed width/height if present to allow scaling
    processed = processed.replace(/width="[^"]*"/, 'width="100%"').replace(/height="[^"]*"/, 'height="100%"');
    return processed;
  };

  const slide = slides[currentSlide];

  // Icons based on lesson phase
  const getPhaseIcon = (index: number) => {
    switch(index) {
      case 0: return <BookOpen className="w-5 h-5 text-blue-600" />;
      case 1: return <Brain className="w-5 h-5 text-purple-600" />;
      case 2: return <Calculator className="w-5 h-5 text-indigo-600" />;
      case 3: return <AlertTriangle className="w-5 h-5 text-amber-600" />;
      case 4: return <CheckCircle2 className="w-5 h-5 text-emerald-600" />;
      default: return <Map className="w-5 h-5 text-slate-600" />;
    }
  };

  const getPhaseLabel = (index: number) => {
    switch(index) {
      case 0: return "Concept";
      case 1: return "Model";
      case 2: return "Example";
      case 3: return "Pitfall";
      case 4: return "Takeaway";
      default: return `Part ${index + 1}`;
    }
  };

  const renderMarkdown = (text: string) => {
    return text.split('\n').map((line, i) => {
      // Headlines
      if (line.startsWith('###')) return <h3 key={i} className="text-xl font-bold text-slate-800 mt-6 mb-3">{line.replace('###', '')}</h3>;
      if (line.startsWith('##')) return <h2 key={i} className="text-2xl font-bold text-slate-900 mt-6 mb-3">{line.replace('##', '')}</h2>;

      // Warning/Tip boxes
      if (line.trim().startsWith('>')) {
        return (
          <div key={i} className="my-5 p-4 bg-amber-50 border-l-4 border-amber-400 rounded-r-lg shadow-sm">
             <div className="flex gap-3">
               <AlertTriangle className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
               <div className="text-amber-900 font-medium text-base leading-relaxed">
                 {line.replace('>', '').split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="font-bold text-amber-950">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                 })}
               </div>
             </div>
          </div>
        );
      }

      // Numbered Lists
      if (line.trim().match(/^\d+\./)) {
         return (
           <div key={i} className="flex gap-3 mb-3 group">
              <span className={`flex-shrink-0 w-7 h-7 rounded-full flex items-center justify-center text-sm font-bold mt-0.5 shadow-sm border border-white ${currentSlide === 3 ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
                {line.trim().split('.')[0]}
              </span>
              <p className="flex-1 text-slate-700 leading-relaxed pt-0.5 text-lg group-hover:text-slate-900 transition-colors">
                {line.replace(/^\d+\./, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                   if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="text-slate-900 font-bold bg-slate-100 px-1 rounded">{part.slice(2, -2)}</strong>;
                   }
                   return part;
                })}
              </p>
           </div>
         );
      }

      // Bullet Lists
      if (line.trim().startsWith('-') || line.trim().startsWith('•')) {
        return (
          <li key={i} className="flex gap-3 mb-3 text-slate-700 text-lg leading-relaxed pl-2">
             <div className={`w-1.5 h-1.5 rounded-full mt-2.5 shrink-0 ${currentSlide === 3 ? 'bg-amber-400' : 'bg-blue-400'}`} />
             <span>
               {line.replace(/^-|•/, '').trim().split(/(\*\*.*?\*\*)/).map((part, idx) => {
                 if (part.startsWith('**') && part.endsWith('**')) {
                   return <strong key={idx} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
                 }
                 return part;
               })}
             </span>
          </li>
        );
      }

      if (line.trim() === '') return <div key={i} className="h-2"></div>;

      const parts = line.split(/(\*\*.*?\*\*)/);
      return (
        <p key={i} className="mb-3 text-slate-700 leading-relaxed text-lg">
          {parts.map((part, index) => {
            if (part.startsWith('**') && part.endsWith('**')) {
              return <strong key={index} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
            }
            return part;
          })}
        </p>
      );
    });
  };

  return (
    <div className="lg:h-[calc(100vh-100px)] h-auto w-full max-w-7xl mx-auto flex flex-col gap-4 p-2 sm:p-4">

      {/* 1. Header Bar */}
      <div className="flex flex-col sm:flex-row justify-between items-center bg-white px-4 sm:px-6 py-4 rounded-2xl shadow-sm border border-slate-200 gap-4 sm:gap-0">
         <div className="flex items-center gap-4 w-full sm:w-auto justify-between sm:justify-start">
           <div className="flex flex-col">
             <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Current Lesson</span>
             <span className="text-lg font-bold text-slate-800">Remediation Mode</span>
           </div>

           {/* Mobile Download Buttons */}
           <div className="sm:hidden flex gap-2">
              <button 
               onClick={handleDownloadPPT}
               disabled={isDownloadingPpt || isDownloadingPdf}
               className="flex items-center justify-center p-2 bg-slate-100 text-slate-700 rounded-lg border border-slate-200"
               title="Download PPT"
             >
               {isDownloadingPpt ? <Loader2 className="w-5 h-5 animate-spin text-orange-600" /> : <Presentation className="w-5 h-5 text-orange-600" />}
             </button>
             <button 
               onClick={handleDownloadPDF}
               disabled={isDownloadingPpt || isDownloadingPdf}
               className="flex items-center justify-center p-2 bg-slate-100 text-slate-700 rounded-lg border border-slate-200"
               title="Download PDF"
             >
               {isDownloadingPdf ? <Loader2 className="w-5 h-5 animate-spin text-red-600" /> : <FileText className="w-5 h-5 text-red-600" />}
             </button>
           </div>
         </div>

         {/* Stepper */}
         <div className="flex items-center gap-1">
            {slides.map((_, idx) => (
              <div 
                key={idx} 
                className={`
                  flex items-center justify-center w-8 h-8 rounded-full text-xs font-bold transition-all duration-300 border
                  ${idx === currentSlide 
                    ? 'bg-blue-600 text-white border-blue-600 scale-110 shadow-md' 
                    : idx < currentSlide 
                      ? 'bg-blue-50 text-blue-600 border-blue-100' 
                      : 'bg-slate-50 text-slate-300 border-slate-100'}
                `}
                title={getPhaseLabel(idx)}
              >
                {idx + 1}
              </div>
            ))}
         </div>

         {/* Desktop Download Buttons */}
         <div className="hidden sm:flex items-center gap-2">
            <button 
              onClick={handleDownloadPPT}
              disabled={isDownloadingPpt || isDownloadingPdf}
              className="flex items-center gap-2 px-4 py-2 bg-orange-50 hover:bg-orange-100 text-orange-700 rounded-lg text-sm font-bold transition-colors border border-orange-200 disabled:opacity-50"
            >
              {isDownloadingPpt ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Presentation className="w-4 h-4" />
              )}
              <span>{isDownloadingPpt ? 'Generating...' : 'PPTX'}</span>
            </button>
            <button 
              onClick={handleDownloadPDF}
              disabled={isDownloadingPpt || isDownloadingPdf}
              className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-bold transition-colors border border-slate-200 disabled:opacity-50"
            >
              {isDownloadingPdf ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <FileText className="w-4 h-4" />
              )}
              <span>{isDownloadingPdf ? 'Generating...' : 'PDF'}</span>
            </button>
         </div>
      </div>

      {/* 2. Main Split Layout */}
      <div className="flex-1 bg-white rounded-3xl shadow-xl ring-1 ring-slate-900/5 flex flex-col lg:flex-row lg:overflow-hidden overflow-visible">

        {/* LEFT PANEL: Content (40% on Desktop, 100% on Mobile) */}
        <div className="lg:w-5/12 w-full flex flex-col border-r border-slate-100 bg-white relative z-10 lg:h-full h-auto">

           {/* Phase Label */}
           <div className="px-6 sm:px-8 pt-8 pb-2">
              <div className="flex items-center gap-2 text-sm font-bold text-blue-600 uppercase tracking-wider">
                 {getPhaseIcon(currentSlide)}
                 {getPhaseLabel(currentSlide)}
              </div>
           </div>

           {/* Scrollable Text Area - Scrollable on Desktop, Auto height on Mobile */}
           <div ref={contentRef} className="flex-1 lg:overflow-y-auto overflow-visible px-6 sm:px-8 pb-6 custom-scrollbar">
              <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 leading-tight mb-6">{slide.title}</h1>
              <div className="prose prose-slate prose-lg max-w-none">
                {renderMarkdown(slide.content)}
              </div>
           </div>

           {/* Vocabulary (Anchored) */}
           {slide.vocabulary.length > 0 && (
             <div className="px-6 sm:px-8 py-5 bg-slate-50 border-t border-slate-100 shrink-0">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Key Vocabulary</span>
                <div className="flex flex-wrap gap-2">
                  {slide.vocabulary.map((v, i) => (
                    <span key={i} className="px-2.5 py-1 bg-white text-slate-600 rounded border border-slate-200 text-xs font-bold shadow-sm">
                      {v}
                    </span>
                  ))}
                </div>
             </div>
           )}
        </div>

        {/* RIGHT PANEL: Visual Whiteboard (60% on Desktop, 100% on Mobile) */}
        <div className="lg:w-7/12 w-full bg-slate-50 relative flex flex-col lg:h-full min-h-[400px] border-t lg:border-t-0 border-slate-100">
            {/* Grid Pattern */}
            <div className="absolute inset-0 opacity-[0.03] pointer-events-none" 
                 style={{ backgroundImage: 'radial-gradient(#475569 1px, transparent 1px)', backgroundSize: '24px 24px' }}>
            </div>

            {/* Visual Container */}
            <div className="flex-1 w-full min-h-0 p-4 sm:p-6 flex flex-col items-center justify-center">
               <div className="w-full h-full bg-white rounded-2xl shadow-sm border border-slate-200 p-2 sm:p-4 flex items-center justify-center relative min-h-[300px]">
                  {slide.svgVisual ? (
                    <div 
                      className="w-full h-full flex items-center justify-center [&>svg]:w-full [&>svg]:h-full [&>svg]:max-w-full [&>svg]:max-h-full"
                      dangerouslySetInnerHTML={{ __html: processSVG(slide.svgVisual) }}
                    />
                  ) : (
                    <div className="flex flex-col items-center gap-3 text-slate-300">
                       <Loader2 className="w-10 h-10 animate-spin" />
                       <span className="font-medium text-sm">Generating diagram...</span>
                    </div>
                  )}
               </div>
            </div>

            {/* Caption Bar */}
            <div className="bg-white border-t border-slate-200 px-6 py-4 shrink-0 z-10 relative">
               <div className="flex gap-4 items-start">
                  <div className="bg-indigo-50 text-indigo-600 p-2 rounded-lg shrink-0 mt-0.5">
                     <Lightbulb className="w-5 h-5" />
                  </div>
                  <div>
                     <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-0.5">Visual Explanation</h4>
                     <p className="text-slate-700 font-medium leading-snug text-sm">
                       {slide.visualDescription}
                     </p>
                  </div>
               </div>
            </div>
        </div>
      </div>

      {/* 3. Footer Navigation */}
      <div className="flex justify-between items-center pb-2 pt-2 lg:pt-0">
         <button
            onClick={prevSlide}
            disabled={currentSlide === 0}
            className="flex items-center gap-2 px-4 sm:px-5 py-3 rounded-xl text-slate-600 hover:text-slate-900 hover:bg-white font-semibold transition-all disabled:opacity-30 disabled:hover:bg-transparent text-sm sm:text-base"
         >
            <ChevronLeft className="w-5 h-5" />
            <span>Back</span>
         </button>

         {currentSlide === slides.length - 1 ? (
            <button
               onClick={onRestart}
               className="bg-slate-900 text-white px-6 sm:px-8 py-3 rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg hover:shadow-slate-900/20 flex items-center gap-2 text-sm sm:text-base"
            >
               <span>Complete Lesson</span>
               <RotateCcw className="w-4 h-4" />
            </button>
         ) : (
            <button
               onClick={nextSlide}
               className="bg-blue-600 text-white px-6 sm:px-8 py-3 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg hover:shadow-blue-600/30 flex items-center gap-2 group text-sm sm:text-base"
            >
               <span>Next Step</span>
               <ArrowRight className="w-4 h-4 group-hover:translate-x-0.5 transition-transform" />
            </button>
         )}
      </div>

      {/* Hidden Print Container for PDF Generation */}
      <div className="fixed left-[-9999px] top-0" ref={printRef}>
        {slides.map((s, idx) => (
          <div key={idx} className="w-[1200px] h-[800px] bg-white p-12 flex flex-col relative border border-slate-200">
             {/* Print Header */}
             <div className="flex justify-between items-center mb-8 border-b border-slate-100 pb-4">
               <div>
                  <h1 className="text-4xl font-bold text-slate-900">{s.title}</h1>
                  <span className="text-slate-500 font-medium mt-2 block">{getPhaseLabel(idx)} - Step {idx + 1} of {slides.length}</span>
               </div>
               <div className="bg-slate-100 px-4 py-2 rounded-lg">
                 <span className="text-slate-500 font-bold tracking-widest">FLORIDA B.E.S.T. MATH</span>
               </div>
             </div>

             <div className="flex gap-12 flex-1">
                {/* Print Content */}
                <div className="w-5/12 text-xl leading-relaxed text-slate-700 space-y-4">
                  {renderMarkdown(s.content)}

                  {s.vocabulary.length > 0 && (
                    <div className="mt-8 pt-8 border-t border-slate-100">
                      <span className="text-sm font-bold text-slate-400 uppercase tracking-wider block mb-3">Vocabulary</span>
                      <div className="flex flex-wrap gap-2">
                        {s.vocabulary.map(v => (
                          <span key={v} className="px-3 py-1 bg-slate-100 text-slate-600 rounded border border-slate-200 text-sm font-bold">{v}</span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {/* Print Visual */}
                <div className="w-7/12 flex flex-col">
                  <div className="flex-1 bg-slate-50 rounded-xl border border-slate-200 p-8 flex items-center justify-center">
                    <div 
                      className="w-full h-full flex items-center justify-center [&>svg]:w-full [&>svg]:h-full [&>svg]:max-w-full [&>svg]:max-h-full"
                      dangerouslySetInnerHTML={{ __html: processSVG(s.svgVisual) }} 
                    />
                  </div>
                  <div className="mt-6 bg-blue-50 p-6 rounded-xl border-l-4 border-blue-500">
                     <h4 className="font-bold text-blue-900 mb-2 flex items-center gap-2">
                       <Lightbulb className="w-5 h-5" /> Visual Insight
                     </h4>
                     <p className="text-blue-800 text-lg">{s.visualDescription}</p>
                  </div>
                </div>
             </div>
          </div>
        ))}
      </div>

    </div>
  );
};

export default RemedialSlides;

import { GoogleGenAI, Schema, Type } from "@google/genai";
import { Standard, Quiz, GapAnalysis, RemedialSlide, GapType, QuizResult, Question } from '../types';
import { MTR_STANDARDS } from '../constants';

// Helper to get client instance - ensures fresh connection for each request
const getAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateQuiz = async (standard: Standard): Promise<Quiz> => {
  const ai = getAiClient();

  const prompt = `
    You are an expert Florida B.E.S.T. Mathematics Standards curriculum designer.
    Create a 5-question multiple-choice quiz for the following standard:

    Code: ${standard.code}
    Description: ${standard.description}
    Clarifications: ${standard.clarifications?.join(' ') || 'None provided.'}
    Examples: ${standard.examples?.join(' ') || 'None provided.'}

    The questions must:
    1. Be strictly aligned to the standard.
    2. Incorporate the Florida MTR (Mathematical Thinking and Reasoning) standards where possible.
    3. Include 4 options (A-D) with one correct answer.
    4. Provide a visual animation description that would help explain the concept to a student.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      text: { type: Type.STRING },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Must contain exactly 4 options"
      },
      correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
      explanation: { type: Type.STRING },
      animationDescription: { type: Type.STRING }
    },
    required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: {
        type: Type.ARRAY,
        items: questionSchema
      }
    },
    required: ["standardCode", "questions"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a rigid JSON generator for educational content."
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as Quiz;
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    throw error;
  }
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  const ai = getAiClient();

  // Pass comprehensive question performance data to the AI
  const detailedAnalysis = questions.map((q, i) => {
    const r = results[i];
    return `
      Question ${i + 1}: ${q.text}
      Options: ${q.options.join(', ')}
      Correct Answer: ${q.options[q.correctAnswerIndex]}
      Student Selected: ${q.options[r.selectedOptionIndex]}
      Is Correct: ${r.isCorrect}
    `;
  }).join('\n---\n');

  const prompt = `
    Analyze the following student performance on a quiz for Florida Standard ${standard.code}: ${standard.description}.

    Detailed Performance:
    ${detailedAnalysis}

    Tasks:
    1. **Sub-skill Analysis**: Break down the standard into 2-4 distinct sub-skills or component skills relevant to these specific questions. For each sub-skill, determine how many questions related to it and how many were correct.
    2. **Misconception Detection**: For incorrect answers, analyze the specific distractor (wrong option) selected by the student. Does it indicate a common mathematical misconception (e.g., "adding denominators", "confusing perimeter with area", "place value alignment error")?
    3. **Gap Diagnosis**: Aggregate the errors into learning gaps.

    **Confidence Score Calculation**:
    Provide a confidence score (0-100) based on the consistency of the error pattern:
    - **High (85-100)**: The student makes the *same specific type of error* across multiple questions (e.g., always adds denominators).
    - **Medium (60-84)**: The student struggles with a general concept but errors vary slightly or there is only 1 error to analyze.
    - **Low (0-59)**: The errors appear random, suggesting guessing, or there is not enough data to form a strong conclusion.
  `;

  const subSkillSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      description: { type: Type.STRING },
      correctCount: { type: Type.INTEGER },
      totalCount: { type: Type.INTEGER }
    },
    required: ["name", "description", "correctCount", "totalCount"]
  };

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } },
      misconception: { type: Type.STRING, description: "The specific misconception identified from the wrong answer chosen." }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      subSkills: { type: Type.ARRAY, items: subSkillSchema },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "subSkills", "confidenceScore", "summary"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GapAnalysis;
  } catch (error) {
    console.error("Gap Analysis Error:", error);
    throw error;
  }
};

export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  const ai = getAiClient();

  const prompt = `
    You are a master math tutor designing a specialized 5-step lesson plan to fix a student's specific learning gap.

    Target Standard: ${standard.code} (${standard.description})

    **DIAGNOSED GAPS (Prioritize these):**
    ${analysis.identifiedGaps.map(g => `• ${g.description} (Misconception: ${g.misconception || 'General error'})`).join('\n')}

    **INSTRUCTIONAL STRATEGY:**
    - The lesson must tell a cohesive story.
    - **Critical Info First**: Start the content with the most important concept in **bold**.
    - Keep text concise (bullet points prefered).

    **LESSON PLAN STRUCTURE (Exactly 5 Slides):**
    1.  **The Hook (Definition)**: Define the core concept simply. Why does it matter?
    2.  **Visual Proof (Mental Model)**: Show *why* it works using a visual model (e.g. Area model for multiplication).
    3.  **Step-by-Step (Walkthrough)**: Solve a specific problem relevant to the gap. Break it into 3 steps.
    4.  **The Fix (Misconception)**: Directly address the error. "You might think X, but it's Y because...".
    5.  **Summary (Key Takeaway)**: A final rule or formula to memorize.

    **STRICT SVG VISUAL GENERATION RULES:**
    1.  **Aspect Ratio**: 16:9. Use ViewBox "0 0 800 450".
    2.  **Layout**: 
        - Leave 10% padding around edges.
        - **NO OVERLAPPING**: Ensure text labels do not overlap with lines or shapes.
        - Center main elements.
    3.  **Typography**:
        - Use sans-serif fonts.
        - Use \`text-anchor="middle"\` and \`dominant-baseline="middle"\` for centering text.
        - For text on top of lines, use \`paint-order="stroke" stroke="white" stroke-width="4"\` to create a halo effect.
        - Font size: 20px - 28px for legibility.
    4.  **Colors**:
        - Primary: Blue (#3b82f6)
        - Success: Emerald (#10b981)
        - Warning: Amber (#f59e0b)
        - Error: Red (#ef4444)
        - Text: Slate (#1e293b)
    5.  **Content**:
        - The visual MUST be an **exact representation** of the math described (e.g. if the text says 3/4, the pie chart must show exactly 3/4).
        - Use Number Lines, Tape Diagrams, Area Models, Coordinate Planes.
    6.  **Output**: Valid static SVG string.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING, description: "The teacher's explanation in Markdown. Keep concise." },
      visualDescription: { type: Type.STRING, description: "A 1-sentence caption connecting the image to the concept." },
      svgVisual: { type: Type.STRING, description: "Static SVG string. ViewBox 0 0 800 450." },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slides: { type: Type.ARRAY, items: slideSchema }
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data.slides as RemedialSlide[];
  } catch (error) {
    console.error("Slide Generation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { RemedialSlide } from '../types';
import { ChevronLeft, ChevronRight, BookOpen, Brain, Calculator, AlertTriangle, Lightbulb, RotateCcw, Map, CheckCircle2, ArrowRight, Download, FileText, Loader2, Presentation, Maximize2, Minimize2 } from 'lucide-react';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';
import pptxgen from 'pptxgenjs';

interface Props {
  slides: RemedialSlide[];
  onRestart: () => void;
}

// Icons based on lesson phase
const getPhaseIcon = (index: number) => {
  switch(index) {
    case 0: return <BookOpen className="w-5 h-5 text-blue-600" />;
    case 1: return <Brain className="w-5 h-5 text-purple-600" />;
    case 2: return <Calculator className="w-5 h-5 text-indigo-600" />;
    case 3: return <AlertTriangle className="w-5 h-5 text-amber-600" />;
    case 4: return <CheckCircle2 className="w-5 h-5 text-emerald-600" />;
    default: return <Map className="w-5 h-5 text-slate-600" />;
  }
};

const getPhaseLabel = (index: number) => {
  switch(index) {
    case 0: return "Concept";
    case 1: return "Model";
    case 2: return "Example";
    case 3: return "Pitfall";
    case 4: return "Takeaway";
    default: return `Part ${index + 1}`;
  }
};

const processSVG = (svgString: string | undefined) => {
  if (!svgString) return '';
  let processed = svgString;
  if (!processed.includes('preserveAspectRatio')) {
    processed = processed.replace('<svg', '<svg preserveAspectRatio="xMidYMid meet"');
  }
  // Ensure width/height are set to 100% for container fitting
  processed = processed.replace(/width="[^"]*"/, 'width="100%"').replace(/height="[^"]*"/, 'height="100%"');
  return processed;
};

// Reusable Slide Layout Component for Screen and Print
const SlideLayout = ({ slide, index, total, isPrint = false }: { slide: RemedialSlide, index: number, total: number, isPrint?: boolean }) => {

  const renderMarkdown = (text: string) => {
    return text.split('\n').map((line, i) => {
      if (line.startsWith('###')) return <h3 key={i} className="text-lg font-bold text-slate-800 mt-4 mb-2">{line.replace('###', '')}</h3>;
      if (line.startsWith('##')) return <h2 key={i} className="text-xl font-bold text-slate-900 mt-4 mb-2">{line.replace('##', '')}</h2>;

      if (line.trim().startsWith('>')) {
        return (
          <div key={i} className="my-3 p-3 bg-amber-50 border-l-4 border-amber-400 rounded-r-lg shadow-sm">
             <div className="flex gap-2">
               <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0 mt-1" />
               <div className="text-amber-900 font-medium text-sm leading-relaxed">
                 {line.replace('>', '').replace(/\*\*/g, '')}
               </div>
             </div>
          </div>
        );
      }

      if (line.trim().match(/^\d+\./)) {
         return (
           <div key={i} className="flex gap-2 mb-2">
              <span className="flex-shrink-0 w-6 h-6 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center text-xs font-bold mt-0.5">
                {line.trim().split('.')[0]}
              </span>
              <p className="flex-1 text-slate-700 leading-relaxed text-base">
                {line.replace(/^\d+\./, '').trim().replace(/\*\*(.*?)\*\*/g, (match, p1) => p1)}
              </p>
           </div>
         );
      }

      if (line.trim().startsWith('-') || line.trim().startsWith('•')) {
        return (
          <li key={i} className="flex gap-2 mb-2 text-slate-700 text-base leading-relaxed pl-1">
             <div className="w-1.5 h-1.5 rounded-full bg-blue-400 mt-2 shrink-0" />
             <span>{line.replace(/^-|•/, '').trim().replace(/\*\*(.*?)\*\*/g, (match, p1) => p1)}</span>
          </li>
        );
      }

      if (line.trim() === '') return <div key={i} className="h-2"></div>;

      return (
        <p key={i} className="mb-2 text-slate-700 leading-relaxed text-base">
          {line.split(/(\*\*.*?\*\*)/).map((part, idx) => {
            if (part.startsWith('**') && part.endsWith('**')) {
              return <strong key={idx} className="text-slate-900 font-bold">{part.slice(2, -2)}</strong>;
            }
            return part;
          })}
        </p>
      );
    });
  };

  return (
    <div className={`flex flex-col bg-white overflow-hidden relative ${isPrint ? 'w-[1280px] h-[720px]' : 'w-full h-full'}`}>

      {/* HEADER: Title & Status */}
      <div className={`bg-slate-50 border-b border-slate-200 flex items-center justify-between px-8 shrink-0 ${isPrint ? 'h-24' : 'h-[15%]'}`}>
         <div className="flex items-center gap-4">
            <div className="bg-white p-2 rounded-lg shadow-sm border border-slate-100">
               {getPhaseIcon(index)}
            </div>
            <div>
               <div className="flex items-center gap-2 mb-0.5">
                  <span className="text-xs font-bold text-blue-600 uppercase tracking-widest">{getPhaseLabel(index)}</span>
                  <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                  <span className="text-xs font-medium text-slate-400">Step {index + 1} of {total}</span>
               </div>
               <h2 className="text-2xl font-bold text-slate-900 leading-tight line-clamp-1">{slide.title}</h2>
            </div>
         </div>
         <div className="bg-slate-200/50 text-slate-400 font-mono text-xs px-2 py-1 rounded">
            FLORIDA B.E.S.T.
         </div>
      </div>

      {/* BODY: Split Content */}
      <div className="flex-1 flex overflow-hidden">
         {/* Left: Text Content */}
         <div className={`w-[45%] flex flex-col ${isPrint ? 'p-10' : 'p-8 overflow-y-auto'}`}>
            <div className="prose prose-slate prose-lg max-w-none flex-1">
               {renderMarkdown(slide.content)}
            </div>

            {/* Vocabulary Footer in Left Col */}
            {slide.vocabulary.length > 0 && (
              <div className="mt-6 pt-6 border-t border-slate-100">
                 <span className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-2">Key Vocabulary</span>
                 <div className="flex flex-wrap gap-2">
                    {slide.vocabulary.map((v, i) => (
                      <span key={i} className="px-2 py-1 bg-slate-50 text-slate-600 rounded border border-slate-200 text-xs font-bold">
                        {v}
                      </span>
                    ))}
                 </div>
              </div>
            )}
         </div>

         {/* Right: Visual */}
         <div className="w-[55%] bg-slate-50/50 border-l border-slate-100 flex flex-col">
            <div className="flex-1 p-6 flex items-center justify-center relative">
               {/* Pattern Background */}
               <div className="absolute inset-0 opacity-[0.05]" 
                    style={{ backgroundImage: 'radial-gradient(#64748b 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
               </div>

               {/* SVG Card */}
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 w-full aspect-video flex items-center justify-center p-2 relative z-10">
                  {slide.svgVisual ? (
                     <div 
                       className="w-full h-full flex items-center justify-center [&>svg]:w-full [&>svg]:h-full [&>svg]:max-w-full [&>svg]:max-h-full"
                       dangerouslySetInnerHTML={{ __html: processSVG(slide.svgVisual) }}
                     />
                  ) : (
                     <div className="flex flex-col items-center gap-2 text-slate-300">
                        <Loader2 className="w-8 h-8 animate-spin" />
                        <span className="text-sm">Loading Visual...</span>
                     </div>
                  )}
               </div>
            </div>

            {/* Caption Area */}
            <div className="px-8 pb-8 pt-0 z-10">
               <div className="bg-white border border-blue-100 rounded-lg p-4 shadow-sm flex gap-3">
                  <Lightbulb className="w-5 h-5 text-blue-500 shrink-0 mt-0.5" />
                  <div>
                     <span className="block text-xs font-bold text-blue-400 uppercase tracking-wide mb-0.5">Visual Insight</span>
                     <p className="text-sm text-slate-700 font-medium leading-relaxed">{slide.visualDescription}</p>
                  </div>
               </div>
            </div>
         </div>
      </div>
    </div>
  );
};

const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);
  const [isDownloadingPpt, setIsDownloadingPpt] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const printRef = useRef<HTMLDivElement>(null);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const handleDownloadPDF = async () => {
    if (!printRef.current) return;
    setIsDownloadingPdf(true);

    try {
      const pdf = new jsPDF({
        orientation: 'landscape',
        unit: 'px',
        format: [1280, 720] // 16:9 HD 720p
      });

      const slidesElements = printRef.current.children;

      for (let i = 0; i < slidesElements.length; i++) {
        const element = slidesElements[i] as HTMLElement;
        await new Promise(resolve => setTimeout(resolve, 50)); // Small yield

        const canvas = await html2canvas(element, {
          scale: 2, 
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.90);

        if (i > 0) pdf.addPage();
        pdf.addImage(imgData, 'JPEG', 0, 0, 1280, 720);
      }

      pdf.save('Math-Lesson-Plan.pdf');
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('Could not generate PDF.');
    } finally {
      setIsDownloadingPdf(false);
    }
  };

  const svgToPng = (svgString: string): Promise<string> => {
    return new Promise((resolve) => {
      let cleanedSvg = svgString.trim();
      if (!cleanedSvg.includes('xmlns=')) cleanedSvg = cleanedSvg.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');

      const img = new Image();
      const svgBlob = new Blob([cleanedSvg], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);

      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 1600; // High res for PPT
        canvas.height = 900; // 16:9
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          resolve(canvas.toDataURL('image/png'));
        }
        URL.revokeObjectURL(url);
      };
      img.onerror = () => resolve('');
      img.src = url;
    });
  };

  const handleDownloadPPT = async () => {
    setIsDownloadingPpt(true);
    try {
      const pres = new pptxgen();
      pres.layout = 'LAYOUT_16x9';

      for (let i = 0; i < slides.length; i++) {
        const s = slides[i];
        const slide = pres.addSlide();

        // Header Bar
        slide.addShape(pres.ShapeType.rect, { x: 0, y: 0, w: '100%', h: 1.2, fill: { color: 'F8FAFC' } });
        slide.addText(s.title, { x: 0.5, y: 0.3, w: 9, h: 0.6, fontSize: 24, bold: true, color: '0F172A' });
        slide.addText(`${getPhaseLabel(i)} | Step ${i+1}`, { x: 0.5, y: 0.8, fontSize: 12, color: '64748B' });

        // Content
        const cleanContent = s.content.replace(/\*\*/g, '').replace(/###/g, '');
        slide.addText(cleanContent, { x: 0.5, y: 1.5, w: 4.5, h: 4.5, fontSize: 16, color: '334155', valign: 'top' });

        // Visual
        if (s.svgVisual) {
          const png = await svgToPng(s.svgVisual);
          if (png) slide.addImage({ data: png, x: 5.2, y: 1.5, w: 4.5, h: 2.53 }); // 16:9 box approx
        }

        // Caption
        slide.addText(s.visualDescription, { 
          x: 5.2, y: 4.2, w: 4.5, h: 1.0, 
          fontSize: 11, color: '3B82F6', 
          fill: { color: 'F0F9FF' }, shape: pres.ShapeType.rect 
        });
      }
      await pres.writeFile({ fileName: 'Math-Lesson.pptx' });
    } catch (e) {
      console.error(e);
      alert('PPT Generation Failed');
    } finally {
      setIsDownloadingPpt(false);
    }
  };

  return (
    <div className="flex flex-col gap-6 w-full max-w-[1280px] mx-auto p-4">

      {/* Control Bar */}
      <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200 gap-4">
         <div>
            <h1 className="text-lg font-bold text-slate-800">Remedial Lesson Plan</h1>
            <p className="text-xs text-slate-500">Standard-aligned personalized intervention</p>
         </div>

         <div className="flex items-center gap-2">
            <button 
              onClick={handleDownloadPPT} disabled={isDownloadingPpt}
              className="flex items-center gap-2 px-4 py-2 bg-orange-50 text-orange-700 rounded-lg text-sm font-bold border border-orange-200 hover:bg-orange-100 transition-colors disabled:opacity-50">
              {isDownloadingPpt ? <Loader2 className="w-4 h-4 animate-spin" /> : <Presentation className="w-4 h-4" />}
              <span>PPTX</span>
            </button>
            <button 
              onClick={handleDownloadPDF} disabled={isDownloadingPdf}
              className="flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg text-sm font-bold border border-slate-200 hover:bg-slate-200 transition-colors disabled:opacity-50">
              {isDownloadingPdf ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
              <span>PDF</span>
            </button>
            <button 
               onClick={() => setIsFullscreen(!isFullscreen)}
               className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg hidden lg:block"
               title={isFullscreen ? "Exit Fullscreen" : "Fullscreen Mode"}
            >
               {isFullscreen ? <Minimize2 className="w-5 h-5" /> : <Maximize2 className="w-5 h-5" />}
            </button>
         </div>
      </div>

      {/* Main Slide Stage */}
      <div className={`relative transition-all duration-300 ${isFullscreen ? 'fixed inset-0 z-50 bg-slate-900 p-8 flex items-center justify-center' : 'w-full aspect-video'}`}>

         <div className={`bg-white rounded-xl shadow-2xl overflow-hidden flex flex-col relative w-full ${isFullscreen ? 'max-w-[1600px] aspect-video' : 'h-full'}`}>
            <SlideLayout slide={slides[currentSlide]} index={currentSlide} total={slides.length} />

            {/* Overlay Navigation Arrows */}
            <button onClick={prevSlide} disabled={currentSlide === 0} 
              className="absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-white/80 hover:bg-white text-slate-800 shadow-lg border border-slate-100 disabled:opacity-0 transition-all hover:scale-110">
              <ChevronLeft className="w-6 h-6" />
            </button>

            <button onClick={nextSlide} disabled={currentSlide === slides.length - 1}
              className="absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-blue-600 hover:bg-blue-700 text-white shadow-lg border border-blue-500 disabled:opacity-0 transition-all hover:scale-110">
              <ChevronRight className="w-6 h-6" />
            </button>
         </div>

         {isFullscreen && (
            <button onClick={() => setIsFullscreen(false)} className="absolute top-4 right-4 text-white/50 hover:text-white">
              <Minimize2 className="w-8 h-8" />
            </button>
         )}
      </div>

      {/* Progress Footer */}
      <div className="flex justify-center items-center gap-2">
         {slides.map((_, idx) => (
           <button 
             key={idx} 
             onClick={() => setCurrentSlide(idx)}
             className={`w-3 h-3 rounded-full transition-all ${idx === currentSlide ? 'bg-blue-600 w-8' : 'bg-slate-300 hover:bg-slate-400'}`}
           />
         ))}
         {currentSlide === slides.length - 1 && (
            <button onClick={onRestart} className="ml-4 flex items-center gap-2 text-slate-500 hover:text-slate-800 text-sm font-medium">
               <RotateCcw className="w-4 h-4" /> Start Over
            </button>
         )}
      </div>

      {/* Hidden Print Container */}
      <div className="fixed left-[-9999px] top-0" ref={printRef}>
        {slides.map((s, idx) => (
          <SlideLayout key={idx} slide={s} index={idx} total={slides.length} isPrint={true} />
        ))}
      </div>

    </div>
  );
};

