const RemedialSlides: React.FC<Props> = ({ slides, onRestart }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);
  const [isDownloadingPpt, setIsDownloadingPpt] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const printRef = useRef<HTMLDivElement>(null);

  const nextSlide = () => {
    if (currentSlide < slides.length - 1) setCurrentSlide(curr => curr + 1);
  };

  const prevSlide = () => {
    if (currentSlide > 0) setCurrentSlide(curr => curr - 1);
  };

  const handleDownloadPDF = async () => {
    if (!printRef.current) return;
    setIsDownloadingPdf(true);

    try {
      const pdf = new jsPDF({
        orientation: 'landscape',
        unit: 'px',
        format: [1280, 720] // 16:9 HD 720p
      });

      const slidesElements = printRef.current.children;

      for (let i = 0; i < slidesElements.length; i++) {
        const element = slidesElements[i] as HTMLElement;
        await new Promise(resolve => setTimeout(resolve, 50)); // Small yield

        const canvas = await html2canvas(element, {
          scale: 2, 
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.90);

        if (i > 0) pdf.addPage();
        pdf.addImage(imgData, 'JPEG', 0, 0, 1280, 720);
      }

      pdf.save('Math-Lesson-Plan.pdf');
    } catch (error) {
      console.error('PDF Generation failed', error);
      alert('Could not generate PDF.');
    } finally {
      setIsDownloadingPdf(false);
    }
  };

  const svgToPng = (svgString: string): Promise<string> => {
    return new Promise((resolve) => {
      let cleanedSvg = svgString.trim();
      if (!cleanedSvg.includes('xmlns=')) cleanedSvg = cleanedSvg.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');

      const img = new Image();
      const svgBlob = new Blob([cleanedSvg], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);

      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 1600; // High res for PPT
        canvas.height = 900; // 16:9
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          resolve(canvas.toDataURL('image/png'));
        }
        URL.revokeObjectURL(url);
      };
      img.onerror = () => resolve('');
      img.src = url;
    });
  };

  const handleDownloadPPT = async () => {
    setIsDownloadingPpt(true);
    try {
      const pres = new pptxgen();
      pres.layout = 'LAYOUT_16x9';

      for (let i = 0; i < slides.length; i++) {
        const s = slides[i];
        const slide = pres.addSlide();

        // Header Bar
        slide.addShape(pres.ShapeType.rect, { x: 0, y: 0, w: '100%', h: 1.2, fill: { color: 'F8FAFC' } });
        slide.addText(s.title, { x: 0.5, y: 0.3, w: 9, h: 0.6, fontSize: 24, bold: true, color: '0F172A' });
        slide.addText(`${getPhaseLabel(i)} | Step ${i+1}`, { x: 0.5, y: 0.8, fontSize: 12, color: '64748B' });

        // Content
        const cleanContent = s.content.replace(/\*\*/g, '').replace(/###/g, '');
        slide.addText(cleanContent, { x: 0.5, y: 1.5, w: 4.5, h: 4.5, fontSize: 16, color: '334155', valign: 'top' });

        // Visual
        if (s.svgVisual) {
          const png = await svgToPng(s.svgVisual);
          if (png) slide.addImage({ data: png, x: 5.2, y: 1.5, w: 4.5, h: 2.53 }); // 16:9 box approx
        }

        // Caption
        slide.addText(s.visualDescription, { 
          x: 5.2, y: 4.2, w: 4.5, h: 1.0, 
          fontSize: 11, color: '3B82F6', 
          fill: { color: 'F0F9FF' }, shape: pres.ShapeType.rect 
        });
      }
      await pres.writeFile({ fileName: 'Math-Lesson.pptx' });
    } catch (e) {
      console.error(e);
      alert('PPT Generation Failed');
    } finally {
      setIsDownloadingPpt(false);
    }
  };

  return (
    <div className="flex flex-col gap-6 w-full max-w-[1280px] mx-auto p-4">

      {/* Control Bar */}
      <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200 gap-4">
         <div>
            <h1 className="text-lg font-bold text-slate-800">Remedial Lesson Plan</h1>
            <p className="text-xs text-slate-500">Standard-aligned personalized intervention</p>
         </div>

         <div className="flex items-center gap-2">
            <button 
              onClick={handleDownloadPPT} disabled={isDownloadingPpt}
              className="flex items-center gap-2 px-4 py-2 bg-orange-50 text-orange-700 rounded-lg text-sm font-bold border border-orange-200 hover:bg-orange-100 transition-colors disabled:opacity-50">
              {isDownloadingPpt ? <Loader2 className="w-4 h-4 animate-spin" /> : <Presentation className="w-4 h-4" />}
              <span>PPTX</span>
            </button>
            <button 
              onClick={handleDownloadPDF} disabled={isDownloadingPdf}
              className="flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg text-sm font-bold border border-slate-200 hover:bg-slate-200 transition-colors disabled:opacity-50">
              {isDownloadingPdf ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
              <span>PDF</span>
            </button>
            <button 
               onClick={() => setIsFullscreen(!isFullscreen)}
               className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg hidden lg:block"
               title={isFullscreen ? "Exit Fullscreen" : "Fullscreen Mode"}
            >
               {isFullscreen ? <Minimize2 className="w-5 h-5" /> : <Maximize2 className="w-5 h-5" />}
            </button>
         </div>
      </div>

      {/* Main Slide Stage */}
      <div className={`relative transition-all duration-300 ${isFullscreen ? 'fixed inset-0 z-50 bg-slate-900 p-8 flex items-center justify-center' : 'w-full aspect-video'}`}>

         <div className={`bg-white rounded-xl shadow-2xl overflow-hidden flex flex-col relative w-full ${isFullscreen ? 'max-w-[1600px] aspect-video' : 'h-full'}`}>
            <SlideLayout slide={slides[currentSlide]} index={currentSlide} total={slides.length} />

            {/* Overlay Navigation Arrows */}
            <button onClick={prevSlide} disabled={currentSlide === 0} 
              className="absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-white/80 hover:bg-white text-slate-800 shadow-lg border border-slate-100 disabled:opacity-0 transition-all hover:scale-110">
              <ChevronLeft className="w-6 h-6" />
            </button>

            <button onClick={nextSlide} disabled={currentSlide === slides.length - 1}
              className="absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-blue-600 hover:bg-blue-700 text-white shadow-lg border border-blue-500 disabled:opacity-0 transition-all hover:scale-110">
              <ChevronRight className="w-6 h-6" />
            </button>
         </div>

         {isFullscreen && (
            <button onClick={() => setIsFullscreen(false)} className="absolute top-4 right-4 text-white/50 hover:text-white">
              <Minimize2 className="w-8 h-8" />
            </button>
         )}
      </div>

      {/* Progress Footer */}
      <div className="flex justify-center items-center gap-2">
         {slides.map((_, idx) => (
           <button 
             key={idx} 
             onClick={() => setCurrentSlide(idx)}
             className={`w-3 h-3 rounded-full transition-all ${idx === currentSlide ? 'bg-blue-600 w-8' : 'bg-slate-300 hover:bg-slate-400'}`}
           />
         ))}
         {currentSlide === slides.length - 1 && (
            <button onClick={onRestart} className="ml-4 flex items-center gap-2 text-slate-500 hover:text-slate-800 text-sm font-medium">
               <RotateCcw className="w-4 h-4" /> Start Over
            </button>
         )}
      </div>

      {/* Hidden Print Container */}
      <div className="fixed left-[-9999px] top-0" ref={printRef}>
        {slides.map((s, idx) => (
          <SlideLayout key={idx} slide={s} index={idx} total={slides.length} isPrint={true} />
        ))}
      </div>

    </div>
  );
};

export default RemedialSlides;

import { GoogleGenAI, Schema, Type } from "@google/genai";
import { Standard, Quiz, GapAnalysis, RemedialSlide, GapType, QuizResult, Question } from '../types';
import { MTR_STANDARDS } from '../constants';

// Helper to get client instance - ensures fresh connection for each request
const getAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateQuiz = async (standard: Standard): Promise<Quiz> => {
  const ai = getAiClient();

  const prompt = `
    You are an expert Florida B.E.S.T. Mathematics Standards curriculum designer.
    Create a 5-question multiple-choice quiz for the following standard:

    Code: ${standard.code}
    Description: ${standard.description}
    Clarifications: ${standard.clarifications?.join(' ') || 'None provided.'}
    Examples: ${standard.examples?.join(' ') || 'None provided.'}

    The questions must:
    1. Be strictly aligned to the standard.
    2. Incorporate the Florida MTR (Mathematical Thinking and Reasoning) standards where possible.
    3. Include 4 options (A-D) with one correct answer.
    4. Provide a visual animation description that would help explain the concept to a student.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      text: { type: Type.STRING },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Must contain exactly 4 options"
      },
      correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
      explanation: { type: Type.STRING },
      animationDescription: { type: Type.STRING }
    },
    required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: {
        type: Type.ARRAY,
        items: questionSchema
      }
    },
    required: ["standardCode", "questions"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a rigid JSON generator for educational content."
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as Quiz;
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    throw error;
  }
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  const ai = getAiClient();

  // Pass comprehensive question performance data to the AI
  const detailedAnalysis = questions.map((q, i) => {
    const r = results[i];
    return `
      Question ${i + 1}: ${q.text}
      Options: ${q.options.join(', ')}
      Correct Answer: ${q.options[q.correctAnswerIndex]}
      Student Selected: ${q.options[r.selectedOptionIndex]}
      Is Correct: ${r.isCorrect}
    `;
  }).join('\n---\n');

  const prompt = `
    Analyze the following student performance on a quiz for Florida Standard ${standard.code}: ${standard.description}.

    Detailed Performance:
    ${detailedAnalysis}

    Tasks:
    1. **Sub-skill Analysis**: Break down the standard into 2-4 distinct sub-skills or component skills relevant to these specific questions. For each sub-skill, determine how many questions related to it and how many were correct.
    2. **Misconception Detection**: For incorrect answers, analyze the specific distractor (wrong option) selected by the student. Does it indicate a common mathematical misconception (e.g., "adding denominators", "confusing perimeter with area", "place value alignment error")?
    3. **Gap Diagnosis**: Aggregate the errors into learning gaps.

    **Confidence Score Calculation**:
    Provide a confidence score (0-100) based on the consistency of the error pattern:
    - **High (85-100)**: The student makes the *same specific type of error* across multiple questions (e.g., always adds denominators).
    - **Medium (60-84)**: The student struggles with a general concept but errors vary slightly or there is only 1 error to analyze.
    - **Low (0-59)**: The errors appear random, suggesting guessing, or there is not enough data to form a strong conclusion.
  `;

  const subSkillSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      description: { type: Type.STRING },
      correctCount: { type: Type.INTEGER },
      totalCount: { type: Type.INTEGER }
    },
    required: ["name", "description", "correctCount", "totalCount"]
  };

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } },
      misconception: { type: Type.STRING, description: "The specific misconception identified from the wrong answer chosen." }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      subSkills: { type: Type.ARRAY, items: subSkillSchema },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "subSkills", "confidenceScore", "summary"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as GapAnalysis;
  } catch (error) {
    console.error("Gap Analysis Error:", error);
    throw error;
  }
};

