// Helper to get client instance - ensures fresh connection for each request
const getAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Retry helper with exponential backoff for handling 429/Quota errors
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function callWithRetry<T>(operation: () => Promise<T>, retries = 3, baseDelay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const isQuotaError = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.toLowerCase().includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED';

    if (retries > 0 && isQuotaError) {
      const waitTime = baseDelay * Math.pow(2, 3 - retries); // 2s, 4s, 8s
      console.warn(`Quota/Rate limit hit. Retrying in ${waitTime}ms...`);
      await delay(waitTime);
      return callWithRetry(operation, retries - 1, baseDelay);
    }
    throw error;
  }
}

export const generateQuiz = async (standard: Standard): Promise<Quiz> => {
  const ai = getAiClient();

  const prompt = `
    You are an expert Florida B.E.S.T. Mathematics Standards curriculum designer.
    Create a 5-question multiple-choice quiz for the following standard:

    Code: ${standard.code}
    Description: ${standard.description}
    Clarifications: ${standard.clarifications?.join(' ') || 'None provided.'}
    Examples: ${standard.examples?.join(' ') || 'None provided.'}

    The questions must:
    1. Be strictly aligned to the standard.
    2. Incorporate the Florida MTR (Mathematical Thinking and Reasoning) standards where possible.
    3. Include 4 options (A-D) with one correct answer.
    4. Provide a visual animation description that would help explain the concept to a student.

    **CRITICAL FOR YOUNGER GRADES (K-2):**
    If the standard implies visual recognition (e.g., "Count the objects", "Identify the shape", "Compare groups", "Look at the graph"), you **MUST** provide a 'visual' field containing valid SVG code.

    **SVG Visual Rules:**
    - **ViewBox**: "0 0 400 250"
    - **Style**: Clean, colorful, simple shapes (circles, squares, stars). High contrast.
    - **Accuracy**: The visual must EXACTLY match the question data (e.g., if the question asks to count 5 apples, draw exactly 5 red circles).
    - **Layout**: Center content, ensure nothing is cut off.
    - If no visual is needed (purely text problem), leave the 'visual' field empty.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const questionSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      text: { type: Type.STRING },
      options: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: "Must contain exactly 4 options"
      },
      correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
      explanation: { type: Type.STRING },
      animationDescription: { type: Type.STRING },
      visual: { type: Type.STRING, description: "Valid SVG string for questions requiring an image (e.g., counting objects). Optional." }
    },
    required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: {
        type: Type.ARRAY,
        items: questionSchema
      }
    },
    required: ["standardCode", "questions"]
  };

  return callWithRetry(async () => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema,
          systemInstruction: "You are a rigid JSON generator for educational content."
        }
      });

      const text = response.text;
      if (!text) throw new Error("No response from AI");

      return JSON.parse(text) as Quiz;
    } catch (error) {
      console.error("Quiz Generation Error:", error);
      throw error;
    }
  });
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  const ai = getAiClient();

  // Pass comprehensive question performance data to the AI
  const detailedAnalysis = questions.map((q, i) => {
    const r = results[i];
    return `
      Question ${i + 1}: ${q.text}
      Options: ${q.options.join(', ')}
      Correct Answer: ${q.options[q.correctAnswerIndex]}
      Student Selected: ${q.options[r.selectedOptionIndex]}
      Is Correct: ${r.isCorrect}
    `;
  }).join('\n---\n');

  const prompt = `
    Analyze the following student performance on a quiz for Florida Standard ${standard.code}: ${standard.description}.

    Detailed Performance:
    ${detailedAnalysis}

    Tasks:
    1. **Sub-skill Analysis**: Break down the standard into 2-4 distinct sub-skills or component skills relevant to these specific questions. For each sub-skill, determine how many questions related to it and how many were correct.
    2. **Misconception Detection**: For incorrect answers, analyze the specific distractor (wrong option) selected by the student. Does it indicate a common mathematical misconception (e.g., "adding denominators", "confusing perimeter with area", "place value alignment error")?
    3. **Gap Diagnosis**: Aggregate the errors into learning gaps.

    **Confidence Score Calculation**:
    Provide a confidence score (0-100) based on the consistency of the error pattern:
    - **High (85-100)**: The student makes the *same specific type of error* across multiple questions (e.g., always adds denominators).
    - **Medium (60-84)**: The student struggles with a general concept but errors vary slightly or there is only 1 error to analyze.
    - **Low (0-59)**: The errors appear random, suggesting guessing, or there is not enough data to form a strong conclusion.
  `;

  const subSkillSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      description: { type: Type.STRING },
      correctCount: { type: Type.INTEGER },
      totalCount: { type: Type.INTEGER }
    },
    required: ["name", "description", "correctCount", "totalCount"]
  };

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } },
      misconception: { type: Type.STRING, description: "The specific misconception identified from the wrong answer chosen." }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      subSkills: { type: Type.ARRAY, items: subSkillSchema },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "subSkills", "confidenceScore", "summary"]
  };

  return callWithRetry(async () => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema
        }
      });

      const text = response.text;
      if (!text) throw new Error("No response from AI");

      return JSON.parse(text) as GapAnalysis;
    } catch (error) {
      console.error("Gap Analysis Error:", error);
      throw error;
    }
  });
};

export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  const ai = getAiClient();

  const prompt = `
    You are an expert K-12 math intervention specialist. Create a 5-slide remedial lesson to fix specific student learning gaps for Florida Standard ${standard.code}.

    **STUDENT DIAGNOSIS:**
    ${analysis.identifiedGaps.map(g => `• GAP: ${g.description} (Misconception: ${g.misconception || 'General error'})`).join('\n')}

    **CONTENT GUIDELINES:**
    1.  **Clarity**: Use clear, concise explanations suitable for K-12 students.
    2.  **Terminology**: Use correct mathematical terminology (bolded).
    3.  **Formatting**: Use Markdown extensively (bullet points, bold text).
    4.  **Directness**: Address the identified gaps explicitly.

    **SLIDE STRUCTURE (Generate exactly 5 slides):**

    **Slide 1: Concept Definition**
    - **Goal**: Define the core concept and why it matters.
    - **Content**: Start with a strong definition. Use bold for key terms.

    **Slide 2: Visual Mental Model**
    - **Goal**: Connect the abstract math to a concrete visual.
    - **Content**: Explain *how* the visual proves the concept.

    **Slide 3: Step-by-Step Walkthrough**
    - **Goal**: Solve a problem relevant to the gap.
    - **Content**: Use a numbered list for steps:
      1.  **Step 1**: ...
      2.  **Step 2**: ...
      3.  **Step 3**: ...

    **Slide 4: Common Pitfalls**
    - **Goal**: Address the specific misconception diagnosed.
    - **Content**: Use a blockquote format:
      > **Common Mistake:** [Describe the specific error]
      > **Correction:** [Explain why it is wrong and how to fix it]

    **Slide 5: Summary & Strategy**
    - **Goal**: Provide a memory aid or checklist.
    - **Content**: A concise summary rule or "Remember this" checklist.

    **STRICT SVG VISUAL GENERATION RULES:**
    1.  **Aspect Ratio**: 16:9. Use ViewBox "0 0 800 450".
    2.  **Layout**: 
        - Leave 10% padding around edges.
        - **NO OVERLAPPING**: Ensure text labels do not overlap with lines or shapes.
        - Center main elements.
    3.  **Typography**:
        - Use sans-serif fonts.
        - Use \`text-anchor="middle"\` and \`dominant-baseline="middle"\` for centering text.
        - For text on top of lines, use \`paint-order="stroke" stroke="white" stroke-width="4"\` to create a halo effect.
        - Font size: 20px - 28px for legibility.
    4.  **Colors**:
        - Primary: Blue (#3b82f6)
        - Success: Emerald (#10b981)
        - Warning: Amber (#f59e0b)
        - Error: Red (#ef4444)
        - Text: Slate (#1e293b)
    5.  **Content**:
        - The visual MUST be an **exact representation** of the math described (e.g. if the text says 3/4, the pie chart must show exactly 3/4).
        - Use Number Lines, Tape Diagrams, Area Models, Coordinate Planes.
    6.  **Output**: Valid static SVG string.

    Return the response as a valid JSON object matching the requested schema.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING, description: "The teacher's explanation in Markdown. Keep concise." },
      visualDescription: { type: Type.STRING, description: "A 1-sentence caption connecting the image to the concept." },
      svgVisual: { type: Type.STRING, description: "Static SVG string. ViewBox 0 0 800 450." },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slides: { type: Type.ARRAY, items: slideSchema }
    }
  };

  return callWithRetry(async () => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema
        }
      });

      const text = response.text;
      if (!text) throw new Error("No response from AI");

      const data = JSON.parse(text);
      return data.slides as RemedialSlide[];
    } catch (error) {
      console.error("Slide Generation Error:", error);
      throw error;
    }
  });
};

import React, { useState } from 'react';
import { AppState, Standard, Quiz, QuizResult, GapAnalysis, RemedialSlide } from './types';
import { generateQuiz, analyzeGaps, generateRemedialSlides } from './services/geminiService';
import QuizGenerator from './components/QuizGenerator';
import QuizTaker from './components/QuizTaker';
import GapAnalysisComponent from './components/GapAnalysis';
import RemedialSlides from './components/RemedialSlides';
import { GraduationCap } from 'lucide-react';

function App() {
  const [state, setState] = useState<AppState>({
    view: 'setup',
    selectedStandard: null,
    quiz: null,
    quizResults: [],
    analysis: null,
    slides: [],
    loading: false,
    loadingMessage: '',
  });

  const handleApiError = (error: any) => {
    console.error("API Error:", error);
    let message = "An error occurred while communicating with the AI service.";

    const isQuotaError = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.toLowerCase().includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED';

    if (isQuotaError) {
      message = "⚠️ API Rate Limit Exceeded. The system is busy or you have hit your quota. Please wait a moment and try again.";
    }

    alert(message);
    setState(prev => ({ ...prev, loading: false }));
  };

  const handleGenerateQuiz = async (standard: Standard) => {
    setState(prev => ({ ...prev, loading: true, loadingMessage: 'Generating Quiz Questions...', selectedStandard: standard }));
    try {
      const quiz = await generateQuiz(standard);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        quiz, 
        view: 'quiz',
        quizResults: [] // reset results
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const handleQuizComplete = async (results: QuizResult[]) => {
    if (!state.quiz || !state.selectedStandard) return;

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Analyzing Performance & Identifying Gaps...', 
      quizResults: results 
    }));

    try {
      const analysis = await analyzeGaps(state.selectedStandard, state.quiz.questions, results);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        analysis, 
        view: 'analysis' 
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const handleStartRemediation = async () => {
    if (!state.analysis || !state.selectedStandard) return;

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Creating Personalized Learning Slides...' 
    }));

    try {
      const slides = await generateRemedialSlides(state.selectedStandard, state.analysis);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        slides, 
        view: 'remedial' 
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const restart = () => {
    setState({
      view: 'setup',
      selectedStandard: null,
      quiz: null,
      quizResults: [],
      analysis: null,
      slides: [],
      loading: false,
      loadingMessage: '',
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={restart}>
            <div className="bg-blue-600 p-2 rounded-lg">
              <GraduationCap className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-indigo-700">
              Florida B.E.S.T. Math Architect
            </h1>
          </div>
          {state.selectedStandard && (
            <div className="text-sm font-medium text-slate-500 bg-slate-100 px-3 py-1 rounded-full hidden sm:block">
              {state.selectedStandard.code}
            </div>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {state.loading ? (
          <div className="flex flex-col items-center justify-center h-[60vh] animate-fade-in">
            <div className="relative w-24 h-24 mb-8">
              <div className="absolute inset-0 border-4 border-slate-200 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">{state.loadingMessage}</h2>
            <p className="text-slate-500">Powered by Gemini AI</p>
          </div>
        ) : (
          <>
            {state.view === 'setup' && (
              <div className="animate-slide-up">
                <QuizGenerator onGenerate={handleGenerateQuiz} isLoading={state.loading} />
              </div>
            )}

            {state.view === 'quiz' && state.quiz && (
              <div className="animate-slide-up">
                <QuizTaker quiz={state.quiz} onComplete={handleQuizComplete} />
              </div>
            )}

            {state.view === 'analysis' && state.analysis && (
              <div className="animate-slide-up">
                <GapAnalysisComponent 
                  analysis={state.analysis} 
                  onStartRemediation={handleStartRemediation} 
                  isLoadingSlides={state.loading} 
                />
              </div>
            )}

            {state.view === 'remedial' && (
              <div className="animate-fade-in">
                <RemedialSlides slides={state.slides} onRestart={restart} />
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

