import React, { useState } from 'react';
import { AppState, Standard, Quiz, QuizResult, GapAnalysis, RemedialSlide, QuizConfig } from './types';
import { generateQuiz, analyzeGaps, generateRemedialSlides } from './services/geminiService';
import QuizGenerator from './components/QuizGenerator';
import QuizTaker from './components/QuizTaker';
import GapAnalysisComponent from './components/GapAnalysis';
import RemedialSlides from './components/RemedialSlides';
import { GraduationCap } from 'lucide-react';

function App() {
  const [state, setState] = useState<AppState>({
    view: 'setup',
    selectedStandard: null,
    quiz: null,
    quizResults: [],
    analysis: null,
    slides: [],
    loading: false,
    loadingMessage: '',
  });

  const handleApiError = (error: any) => {
    console.error("API Error:", error);
    let message = "An error occurred while communicating with the AI service.";

    const isQuotaError = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.toLowerCase().includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED';

    if (isQuotaError) {
      message = "⚠️ API Rate Limit Exceeded. The system is busy or you have hit your quota. Please wait a moment and try again.";
    }

    alert(message);
    setState(prev => ({ ...prev, loading: false }));
  };

  const handleGenerateQuiz = async (standard: Standard, config: QuizConfig) => {
    const modeLabel = config.mode === 'item-bank' ? 'Fetching Bank Items...' : 'Generating AI Questions...';

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: modeLabel, 
      selectedStandard: standard 
    }));

    try {
      const quiz = await generateQuiz(standard, config);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        quiz, 
        view: 'quiz',
        quizResults: [] // reset results
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const handleQuizComplete = async (results: QuizResult[]) => {
    if (!state.quiz || !state.selectedStandard) return;

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Analyzing Performance & Identifying Gaps...', 
      quizResults: results 
    }));

    try {
      const analysis = await analyzeGaps(state.selectedStandard, state.quiz.questions, results);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        analysis, 
        view: 'analysis' 
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const handleStartRemediation = async () => {
    if (!state.analysis || !state.selectedStandard) return;

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Creating Personalized Learning Slides...' 
    }));

    try {
      const slides = await generateRemedialSlides(state.selectedStandard, state.analysis);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        slides, 
        view: 'remedial' 
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const restart = () => {
    setState({
      view: 'setup',
      selectedStandard: null,
      quiz: null,
      quizResults: [],
      analysis: null,
      slides: [],
      loading: false,
      loadingMessage: '',
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={restart}>
            <div className="bg-blue-600 p-2 rounded-lg">
              <GraduationCap className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-indigo-700">
              Florida B.E.S.T. Math Architect
            </h1>
          </div>
          {state.selectedStandard && (
            <div className="text-sm font-medium text-slate-500 bg-slate-100 px-3 py-1 rounded-full hidden sm:block">
              {state.selectedStandard.code}
            </div>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {state.loading ? (
          <div className="flex flex-col items-center justify-center h-[60vh] animate-fade-in">
            <div className="relative w-24 h-24 mb-8">
              <div className="absolute inset-0 border-4 border-slate-200 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">{state.loadingMessage}</h2>
            <p className="text-slate-500">Powered by Gemini AI</p>
          </div>
        ) : (
          <>
            {state.view === 'setup' && (
              <div className="animate-slide-up">
                <QuizGenerator onGenerate={handleGenerateQuiz} isLoading={state.loading} />
              </div>
            )}

            {state.view === 'quiz' && state.quiz && (
              <div className="animate-slide-up">
                <QuizTaker quiz={state.quiz} onComplete={handleQuizComplete} />
              </div>
            )}

            {state.view === 'analysis' && state.analysis && (
              <div className="animate-slide-up">
                <GapAnalysisComponent 
                  analysis={state.analysis} 
                  onStartRemediation={handleStartRemediation} 
                  isLoadingSlides={state.loading} 
                />
              </div>
            )}

            {state.view === 'remedial' && (
              <div className="animate-fade-in">
                <RemedialSlides slides={state.slides} onRestart={restart} />
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

export enum GradeLevel {
  K = 'Kindergarten',
  G1 = 'Grade 1',
  G2 = 'Grade 2',
  G3 = 'Grade 3',
  G4 = 'Grade 4',
  G5 = 'Grade 5',
  G6 = 'Grade 6',
  G7 = 'Grade 7',
  G8 = 'Grade 8'
}

export interface Standard {
  code: string;
  description: string;
  grade: GradeLevel;
  clarifications?: string[];
  examples?: string[];
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
  animationDescription: string; // Description for a potential animation
  visual?: string; // SVG code for questions that require an image
}

export interface Quiz {
  standardCode: string;
  questions: Question[];
}

export interface QuizResult {
  questionIndex: number;
  selectedOptionIndex: number;
  isCorrect: boolean;
  timeTaken: number; // seconds
}

export enum GapType {
  Conceptual = 'Conceptual Understanding',
  Procedural = 'Procedural Fluency',
  Computational = 'Computational Error',
  Unknown = 'Needs More Data'
}

export interface SubSkill {
  name: string;
  description: string;
  correctCount: number;
  totalCount: number;
}

export interface GapAnalysis {
  standardCode: string;
  identifiedGaps: {
    gapType: GapType;
    description: string;
    relatedQuestions: number[]; // Indices
    misconception?: string; // Specific detected misconception
  }[];
  subSkills: SubSkill[];
  confidenceScore: number; // 0-100
  summary: string;
}

export interface RemedialSlide {
  slideNumber: number;
  title: string;
  content: string; // Markdown supported
  visualDescription: string;
  svgVisual?: string; // New field for SVG code
  vocabulary: string[];
}

export type QuizMode = 'item-bank' | 'topic-based';
export type Difficulty = 'Easy' | 'Medium' | 'Hard' | 'Mixed';

export interface QuizConfig {
  questionCount: number;
  difficulty: Difficulty;
  mode: QuizMode;
  questionTypes: {
    multipleChoice: boolean;
    trueFalse: boolean;
    fillInBlank: boolean;
  };
  focusAreas: {
    wordProblems: boolean;
    visualQuestions: boolean;
    realWorld: boolean;
  };
}

export interface AppState {
  view: 'setup' | 'quiz' | 'analysis' | 'remedial';
  selectedStandard: Standard | null;
  quiz: Quiz | null;
  quizResults: QuizResult[];
  analysis: GapAnalysis | null;
  slides: RemedialSlide[];
  loading: boolean;
  loadingMessage: string;
}

