import React, { useState } from 'react';
import { TopicNode } from '../types';
import { ChevronRight, ChevronDown, BookOpen, Folder, Hash, TreeDeciduous } from 'lucide-react';

interface Props {
  data: TopicNode[];
  onSelect: (node: TopicNode, breadcrumbs: string[]) => void;
  selectedNodeId: string | null;
  isOpen: boolean;
  onToggle: () => void;
}

const TopicSidebar: React.FC<Props> = ({ data, onSelect, selectedNodeId, isOpen, onToggle }) => {
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());

  const toggleExpand = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const newExpanded = new Set(expandedNodes);
    if (newExpanded.has(id)) {
      newExpanded.delete(id);
    } else {
      newExpanded.add(id);
    }
    setExpandedNodes(newExpanded);
  };

  const handleNodeClick = (node: TopicNode, parentPath: string[]) => {
    // If it has children, just toggle expansion
    if (node.children && node.children.length > 0) {
       const newExpanded = new Set(expandedNodes);
       if (newExpanded.has(node.id)) {
         newExpanded.delete(node.id);
       } else {
         newExpanded.add(node.id);
       }
       setExpandedNodes(newExpanded);
    } 

    // Always select the node to update the view context
    onSelect(node, [...parentPath, node.title]);
  };

  const renderNode = (node: TopicNode, depth: number = 0, parentPath: string[]) => {
    const isExpanded = expandedNodes.has(node.id);
    const isSelected = selectedNodeId === node.id;
    const hasChildren = node.children && node.children.length > 0;

    return (
      <div key={node.id} className="select-none">
        <div 
          onClick={() => handleNodeClick(node, parentPath)}
          className={`
            flex items-center gap-2 px-4 py-2 cursor-pointer transition-colors duration-200
            ${isSelected ? 'bg-blue-600 text-white' : 'hover:bg-slate-100 text-slate-700'}
            ${depth === 0 ? 'font-semibold border-b border-slate-100' : 'text-sm'}
          `}
          style={{ paddingLeft: `${depth * 16 + 16}px` }}
        >
          {/* Icon based on Type */}
          {node.type === 'grade' && <BookOpen className={`w-4 h-4 ${isSelected ? 'text-white' : 'text-blue-500'}`} />}
          {node.type === 'strand' && <Folder className={`w-4 h-4 ${isSelected ? 'text-white' : 'text-amber-500'}`} />}
          {node.type === 'topic' && <Hash className={`w-3 h-3 ${isSelected ? 'text-white' : 'text-slate-400'}`} />}

          <span className="flex-1 truncate">{node.title}</span>

          {hasChildren && (
            <div onClick={(e) => toggleExpand(e, node.id)} className="p-1 hover:bg-black/10 rounded">
               {isExpanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
            </div>
          )}
        </div>

        {/* Children */}
        {hasChildren && isExpanded && (
          <div className="animate-slide-down">
            {node.children!.map(child => renderNode(child, depth + 1, [...parentPath, node.title]))}
          </div>
        )}
      </div>
    );
  };

  return (
    <>
      {/* Mobile Overlay */}
      <div 
         className={`fixed inset-0 bg-black/30 z-30 transition-opacity lg:hidden ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
         onClick={onToggle}
      />

      {/* Sidebar Panel */}
      <div className={`
        fixed top-16 left-0 bottom-0 z-40 bg-white border-r border-slate-200 shadow-xl lg:shadow-none lg:static
        transition-all duration-300 ease-in-out flex flex-col
        ${isOpen ? 'w-[300px] translate-x-0' : 'w-[300px] -translate-x-full lg:translate-x-0 lg:w-0 lg:overflow-hidden lg:opacity-0'}
      `}>

         {/* Header */}
         <div className="p-4 border-b border-slate-200 bg-slate-50 flex items-center gap-3">
            <div className="bg-emerald-100 p-2 rounded-lg text-emerald-600">
               <TreeDeciduous className="w-5 h-5" />
            </div>
            <div>
               <h2 className="font-bold text-slate-800 text-sm">Topic Explorer</h2>
               <p className="text-xs text-slate-500">Browse curriculum</p>
            </div>
         </div>

         {/* Tree Content */}
         <div className="flex-1 overflow-y-auto py-2 custom-scrollbar">
            {data.map(node => renderNode(node, 0, []))}
         </div>

      </div>
    </>
  );
};

export default TopicSidebar;

import React, { useState, useEffect } from 'react';
import { GradeLevel, Standard, QuizMode, Difficulty, QuizConfig, TopicNode } from '../types';
import { FLORIDA_STANDARDS, TOPIC_TREE } from '../constants';
import { BookOpen, Sparkles, ChevronDown, Database, Info, Layers, Check, Settings2, Menu, Filter, ArrowRight } from 'lucide-react';
import TopicSidebar from './TopicSidebar';

interface Props {
  onGenerate: (standard: Standard, config: QuizConfig) => void;
  isLoading: boolean;
}

const QuizGenerator: React.FC<Props> = ({ onGenerate, isLoading }) => {
  // Modes
  const [quizMode, setQuizMode] = useState<QuizMode>('item-bank');

  // Standard Mode State
  const [selectedGrade, setSelectedGrade] = useState<GradeLevel | ''>('');
  const [selectedStandardCode, setSelectedStandardCode] = useState<string>('');

  // Topic Mode State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [selectedTopic, setSelectedTopic] = useState<TopicNode | null>(null);
  const [breadcrumbs, setBreadcrumbs] = useState<string[]>([]);

  // Configuration State
  const [questionCount, setQuestionCount] = useState<number>(5);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');

  // Advanced Config State
  const [config, setConfig] = useState({
    questionTypes: {
      multipleChoice: true,
      trueFalse: false,
      fillInBlank: false
    },
    focusAreas: {
      wordProblems: true,
      visualQuestions: true,
      realWorld: false
    }
  });

  // Derived
  const filteredStandards = FLORIDA_STANDARDS.filter(s => s.grade === selectedGrade);
  const selectedStandard = FLORIDA_STANDARDS.find(s => s.code === selectedStandardCode);

  // Handlers
  const handleTopicSelect = (node: TopicNode, path: string[]) => {
     setSelectedTopic(node);
     setBreadcrumbs(path);
  };

  const handleGenerate = () => {
    if (quizMode === 'item-bank' && selectedStandard) {
      onGenerate(selectedStandard, {
        questionCount,
        difficulty,
        mode: quizMode,
        questionTypes: config.questionTypes,
        focusAreas: config.focusAreas
      });
    } else if (quizMode === 'topic-based' && selectedTopic) {
      // Find a standard to map to (or create a dummy one if no direct mapping exists)
      const standardCode = selectedTopic.associatedStandards?.[0] || 'MA.TOPIC.AI';
      const mappedStandard: Standard = FLORIDA_STANDARDS.find(s => s.code === standardCode) || {
        code: standardCode,
        grade: GradeLevel.G4, // Default fallbacks
        description: `Topic Assessment: ${selectedTopic.title}`,
        clarifications: [`Focus on concepts related to ${breadcrumbs.join(' > ')}`]
      };

      onGenerate(mappedStandard, {
        questionCount,
        difficulty,
        mode: quizMode,
        questionTypes: config.questionTypes,
        focusAreas: config.focusAreas
      });
    }
  };

  // Ensure Sidebar opens on desktop when mode switches
  useEffect(() => {
    if (quizMode === 'topic-based') {
       setIsSidebarOpen(true);
    }
  }, [quizMode]);

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-slate-50 relative -mx-4 sm:-mx-6 lg:-mx-8 -my-8">

      {/* Sidebar (Only visible in Topic Mode) */}
      {quizMode === 'topic-based' && (
        <TopicSidebar 
          data={TOPIC_TREE} 
          isOpen={isSidebarOpen} 
          onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
          selectedNodeId={selectedTopic?.id || null}
          onSelect={handleTopicSelect}
        />
      )}

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col h-full overflow-y-auto">
        <div className="max-w-5xl mx-auto w-full p-6 lg:p-10 space-y-8">

          {/* Header & Mode Switcher */}
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-slate-200 pb-6">
             <div>
                <h1 className="text-3xl font-bold text-slate-900">New Assessment</h1>
                <p className="text-slate-500 mt-1">Configure parameters to generate your quiz</p>
             </div>

             {/* Mode Toggle Pills */}
             <div className="bg-white p-1 rounded-xl border border-slate-200 flex shadow-sm">
                <button
                  onClick={() => setQuizMode('item-bank')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                    quizMode === 'item-bank' 
                      ? 'bg-emerald-100 text-emerald-700 shadow-sm' 
                      : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <Database className="w-4 h-4" />
                  Item Bank
                </button>
                <button
                  onClick={() => setQuizMode('topic-based')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                    quizMode === 'topic-based' 
                      ? 'bg-blue-100 text-blue-700 shadow-sm' 
                      : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <Sparkles className="w-4 h-4" />
                  Topic AI
                </button>
             </div>
          </div>

          {/* Mobile Sidebar Toggle */}
          {quizMode === 'topic-based' && (
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="lg:hidden flex items-center gap-2 text-blue-600 font-bold bg-blue-50 px-4 py-2 rounded-lg w-fit"
            >
               <Menu className="w-4 h-4" />
               Browse Topics
            </button>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

             {/* Left Col: Context Selection */}
             <div className="lg:col-span-7 space-y-6">

                {/* Standard Mode Selection UI */}
                {quizMode === 'item-bank' && (
                  <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 space-y-6 animate-fade-in">
                      <div className="flex items-center gap-2 mb-2">
                         <span className="w-8 h-8 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-sm">1</span>
                         <h3 className="font-bold text-lg text-slate-800">Select Standard</h3>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-semibold text-slate-700 mb-2">Grade</label>
                          <select 
                            className="w-full p-3 rounded-xl border border-slate-200 bg-slate-50 font-medium"
                            value={selectedGrade}
                            onChange={(e) => {
                              setSelectedGrade(e.target.value as GradeLevel);
                              setSelectedStandardCode('');
                            }}
                          >
                            <option value="">Select...</option>
                            {Object.values(GradeLevel).map(g => <option key={g} value={g}>{g}</option>)}
                          </select>
                        </div>
                        <div>
                           <label className="block text-sm font-semibold text-slate-700 mb-2">Standard</label>
                           <select 
                            className="w-full p-3 rounded-xl border border-slate-200 bg-slate-50 font-medium disabled:opacity-50"
                            value={selectedStandardCode}
                            onChange={(e) => setSelectedStandardCode(e.target.value)}
                            disabled={!selectedGrade}
                          >
                            <option value="">Select...</option>
                            {filteredStandards.map(s => <option key={s.code} value={s.code}>{s.code}</option>)}
                          </select>
                        </div>
                      </div>

                      {selectedStandard && (
                        <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100">
                           <h4 className="font-bold text-emerald-900 mb-1">{selectedStandard.code}</h4>
                           <p className="text-sm text-emerald-800">{selectedStandard.description}</p>
                        </div>
                      )}
