                                <span className={`font-bold ${isAdaptive ? 'text-purple-900' : 'text-slate-500'}`}>Adaptive Difficulty</span>
                             </div>
                             <p className="text-xs text-slate-500 leading-relaxed">
                                AI adjusts question difficulty in real-time based on your performance. Start at <strong>{difficulty}</strong>.
                             </p>
                          </div>
                        </label>
                     </div>
                   )}

                   {/* Advanced Filters (Topic Mode Only) */}
                   {quizMode === 'topic-based' && (
                     <>
                        <div className="h-px bg-slate-100" />
                        <div>
                           <label className="block text-sm font-bold text-slate-700 mb-3 flex items-center gap-2">
                              <Filter className="w-4 h-4" /> Focus Areas
                           </label>
                           <div className="flex flex-wrap gap-2">
                              {Object.entries(config.focusAreas).map(([key, val]) => (
                                 <button
                                    key={key}
                                    onClick={() => setConfig({...config, focusAreas: {...config.focusAreas, [key]: !val} as any})}
                                    className={`px-3 py-1.5 rounded-full text-xs font-bold border transition-all ${
                                       val 
                                       ? 'bg-blue-100 text-blue-700 border-blue-200' 
                                       : 'bg-slate-50 text-slate-500 border-slate-200'
                                    }`}
                                 >
                                    {key.replace(/([A-Z])/g, ' $1').trim()}
                                 </button>
                              ))}
                           </div>
                        </div>
                     </>
                   )}

                   <button
                      onClick={handleGenerate}
                      disabled={isLoading}
                      className="w-full bg-slate-900 text-white font-bold py-4 rounded-xl shadow-lg hover:bg-slate-800 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center gap-3 mt-4"
                    >
                      {isLoading ? (
                        <>
                          <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                          <span>Generating...</span>
                        </>
                      ) : (
                        <>
                          <Settings2 className="w-5 h-5" />
                          <span>Generate Assessment</span>
                        </>
                      )}
                    </button>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QuizGenerator;

import React, { useState, useEffect } from 'react';
import { Quiz, QuizResult, Question, Difficulty } from '../types';
import { generateAdaptiveQuestion } from '../services/geminiService';
import { FLORIDA_STANDARDS } from '../constants'; // Needed to re-fetch standard details
import { CheckCircle, XCircle, ArrowRight, Clock, Image as ImageIcon, Loader2, Gauge } from 'lucide-react';

interface Props {
  quiz: Quiz;
  onComplete: (results: QuizResult[]) => void;
}

const QuizTaker: React.FC<Props> = ({ quiz, onComplete }) => {
  // --- State Management ---
  const [questions, setQuestions] = useState<Question[]>(quiz.questions);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [results, setResults] = useState<QuizResult[]>([]);
  const [startTime, setStartTime] = useState(Date.now());
  const [showFeedback, setShowFeedback] = useState(false);

  // Adaptive State
  const [currentDifficulty, setCurrentDifficulty] = useState<Difficulty>(quiz.config.difficulty);
  const [consecutiveCorrect, setConsecutiveCorrect] = useState(0);
  const [consecutiveWrong, setConsecutiveWrong] = useState(0);
  const [isFetchingNext, setIsFetchingNext] = useState(false);

  // Standard lookup for API calls
  const standard = FLORIDA_STANDARDS.find(s => s.code === quiz.standardCode) || { 
    code: quiz.standardCode, grade: 'Grade 4' as any, description: 'Generated Topic' 
  };

  useEffect(() => {
    setStartTime(Date.now());
  }, [currentQuestionIdx]);

  // --- Logic ---

  const handleSelect = (idx: number) => {
    if (showFeedback) return;
    setSelectedOption(idx);
  };

  const getNextDifficulty = (current: Difficulty, isCorrect: boolean): Difficulty => {
    // Logic: 2 Correct -> Level Up. 2 Wrong -> Level Down.
    // Levels: Easy (1) -> Medium (2) -> Hard (3)

    // Calculate hypothetical new counters
    const nextConsecutiveCorrect = isCorrect ? consecutiveCorrect + 1 : 0;
    const nextConsecutiveWrong = isCorrect ? 0 : consecutiveWrong + 1;

    let nextDiff = current;

    if (nextConsecutiveCorrect >= 2) {
      if (current === 'Easy') nextDiff = 'Medium';
      else if (current === 'Medium') nextDiff = 'Hard';
      // If Hard, stay Hard
    } else if (nextConsecutiveWrong >= 2) {
      if (current === 'Hard') nextDiff = 'Medium';
      else if (current === 'Medium') nextDiff = 'Easy';
      // If Easy, stay Easy
    }

    return nextDiff;
  };

  const handleSubmitAnswer = () => {
    if (selectedOption === null) return;

    const question = questions[currentQuestionIdx];
    const timeTaken = (Date.now() - startTime) / 1000;
    const isCorrect = selectedOption === question.correctAnswerIndex;

    const result: QuizResult = {
      questionIndex: currentQuestionIdx,
      selectedOptionIndex: selectedOption,
      isCorrect,
      timeTaken,
      difficulty: question.difficulty
    };

    // Update Counters
    if (isCorrect) {
      setConsecutiveCorrect(prev => prev + 1);
      setConsecutiveWrong(0);
    } else {
      setConsecutiveCorrect(0);
      setConsecutiveWrong(prev => prev + 1);
    }

    // Determine next difficulty immediately so we can fetch while user reads feedback
    // Only if adaptive AND not the last question
    if (quiz.config.isAdaptive && results.length + 1 < quiz.config.questionCount) {
       const nextDiff = getNextDifficulty(currentDifficulty, isCorrect);
       setCurrentDifficulty(nextDiff); // Update state for next question

       // OPTIMIZATION: Trigger fetch for next question in background?
       // For this implementation, we will trigger it on "Next" click to avoid race conditions with UI state
    }

    const newResults = [...results, result];
    setResults(newResults);
    setShowFeedback(true);
  };

  const handleNext = async () => {
    const isLastQuestion = results.length >= quiz.config.questionCount;

    if (isLastQuestion) {
      onComplete(results);
      return;
    }

    // If we have the next question already (e.g. batch mode), just advance
    if (currentQuestionIdx < questions.length - 1) {
      setCurrentQuestionIdx(curr => curr + 1);
      setSelectedOption(null);
      setShowFeedback(false);
      return;
    }

    // ADAPTIVE MODE: Need to fetch next question
    if (quiz.config.isAdaptive) {
      setIsFetchingNext(true);
      try {
        const newQuestion = await generateAdaptiveQuestion(standard, currentDifficulty, results);

        // Ensure new question has the calculated difficulty
        newQuestion.difficulty = currentDifficulty;

        setQuestions(prev => [...prev, newQuestion]);
        setCurrentQuestionIdx(curr => curr + 1);
        setSelectedOption(null);
        setShowFeedback(false);
      } catch (e) {
        console.error("Failed to fetch next adaptive question", e);
        alert("Connection lost. Trying to recover...");
      } finally {
        setIsFetchingNext(false);
      }
    }
  };

  // --- Rendering ---

  const processSVG = (svgString: string | undefined) => {
    if (!svgString) return null;
    let processed = svgString;
    if (!processed.includes('preserveAspectRatio')) {
      processed = processed.replace('<svg', '<svg preserveAspectRatio="xMidYMid meet"');
    }
    processed = processed.replace(/width="[^"]*"/, 'width="100%"').replace(/height="[^"]*"/, 'height="100%"');
    return processed;
  };

  const question = questions[currentQuestionIdx];
  const progress = ((currentQuestionIdx) / quiz.config.questionCount) * 100;

  // Get Difficulty Color
  const getDiffColor = (d: Difficulty) => {
    switch(d) {
      case 'Easy': return 'text-green-600 bg-green-50 border-green-200';
      case 'Medium': return 'text-amber-600 bg-amber-50 border-amber-200';
      case 'Hard': return 'text-red-600 bg-red-50 border-red-200';
      default: return 'text-slate-600 bg-slate-50 border-slate-200';
    }
  };

  return (
    <div className="max-w-3xl mx-auto">
      {/* Progress Bar */}
      <div className="w-full bg-slate-200 h-2 rounded-full mb-8 overflow-hidden">
        <div 
          className="bg-blue-600 h-2 rounded-full transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>

      <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden min-h-[500px] flex flex-col">
        {/* Header */}
        <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <span className="text-sm font-semibold text-slate-500 uppercase tracking-wide">
            Question {currentQuestionIdx + 1} of {quiz.config.questionCount}
          </span>
          <div className="flex items-center gap-3">
             {quiz.config.isAdaptive && (
               <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full border text-xs font-bold uppercase tracking-wider ${getDiffColor(question.difficulty)}`}>
                  <Gauge className="w-3.5 h-3.5" />
                  {question.difficulty}
               </div>
             )}
             <span className="text-sm font-medium text-slate-400 flex items-center gap-1">
              <Clock className="w-4 h-4" />
              Standard: {quiz.standardCode}
            </span>
          </div>
        </div>

        {/* Content */}
        <div className="p-8 flex-1">
          <h3 className="text-xl font-bold text-slate-900 mb-6 leading-relaxed">
            {question.text}
          </h3>

          {/* Question Visual */}
          {question.visual && (
            <div className="mb-8 p-4 bg-slate-50 rounded-xl border border-slate-200 flex flex-col items-center">
               <div className="flex items-center gap-2 mb-2 text-slate-400 text-xs font-bold uppercase tracking-wider">
                  <ImageIcon className="w-4 h-4" />
                  <span>Visual Aid</span>
               </div>
               <div
                  className="w-full max-w-lg aspect-[400/250] bg-white rounded-lg shadow-sm overflow-hidden"
                  dangerouslySetInnerHTML={{ __html: processSVG(question.visual) || '' }}
               />
            </div>
          )}

          <div className="space-y-4">
            {question.options.map((option, idx) => {
              let btnClass = "w-full p-4 rounded-xl border-2 text-left transition-all relative flex items-center justify-between ";

              if (showFeedback) {
                if (idx === question.correctAnswerIndex) {
                  btnClass += "border-green-500 bg-green-50 text-green-800";
                } else if (idx === selectedOption && idx !== question.correctAnswerIndex) {
                  btnClass += "border-red-500 bg-red-50 text-red-800";
                } else {
                  btnClass += "border-slate-100 text-slate-400 opacity-50";
                }
              } else {
                if (selectedOption === idx) {
                  btnClass += "border-blue-600 bg-blue-50 text-blue-900 shadow-md ring-2 ring-blue-100";
                } else {
                  btnClass += "border-slate-200 hover:border-blue-300 hover:bg-slate-50 text-slate-700";
                }
              }

              return (
                <button
                  key={idx}
                  onClick={() => handleSelect(idx)}
                  className={btnClass}
                  disabled={showFeedback}
                >
                  <span className="font-medium text-lg">{String.fromCharCode(65 + idx)}. {option}</span>
                  {showFeedback && idx === question.correctAnswerIndex && (
                    <CheckCircle className="w-6 h-6 text-green-600" />
                  )}
                  {showFeedback && idx === selectedOption && idx !== question.correctAnswerIndex && (
                    <XCircle className="w-6 h-6 text-red-600" />
                  )}
                </button>
              );
            })}
          </div>

          {showFeedback && (
            <div className="mt-8 animate-fade-in">
              <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-100">
                <h4 className="font-semibold text-indigo-900 mb-2 flex items-center gap-2">
                  Explanation
                </h4>
                <p className="text-indigo-800 leading-relaxed mb-4">{question.explanation}</p>

                <div className="bg-white p-4 rounded-lg border border-indigo-100">
                  <span className="text-xs font-bold text-indigo-400 uppercase tracking-wider mb-1 block">Visual Concept</span>
                  <p className="text-sm text-slate-600 italic">
                    "{question.animationDescription}"
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-8 py-6 bg-slate-50 border-t border-slate-100 flex justify-end">
          {!showFeedback ? (
            <button
              onClick={handleSubmitAnswer}
              disabled={selectedOption === null}
              className="bg-blue-600 text-white px-8 py-3 rounded-xl font-semibold shadow-lg hover:bg-blue-700 disabled:opacity-50 disabled:shadow-none transition-all"
            >
              Check Answer
            </button>
          ) : (
            <button
              onClick={handleNext}
              disabled={isFetchingNext}
              className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-semibold shadow-lg hover:bg-indigo-700 flex items-center gap-2 transition-all disabled:opacity-70"
            >
              {isFetchingNext ? (
                 <>
                   <Loader2 className="w-5 h-5 animate-spin" />
                   Thinking...
                 </>
              ) : (
                 <>
                   {results.length >= quiz.config.questionCount ? "Finish Quiz" : "Next Question"}
                   <ArrowRight className="w-5 h-5" />
                 </>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default QuizTaker;

import React from 'react';
import { GapAnalysis as GapAnalysisType, GapType, Difficulty } from '../types';
import { AlertTriangle, Brain, Calculator, Wrench, BarChart2, BookOpen, Target, AlertCircle, Info, CheckCircle2, TrendingUp, TrendingDown, Minus } from 'lucide-react';

interface Props {
  analysis: GapAnalysisType;
  onStartRemediation: () => void;
  isLoadingSlides: boolean;
}

const GapAnalysis: React.FC<Props> = ({ analysis, onStartRemediation, isLoadingSlides }) => {
  const getIcon = (type: GapType) => {
    switch (type) {
      case GapType.Conceptual: return <Brain className="w-6 h-6 text-purple-600" />;
      case GapType.Procedural: return <Wrench className="w-6 h-6 text-orange-600" />;
      case GapType.Computational: return <Calculator className="w-6 h-6 text-red-600" />;
      default: return <AlertTriangle className="w-6 h-6 text-slate-600" />;
    }
  };

  const getColor = (type: GapType) => {
    switch (type) {
      case GapType.Conceptual: return "bg-purple-50 border-purple-100 text-purple-900";
      case GapType.Procedural: return "bg-orange-50 border-orange-100 text-orange-900";
      case GapType.Computational: return "bg-red-50 border-red-100 text-red-900";
      default: return "bg-slate-50 border-slate-100 text-slate-900";
    }
  };

  const getScoreColor = (correct: number, total: number) => {
    const percentage = correct / total;
    if (percentage >= 0.8) return 'text-green-600';
    if (percentage >= 0.5) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getProgressBarColor = (correct: number, total: number) => {
    const percentage = correct / total;
    if (percentage >= 0.8) return 'bg-green-500';
    if (percentage >= 0.5) return 'bg-yellow-500';
    return 'bg-red-500';
  };

  // Determine confidence level properties
  const getConfidenceLevel = (score: number) => {
    if (score >= 85) return { 
      label: "High Reliability", 
      color: "text-emerald-600", 
      bg: "bg-emerald-50",
      icon: <CheckCircle2 className="w-4 h-4 text-emerald-600" />,
      description: "Consistent error patterns detected. The AI is highly certain about the diagnosed gaps." 
    };
    if (score >= 60) return { 
      label: "Medium Reliability", 
      color: "text-amber-600", 
      bg: "bg-amber-50",
      icon: <Info className="w-4 h-4 text-amber-600" />,
      description: "Some patterns identified, but errors varied. Remediation is recommended to clarify understanding." 
    };
    return { 
      label: "Low Reliability", 
      color: "text-slate-500", 
      bg: "bg-slate-50",
      icon: <AlertTriangle className="w-4 h-4 text-slate-500" />,
      description: "Errors appear random or due to guessing. The specific gap diagnosis requires more data." 
    };
  };

  const confidence = getConfidenceLevel(analysis.confidenceScore);
  const radius = 36;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (analysis.confidenceScore / 100) * circumference;

  // Render Difficulty Trajectory if available
  const renderTrajectory = () => {
    if (!analysis.difficultyTrend || analysis.difficultyTrend.length === 0) return null;

    const diffMap = { 'Easy': 1, 'Medium': 2, 'Hard': 3 };
    const maxVal = 3;

    return (
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-6 flex items-center gap-2">
          <TrendingUp className="w-5 h-5 text-blue-500" />
          Adaptive Difficulty Progression
        </h3>

        <div className="relative h-32 flex items-end justify-between px-4">
          {/* Y-Axis Lines */}
          <div className="absolute inset-0 flex flex-col justify-between pointer-events-none pb-6 text-xs text-slate-300 font-bold uppercase">
             <div className="border-b border-slate-100 w-full h-8 flex items-center">Hard</div>
             <div className="border-b border-slate-100 w-full h-8 flex items-center">Medium</div>
             <div className="border-b border-slate-100 w-full h-8 flex items-center">Easy</div>
          </div>

          {/* Points */}
          {analysis.difficultyTrend.map((d, i) => {
             // Calculate height percentage (Easy=33%, Medium=66%, Hard=100%)
             // Actually, map 1->10%, 2->50%, 3->90% for visual centering
             const val = diffMap[d as keyof typeof diffMap] || 2;
             const heightPct = val === 1 ? '15%' : val === 2 ? '50%' : '85%';

             // Check if trend went up or down from previous
             const prevVal = i > 0 ? diffMap[analysis.difficultyTrend![i-1] as keyof typeof diffMap] : val;
             const colorClass = val > prevVal ? 'bg-green-500' : val < prevVal ? 'bg-red-500' : 'bg-blue-500';

             return (
               <div key={i} className="flex flex-col items-center gap-2 z-10 relative group w-full">
                  <div 
                    className={`w-4 h-4 rounded-full border-2 border-white shadow-md transition-all ${colorClass}`}
                    style={{ position: 'absolute', bottom: heightPct }}
                  >
                    {/* Tooltip */}
                    <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 bg-slate-800 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
                       Q{i+1}: {d}
                    </div>
                  </div>
                  {/* Connecting Line (simulated) - ideally use SVG but this is a quick CSS hack */}
                  {i < analysis.difficultyTrend!.length - 1 && (
                     // This is hard to do purely with divs in a flex container without SVG
                     // So we keep it as discrete points for now
                     <span className="sr-only">Connect</span>
                  )}
                  <span className="absolute bottom-[-24px] text-xs text-slate-400 font-mono">Q{i+1}</span>
               </div>
             );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="max-w-5xl mx-auto space-y-8 animate-fade-in">
      <div className="text-center">
        <h2 className="text-3xl font-bold text-slate-900 mb-2">Learning Gap Analysis</h2>
        <p className="text-slate-500">AI-Diagnosis based on your quiz performance for standard {analysis.standardCode}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* Expanded Confidence Score Card */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col items-center justify-center text-center relative overflow-hidden group">
          <div className="absolute top-0 w-full h-1 bg-gradient-to-r from-slate-200 via-blue-500 to-slate-200 opacity-50"></div>

          <div className="relative w-28 h-28 mb-4 group-hover:scale-105 transition-transform duration-300">
            <svg className="w-full h-full transform -rotate-90">
              <circle cx="56" cy="56" r={radius} stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-100" />
              <circle cx="56" cy="56" r={radius} stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={circumference} strokeDashoffset={offset} strokeLinecap="round" className="text-blue-600 transition-all duration-1000 ease-out" />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-2xl font-bold text-slate-900">{analysis.confidenceScore}%</span>
              <span className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">Reliability</span>
            </div>
          </div>

          <div className={`flex items-center gap-2 mb-3 px-3 py-1 rounded-full ${confidence.bg}`}>
            {confidence.icon}
            <h3 className={`text-sm font-bold uppercase tracking-wider ${confidence.color}`}>
              {confidence.label}
            </h3>
          </div>
        </div>

        <div className="md:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
            <BarChart2 className="w-5 h-5 text-blue-500" />
            Performance Summary
          </h3>
          <p className="text-slate-600 leading-relaxed text-lg">{analysis.summary}</p>
        </div>
      </div>

      {/* Trajectory Chart (If Adaptive) */}
      {renderTrajectory()}

      {/* Sub-skills Section */}
      {analysis.subSkills && analysis.subSkills.length > 0 && (
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-6 flex items-center gap-2">
            <Target className="w-5 h-5 text-indigo-500" />
            Skill Breakdown
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {analysis.subSkills.map((skill, idx) => (
              <div key={idx} className="bg-slate-50 p-5 rounded-xl border border-slate-100 hover:border-blue-200 transition-colors">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <h4 className="font-bold text-slate-700">{skill.name}</h4>
                    <p className="text-xs text-slate-500 mt-1">{skill.description}</p>
                  </div>
                  <span className={`text-lg font-bold ${getScoreColor(skill.correctCount, skill.totalCount)}`}>
                    {skill.correctCount}/{skill.totalCount}
                  </span>
                </div>
                {/* Progress bar */}
                <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-full rounded-full ${getProgressBarColor(skill.correctCount, skill.totalCount)} transition-all duration-1000`}
                    style={{ width: `${(skill.correctCount / skill.totalCount) * 100}%` }}
                  ></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="space-y-4">
        <h3 className="text-xl font-bold text-slate-900 flex items-center gap-2">
          <AlertCircle className="w-5 h-5 text-red-500" />
          Diagnosed Learning Gaps
        </h3>

        {analysis.identifiedGaps.length === 0 ? (
          <div className="p-8 bg-green-50 rounded-2xl border border-green-100 text-center">
            <p className="text-green-800 font-medium text-lg">No significant gaps identified! Great job mastering this standard.</p>
          </div>
        ) : (
          <div className="grid gap-4">
            {analysis.identifiedGaps.map((gap, idx) => (
              <div key={idx} className={`p-6 rounded-2xl border flex flex-col md:flex-row gap-4 ${getColor(gap.gapType)}`}>
                <div className="flex-shrink-0 mt-1">
                   <div className="bg-white/80 p-3 rounded-full h-fit shadow-sm backdrop-blur-sm">
                    {getIcon(gap.gapType)}
                  </div>
                </div>
                <div className="flex-1">
                  <div className="flex flex-wrap items-center gap-2 mb-2">
                    <h4 className="font-bold text-lg">{gap.gapType}</h4>
                    {gap.relatedQuestions.map(qIdx => (
                      <span key={qIdx} className="px-2 py-0.5 bg-white/60 rounded text-xs font-bold uppercase tracking-wide border border-black/5">
                        Q{qIdx + 1}
                      </span>
                    ))}
                  </div>
                  <p className="opacity-90 mb-4 leading-relaxed">{gap.description}</p>

                  {gap.misconception && (
                    <div className="bg-white/60 p-4 rounded-xl border border-black/5">
                      <span className="text-xs font-bold uppercase tracking-wider opacity-60 flex items-center gap-1 mb-1">
                        <AlertTriangle className="w-3 h-3" />
                        Detected Misconception
                      </span>
                      <p className="font-medium italic">"{gap.misconception}"</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="flex justify-center pt-8 pb-12">
        <button
          onClick={onStartRemediation}
          disabled={isLoadingSlides || analysis.identifiedGaps.length === 0}
          className="bg-gradient-to-r from-emerald-500 to-teal-600 text-white px-10 py-4 rounded-xl font-bold shadow-lg hover:shadow-xl hover:scale-[1.02] active:scale-[0.98] transform transition-all disabled:opacity-50 disabled:hover:scale-100 disabled:cursor-not-allowed flex items-center gap-3 border border-emerald-400/20"
        >
          {isLoadingSlides ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
              Building Personalized Lesson Plan...
            </>
          ) : (
            <>
              <BookOpen className="w-6 h-6" />
              Generate Remedial Slides
            </>
          )}
        </button>
      </div>
    </div>
  );
};

