import { GoogleGenAI, Schema, Type } from "@google/genai";
import { Standard, Quiz, GapAnalysis, RemedialSlide, GapType, QuizResult, Question, QuizConfig, Difficulty } from '../types';
import { MOCK_ITEM_BANK } from '../constants';

const getAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function callWithRetry<T>(operation: () => Promise<T>, retries = 3, baseDelay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const isQuotaError = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.toLowerCase().includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED';

    if (retries > 0 && isQuotaError) {
      const waitTime = baseDelay * Math.pow(2, 3 - retries);
      console.warn(`Quota/Rate limit hit. Retrying in ${waitTime}ms...`);
      await delay(waitTime);
      return callWithRetry(operation, retries - 1, baseDelay);
    }
    throw error;
  }
}

// Reusable Schema for a single question
const questionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    id: { type: Type.STRING },
    text: { type: Type.STRING },
    options: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "Must contain exactly 4 options"
    },
    correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
    explanation: { type: Type.STRING },
    animationDescription: { type: Type.STRING },
    visual: { type: Type.STRING, description: "Valid SVG string for questions requiring an image (e.g., counting objects). Optional." },
    difficulty: { type: Type.STRING, enum: ['Easy', 'Medium', 'Hard'], description: "The difficulty level of this specific question" }
  },
  required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription", "difficulty"]
};

export const generateQuiz = async (standard: Standard, config: QuizConfig): Promise<Quiz> => {

  // MODE 1: ITEM BANK
  if (config.mode === 'item-bank') {
    await new Promise(resolve => setTimeout(resolve, 800));
    const bankedQuestions = MOCK_ITEM_BANK[standard.code] || [];

    // In item bank mode, questions already have difficulty assigned in constants.ts
    if (bankedQuestions.length > 0) {
      let selectedQuestions = [...bankedQuestions];
      if (selectedQuestions.length > config.questionCount) {
        selectedQuestions = selectedQuestions.slice(0, config.questionCount);
      }
      return { standardCode: standard.code, questions: selectedQuestions, config };
    }
    console.warn(`Item Bank empty for ${standard.code}, falling back to AI generation.`);
  }

  // MODE 2: TOPIC-BASED (AI)
  // If Adaptive is ON, we only generate the first question (or first 2) to start the chain
  const countToGenerate = config.isAdaptive ? 1 : config.questionCount;

  const ai = getAiClient();
  const prompt = `
    You are an expert K-12 Mathematics Standards curriculum designer.

    TARGET AUDIENCE: ${standard.grade} Student
    SUBJECT: Mathematics

    Create ${countToGenerate} multiple-choice question(s) for:
    Topic/Standard: ${standard.code}
    Description: ${standard.description}
    Additional Context: ${standard.clarifications?.join(' ') || ''}

    **CONFIGURATION:**
    - Difficulty: ${config.difficulty}
    - Count: ${countToGenerate}

    **STRICT CONTENT RULES:**
    1. Questions MUST be strictly appropriate for a ${standard.grade} student.
    2. CONTENT SAFETY: Do NOT generate questions about Artificial Intelligence, Neural Networks, or advanced Computer Science unless the standard explicitly requires it. Keep it purely MATHEMATICAL (counting, arithmetic, geometry, etc).
    3. Ensure language is simple and clear for the grade level.

    **DIFFICULTY GUIDELINES:**
    - Easy: Direct application, simple numbers (1-3 complexity).
    - Medium: Multi-step, standard application (4-6 complexity).
    - Hard: Complex, analysis, larger numbers (7-10 complexity).

    **CRITICAL VISUALS:**
    If standard implies visual recognition (counting, shapes, graphs), you MUST provide valid SVG in 'visual' field.
    SVG ViewBox: "0 0 400 250". Simple, high contrast, accurate.

    Return JSON matching schema.
  `;

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: { type: Type.ARRAY, items: questionSchema }
    },
    required: ["standardCode", "questions"]
  };

  return callWithRetry(async () => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema
        }
      });

      const text = response.text;
      if (!text) throw new Error("No response from AI");

      const parsed = JSON.parse(text);
      return {
        standardCode: parsed.standardCode,
        questions: parsed.questions,
        config
      };
    } catch (error) {
      console.error("Quiz Generation Error:", error);
      throw error;
    }
  });
};

/**
 * Generates a SINGLE question for Adaptive Mode based on current difficulty context
 */
export const generateAdaptiveQuestion = async (
  standard: Standard, 
  currentDifficulty: Difficulty, 
  history: QuizResult[]
): Promise<Question> => {
  const ai = getAiClient();

  const lastResult = history[history.length - 1];
  const contextMsg = history.length > 0 
    ? `Student just answered the previous ${lastResult.difficulty} question ${lastResult.isCorrect ? 'CORRECTLY' : 'INCORRECTLY'}.`
    : 'Starting the quiz.';

  const prompt = `
    ADAPTIVE QUIZ GENERATION - NEXT QUESTION

    TARGET AUDIENCE: ${standard.grade} Student
    SUBJECT: Mathematics

    Standard: ${standard.code} (${standard.description})
    Context: ${standard.clarifications?.join(' ') || ''}

    **CURRENT STATE:**
    - Target Difficulty: ${currentDifficulty}
    - Context: ${contextMsg}
    - Question Number: ${history.length + 1}

    **TASK:**
    Generate EXACTLY 1 multiple-choice question at **${currentDifficulty}** level.

    **RULES:**
    1. STRICTLY aligned to ${standard.grade} math curriculum. NO advanced college topics or AI concepts.
    2. If Easy: Keep it fundamental.
    3. If Medium: Add a step or concept connection.
    4. If Hard: Require synthesis or error analysis.

    **FORMAT:**
    Return a SINGLE Question object in JSON.
  `;

  // We reuse the questionSchema but wrap it to ensure we get a single object or simple wrapper
  const singleQuestionResponseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      question: questionSchema
    },
    required: ["question"]
  };

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: singleQuestionResponseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response");
    const parsed = JSON.parse(text);
    return parsed.question;
  });
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  const ai = getAiClient();

  // Extract difficulty trend
  const difficultyTrend = questions.map(q => q.difficulty);

  const detailedAnalysis = questions.map((q, i) => {
    const r = results[i];
    return `Q${i + 1} [${q.difficulty}]: ${q.text} \n   (Selected: ${q.options[r.selectedOptionIndex]}, Correct: ${r.isCorrect})`;
  }).join('\n');

  const prompt = `
    Analyze student performance for Florida Standard ${standard.code}.
    Grade Level: ${standard.grade}

    **PERFORMANCE DATA:**
    ${detailedAnalysis}

    **TASK:**
    1. Identify learning gaps.
    2. **DIFFICULTY ANALYSIS**: Specifically analyze performance across Easy/Medium/Hard levels. 
       - Did they fail only at Hard? (Conceptual gap at high level)
       - Did they fail Easy? (Fundamental gap)

    Return JSON.
  `;

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } },
      misconception: { type: Type.STRING }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      subSkills: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { name: { type: Type.STRING }, description: { type: Type.STRING }, correctCount: { type: Type.INTEGER }, totalCount: { type: Type.INTEGER } } } },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "subSkills", "confidenceScore", "summary"]
  };

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { responseMimeType: "application/json", responseSchema: responseSchema }
    });

    const data = JSON.parse(response.text || '{}');
    // Inject difficulty trend manually since AI doesn't track it perfectly in schema
    data.difficultyTrend = difficultyTrend;
    return data as GapAnalysis;
  });
};

export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  const ai = getAiClient();

  const prompt = `
    Create 5 remedial slides for Standard ${standard.code} (${standard.grade} Math).

    **DIAGNOSIS:**
    ${analysis.identifiedGaps.map(g => `- ${g.description} (${g.misconception})`).join('\n')}

    **ADAPTIVE CONTEXT:**
    The student struggled specifically with the concepts identified above.
    Start the first slide at a LOWER difficulty level to build confidence, then scaffold up.

    Return JSON with 5 slides.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING },
      visualDescription: { type: Type.STRING },
      svgVisual: { type: Type.STRING },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: { slides: { type: Type.ARRAY, items: slideSchema } }
  };

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
