  });
};

import React, { useState, useEffect, useRef } from 'react';
import { Quiz, QuizResult, Question, Difficulty } from '../types';
import { generateAdaptiveQuestion } from '../services/geminiService';
import { FLORIDA_STANDARDS } from '../constants'; // Needed to re-fetch standard details
import { CheckCircle, XCircle, ArrowRight, Clock, Image as ImageIcon, Loader2, Gauge } from 'lucide-react';

interface Props {
  quiz: Quiz;
  onComplete: (results: QuizResult[]) => void;
}

const QuizTaker: React.FC<Props> = ({ quiz, onComplete }) => {
  // --- State Management ---
  const [questions, setQuestions] = useState<Question[]>(quiz.questions);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [results, setResults] = useState<QuizResult[]>([]);
  const [startTime, setStartTime] = useState(Date.now());
  const [showFeedback, setShowFeedback] = useState(false);

  // Adaptive State
  const [currentDifficulty, setCurrentDifficulty] = useState<Difficulty>(quiz.config.difficulty);
  const [consecutiveCorrect, setConsecutiveCorrect] = useState(0);
  const [consecutiveWrong, setConsecutiveWrong] = useState(0);
  const [isFetchingNext, setIsFetchingNext] = useState(false);

  // Background Fetch Reference
  const nextQuestionPromise = useRef<Promise<Question | null> | null>(null);

  // Standard lookup for API calls
  const standard = FLORIDA_STANDARDS.find(s => s.code === quiz.standardCode) || { 
    code: quiz.standardCode, grade: 'Grade 4' as any, description: 'Generated Topic' 
  };

  useEffect(() => {
    setStartTime(Date.now());
  }, [currentQuestionIdx]);

  // --- Logic ---

  const handleSelect = (idx: number) => {
    if (showFeedback) return;
    setSelectedOption(idx);
  };

  const getNextDifficulty = (current: Difficulty, isCorrect: boolean): Difficulty => {
    // Logic: 2 Correct -> Level Up. 2 Wrong -> Level Down.
    // Levels: Easy (1) -> Medium (2) -> Hard (3)

    // Calculate hypothetical new counters
    const nextConsecutiveCorrect = isCorrect ? consecutiveCorrect + 1 : 0;
    const nextConsecutiveWrong = isCorrect ? 0 : consecutiveWrong + 1;

    let nextDiff = current;

    if (nextConsecutiveCorrect >= 2) {
      if (current === 'Easy') nextDiff = 'Medium';
      else if (current === 'Medium') nextDiff = 'Hard';
      // If Hard, stay Hard
    } else if (nextConsecutiveWrong >= 2) {
      if (current === 'Hard') nextDiff = 'Medium';
      else if (current === 'Medium') nextDiff = 'Easy';
      // If Easy, stay Easy
    }

    return nextDiff;
  };

  const handleSubmitAnswer = () => {
    if (selectedOption === null) return;

    const question = questions[currentQuestionIdx];
    const timeTaken = (Date.now() - startTime) / 1000;
    const isCorrect = selectedOption === question.correctAnswerIndex;

    const result: QuizResult = {
      questionIndex: currentQuestionIdx,
      selectedOptionIndex: selectedOption,
      isCorrect,
      timeTaken,
      difficulty: question.difficulty
    };

    // Update Counters
    if (isCorrect) {
      setConsecutiveCorrect(prev => prev + 1);
      setConsecutiveWrong(0);
    } else {
      setConsecutiveCorrect(0);
      setConsecutiveWrong(prev => prev + 1);
    }

    // ADAPTIVE LOGIC: Prefetch next question
    if (quiz.config.isAdaptive && results.length + 1 < quiz.config.questionCount) {
       const nextDiff = getNextDifficulty(currentDifficulty, isCorrect);
       setCurrentDifficulty(nextDiff); // Update state for next question

       // Calculate new results history including current answer to pass to AI
       const newHistory = [...results, result];

       // START PREFETCH IN BACKGROUND
       // We do NOT set isFetchingNext(true) here to allow user to read feedback without a spinner blocking them
       nextQuestionPromise.current = generateAdaptiveQuestion(standard, nextDiff, newHistory)
         .then(q => {
            q.difficulty = nextDiff;
            return q;
         })
         .catch(e => {
            console.error("Background fetch failed", e);
            return null;
         });
    }

    const newResults = [...results, result];
    setResults(newResults);
    setShowFeedback(true);
  };

  const handleNext = async () => {
    const isLastQuestion = results.length >= quiz.config.questionCount;

    if (isLastQuestion) {
      onComplete(results);
      return;
    }

    // If we have the next question already in the array (e.g. standard mode), just advance
    if (currentQuestionIdx < questions.length - 1) {
      setCurrentQuestionIdx(curr => curr + 1);
      setSelectedOption(null);
      setShowFeedback(false);
      return;
    }

    // ADAPTIVE MODE: Check if prefetch is ready or start new fetch
    if (quiz.config.isAdaptive) {
      setIsFetchingNext(true); // Now we show loading because user explicitly asked for next

      try {
        let newQuestion: Question | null = null;

        if (nextQuestionPromise.current) {
           // Await the pre-fetch
           newQuestion = await nextQuestionPromise.current;
        } else {
           // Fallback if prefetch wasn't triggered (shouldn't happen often)
           newQuestion = await generateAdaptiveQuestion(standard, currentDifficulty, results);
           if (newQuestion) newQuestion.difficulty = currentDifficulty;
        }

        // Clear promise
        nextQuestionPromise.current = null;

        if (newQuestion) {
          setQuestions(prev => [...prev, newQuestion!]);
          setCurrentQuestionIdx(curr => curr + 1);
          setSelectedOption(null);
          setShowFeedback(false);
        } else {
           throw new Error("Failed to generate question");
        }
      } catch (e) {
        console.error("Failed to fetch next adaptive question", e);
        alert("Connection unstable. Retrying...");
        // Retry logic could go here, for now just reset loading so they can click again
        nextQuestionPromise.current = null; // Clear bad promise
      } finally {
        setIsFetchingNext(false);
      }
    }
  };

  // --- Rendering ---

  const processSVG = (svgString: string | undefined) => {
    if (!svgString) return null;
    let processed = svgString;
    if (!processed.includes('preserveAspectRatio')) {
      processed = processed.replace('<svg', '<svg preserveAspectRatio="xMidYMid meet"');
    }
    processed = processed.replace(/width="[^"]*"/, 'width="100%"').replace(/height="[^"]*"/, 'height="100%"');
    return processed;
  };

  const question = questions[currentQuestionIdx];
  const progress = ((currentQuestionIdx) / quiz.config.questionCount) * 100;

  // Get Difficulty Color
  const getDiffColor = (d: Difficulty) => {
    switch(d) {
      case 'Easy': return 'text-green-600 bg-green-50 border-green-200';
      case 'Medium': return 'text-amber-600 bg-amber-50 border-amber-200';
      case 'Hard': return 'text-red-600 bg-red-50 border-red-200';
      default: return 'text-slate-600 bg-slate-50 border-slate-200';
    }
  };

  return (
    <div className="max-w-3xl mx-auto">
      {/* Progress Bar */}
      <div className="w-full bg-slate-200 h-2 rounded-full mb-8 overflow-hidden">
        <div 
          className="bg-blue-600 h-2 rounded-full transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>

      <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden min-h-[500px] flex flex-col">
        {/* Header */}
        <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <span className="text-sm font-semibold text-slate-500 uppercase tracking-wide">
            Question {currentQuestionIdx + 1} of {quiz.config.questionCount}
          </span>
          <div className="flex items-center gap-3">
             {quiz.config.isAdaptive && (
               <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full border text-xs font-bold uppercase tracking-wider ${getDiffColor(question.difficulty)}`}>
                  <Gauge className="w-3.5 h-3.5" />
                  {question.difficulty}
               </div>
             )}
             <span className="text-sm font-medium text-slate-400 flex items-center gap-1">
              <Clock className="w-4 h-4" />
              Standard: {quiz.standardCode}
            </span>
          </div>
        </div>

        {/* Content */}
        <div className="p-8 flex-1">
          <h3 className="text-xl font-bold text-slate-900 mb-6 leading-relaxed">
            {question.text}
          </h3>

          {/* Question Visual */}
          {question.visual && (
            <div className="mb-8 p-4 bg-slate-50 rounded-xl border border-slate-200 flex flex-col items-center">
               <div className="flex items-center gap-2 mb-2 text-slate-400 text-xs font-bold uppercase tracking-wider">
                  <ImageIcon className="w-4 h-4" />
                  <span>Visual Aid</span>
               </div>
               <div
                  className="w-full max-w-lg aspect-[400/250] bg-white rounded-lg shadow-sm overflow-hidden"
                  dangerouslySetInnerHTML={{ __html: processSVG(question.visual) || '' }}
               />
            </div>
          )}

          <div className="space-y-4">
            {question.options.map((option, idx) => {
              let btnClass = "w-full p-4 rounded-xl border-2 text-left transition-all relative flex items-center justify-between ";

              if (showFeedback) {
                if (idx === question.correctAnswerIndex) {
                  btnClass += "border-green-500 bg-green-50 text-green-800";
                } else if (idx === selectedOption && idx !== question.correctAnswerIndex) {
                  btnClass += "border-red-500 bg-red-50 text-red-800";
                } else {
                  btnClass += "border-slate-100 text-slate-400 opacity-50";
                }
              } else {
                if (selectedOption === idx) {
                  btnClass += "border-blue-600 bg-blue-50 text-blue-900 shadow-md ring-2 ring-blue-100";
                } else {
                  btnClass += "border-slate-200 hover:border-blue-300 hover:bg-slate-50 text-slate-700";
                }
              }

              return (
                <button
                  key={idx}
                  onClick={() => handleSelect(idx)}
                  className={btnClass}
                  disabled={showFeedback}
                >
                  <span className="font-medium text-lg">{String.fromCharCode(65 + idx)}. {option}</span>
                  {showFeedback && idx === question.correctAnswerIndex && (
                    <CheckCircle className="w-6 h-6 text-green-600" />
                  )}
                  {showFeedback && idx === selectedOption && idx !== question.correctAnswerIndex && (
                    <XCircle className="w-6 h-6 text-red-600" />
                  )}
                </button>
              );
            })}
          </div>

          {showFeedback && (
            <div className="mt-8 animate-fade-in">
              <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-100">
                <h4 className="font-semibold text-indigo-900 mb-2 flex items-center gap-2">
                  Explanation
                </h4>
                <p className="text-indigo-800 leading-relaxed mb-4">{question.explanation}</p>

                <div className="bg-white p-4 rounded-lg border border-indigo-100">
                  <span className="text-xs font-bold text-indigo-400 uppercase tracking-wider mb-1 block">Visual Concept</span>
                  <p className="text-sm text-slate-600 italic">
                    "{question.animationDescription}"
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-8 py-6 bg-slate-50 border-t border-slate-100 flex justify-end">
          {!showFeedback ? (
            <button
              onClick={handleSubmitAnswer}
              disabled={selectedOption === null}
              className="bg-blue-600 text-white px-8 py-3 rounded-xl font-semibold shadow-lg hover:bg-blue-700 disabled:opacity-50 disabled:shadow-none transition-all"
            >
              Check Answer
            </button>
          ) : (
            <button
              onClick={handleNext}
              disabled={isFetchingNext}
              className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-semibold shadow-lg hover:bg-indigo-700 flex items-center gap-2 transition-all disabled:opacity-70"
            >
              {isFetchingNext ? (
                 <>
                   <Loader2 className="w-5 h-5 animate-spin" />
                   Thinking...
                 </>
              ) : (
                 <>
                   {results.length >= quiz.config.questionCount ? "Finish Quiz" : "Next Question"}
                   <ArrowRight className="w-5 h-5" />
                 </>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default QuizTaker;

import { GoogleGenAI, Schema, Type } from "@google/genai";
import { Standard, Quiz, GapAnalysis, RemedialSlide, GapType, QuizResult, Question, QuizConfig, Difficulty } from '../types';
import { MOCK_ITEM_BANK } from '../constants';

const getAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function callWithRetry<T>(operation: () => Promise<T>, retries = 3, baseDelay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const isQuotaError = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.toLowerCase().includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED';

    if (retries > 0 && isQuotaError) {
      const waitTime = baseDelay * Math.pow(2, 3 - retries);
      console.warn(`Quota/Rate limit hit. Retrying in ${waitTime}ms...`);
      await delay(waitTime);
      return callWithRetry(operation, retries - 1, baseDelay);
    }
    throw error;
  }
}

// Reusable Schema for a single question
const questionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    id: { type: Type.STRING },
    text: { type: Type.STRING },
    options: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "Must contain exactly 4 options"
    },
    correctAnswerIndex: { type: Type.INTEGER, description: "0-3" },
    explanation: { type: Type.STRING },
    animationDescription: { type: Type.STRING },
    visual: { type: Type.STRING, description: "Valid SVG string for questions requiring an image (e.g., counting objects). Optional." },
    difficulty: { type: Type.STRING, enum: ['Easy', 'Medium', 'Hard'], description: "The difficulty level of this specific question" }
  },
  required: ["id", "text", "options", "correctAnswerIndex", "explanation", "animationDescription", "difficulty"]
};

export const generateQuiz = async (standard: Standard, config: QuizConfig): Promise<Quiz> => {

  // MODE 1: ITEM BANK
  if (config.mode === 'item-bank') {
    await new Promise(resolve => setTimeout(resolve, 800));
    const bankedQuestions = MOCK_ITEM_BANK[standard.code] || [];

    // In item bank mode, questions already have difficulty assigned in constants.ts
    if (bankedQuestions.length > 0) {
      let selectedQuestions = [...bankedQuestions];
      if (selectedQuestions.length > config.questionCount) {
        selectedQuestions = selectedQuestions.slice(0, config.questionCount);
      }
      return { standardCode: standard.code, questions: selectedQuestions, config };
    }
    console.warn(`Item Bank empty for ${standard.code}, falling back to AI generation.`);
  }

  // MODE 2: TOPIC-BASED (AI)
  // If Adaptive is ON, we only generate the first question (or first 2) to start the chain
  const countToGenerate = config.isAdaptive ? 1 : config.questionCount;

  const ai = getAiClient();
  const prompt = `
    You are an expert K-12 Mathematics Standards curriculum designer.

    TARGET AUDIENCE: ${standard.grade} Student
    SUBJECT: Mathematics

    Create ${countToGenerate} multiple-choice question(s) for:
    Topic/Standard: ${standard.code}
    Description: ${standard.description}
    Additional Context: ${standard.clarifications?.join(' ') || ''}

    **CONFIGURATION:**
    - Difficulty: ${config.difficulty}
    - Count: ${countToGenerate}

    **CRITICAL CONSISTENCY RULES:**
    1. **Text-Visual Match**: If the question text asks to count objects (e.g., "How many red apples?"), the SVG MUST show EXACTLY that number.
    2. **Option Coherence**: The correct answer MUST be present in the 'options' array.
    3. **Distractor Plausibility**: Wrong options should be plausible errors (e.g., off-by-one, common calculation mistakes). Do NOT generate random numbers.
    4. **Safety**: Strictly ${standard.grade} appropriate. NO AI/Tech topics.

    **VISUALS (SVG):**
    - Provide a clean, valid SVG string in the 'visual' field for geometry, counting, or fraction questions.
    - ViewBox: "0 0 400 250".
    - Use simple shapes (circle, rect, path) to ensure rendering success.

    Return JSON matching schema.
  `;

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      questions: { type: Type.ARRAY, items: questionSchema }
    },
    required: ["standardCode", "questions"]
  };

  return callWithRetry(async () => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema
        }
      });

      const text = response.text;
      if (!text) throw new Error("No response from AI");

      const parsed = JSON.parse(text);
      return {
        standardCode: parsed.standardCode,
        questions: parsed.questions,
        config
      };
    } catch (error) {
      console.error("Quiz Generation Error:", error);
      throw error;
    }
  });
};

/**
 * Generates a SINGLE question for Adaptive Mode based on current difficulty context
 */
export const generateAdaptiveQuestion = async (
  standard: Standard, 
  currentDifficulty: Difficulty, 
  history: QuizResult[]
): Promise<Question> => {
  const ai = getAiClient();

  const lastResult = history[history.length - 1];
  const contextMsg = history.length > 0 
    ? `Student just answered the previous ${lastResult.difficulty} question ${lastResult.isCorrect ? 'CORRECTLY' : 'INCORRECTLY'}.`
    : 'Starting the quiz.';

  const prompt = `
    ADAPTIVE QUIZ GENERATION - NEXT QUESTION

    TARGET AUDIENCE: ${standard.grade} Student
    SUBJECT: Mathematics

    Standard: ${standard.code} (${standard.description})
    Context: ${standard.clarifications?.join(' ') || ''}

    **CURRENT STATE:**
    - Target Difficulty: ${currentDifficulty}
    - Context: ${contextMsg}
    - Question Number: ${history.length + 1}

    **TASK:**
    Generate EXACTLY 1 multiple-choice question at **${currentDifficulty}** level.

    **STRICT COHERENCE CHECKS:**
    1. **Visual Alignment**: If you generate an SVG, it MUST depict the exact scenario described in the text. (e.g., if text says "3/4", SVG must show 3 shaded out of 4).
    2. **Option Validity**: Ensure the calculated answer is mathematically correct and included in 'options'.
    3. **No Hallucinations**: Do not reference objects or numbers not present in the visual/text.

    **FORMAT:**
    Return a SINGLE Question object in JSON.
  `;

  // We reuse the questionSchema but wrap it to ensure we get a single object or simple wrapper
  const singleQuestionResponseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      question: questionSchema
    },
    required: ["question"]
  };

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: singleQuestionResponseSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response");
    const parsed = JSON.parse(text);
    return parsed.question;
  });
};

export const analyzeGaps = async (standard: Standard, questions: Question[], results: QuizResult[]): Promise<GapAnalysis> => {
  const ai = getAiClient();

  // Extract difficulty trend
  const difficultyTrend = questions.map(q => q.difficulty);

  const detailedAnalysis = questions.map((q, i) => {
    const r = results[i];
    return `Q${i + 1} [${q.difficulty}]: ${q.text} \n   (Selected: ${q.options[r.selectedOptionIndex]}, Correct: ${r.isCorrect})`;
  }).join('\n');

  const prompt = `
    Analyze student performance for Florida Standard ${standard.code}.
    Grade Level: ${standard.grade}

    **PERFORMANCE DATA:**
    ${detailedAnalysis}

    **TASK:**
    1. Identify learning gaps.
    2. **DIFFICULTY ANALYSIS**: Specifically analyze performance across Easy/Medium/Hard levels. 
       - Did they fail only at Hard? (Conceptual gap at high level)
       - Did they fail Easy? (Fundamental gap)

    Return JSON.
  `;

  const gapSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      gapType: { type: Type.STRING, enum: Object.values(GapType) },
      description: { type: Type.STRING },
      relatedQuestions: { type: Type.ARRAY, items: { type: Type.INTEGER } },
      misconception: { type: Type.STRING }
    },
    required: ["gapType", "description", "relatedQuestions"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      standardCode: { type: Type.STRING },
      identifiedGaps: { type: Type.ARRAY, items: gapSchema },
      subSkills: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { name: { type: Type.STRING }, description: { type: Type.STRING }, correctCount: { type: Type.INTEGER }, totalCount: { type: Type.INTEGER } } } },
      confidenceScore: { type: Type.INTEGER },
      summary: { type: Type.STRING }
    },
    required: ["standardCode", "identifiedGaps", "subSkills", "confidenceScore", "summary"]
  };

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { responseMimeType: "application/json", responseSchema: responseSchema }
    });

    const data = JSON.parse(response.text || '{}');
    // Inject difficulty trend manually since AI doesn't track it perfectly in schema
    data.difficultyTrend = difficultyTrend;
    return data as GapAnalysis;
  });
};

export const generateRemedialSlides = async (standard: Standard, analysis: GapAnalysis): Promise<RemedialSlide[]> => {
  const ai = getAiClient();

  const prompt = `
    Create 5 remedial slides for Standard ${standard.code} (${standard.grade} Math).

    **DIAGNOSIS:**
    ${analysis.identifiedGaps.map(g => `- ${g.description} (${g.misconception})`).join('\n')}

    **ADAPTIVE CONTEXT:**
    The student struggled specifically with the concepts identified above.
    Start the first slide at a LOWER difficulty level to build confidence, then scaffold up.

    Return JSON with 5 slides.
  `;

  const slideSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      slideNumber: { type: Type.INTEGER },
      title: { type: Type.STRING },
      content: { type: Type.STRING },
      visualDescription: { type: Type.STRING },
      svgVisual: { type: Type.STRING },
      vocabulary: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["slideNumber", "title", "content", "visualDescription", "svgVisual", "vocabulary"]
  };

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: { slides: { type: Type.ARRAY, items: slideSchema } }
  };

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { responseMimeType: "application/json", responseSchema: responseSchema }
    });
    return JSON.parse(response.text || '{}').slides;
  });
};

