                              difficulty === level 
                                ? 'border-indigo-500 bg-indigo-50 text-indigo-700' 
                                : 'border-slate-200 text-slate-600 hover:border-slate-300'
                            }`}
                          >
                            {level}
                          </button>
                        ))}
                      </div>
                   </div>

                   {/* Advanced Filters (Topic Mode Only) */}
                   {quizMode === 'topic-based' && (
                     <>
