import React, { useState, useEffect } from 'react';
import { AppState, Standard, Quiz, QuizResult, GapAnalysis, RemedialSlide, QuizConfig, User } from './types';
import { generateQuiz, analyzeGaps, generateRemedialSlides } from './services/geminiService';
import { dbService } from './services/dbService';
import QuizGenerator from './components/QuizGenerator';
import QuizTaker from './components/QuizTaker';
import GapAnalysisComponent from './components/GapAnalysis';
import RemedialSlides from './components/RemedialSlides';
import AuthScreen from './components/AuthScreen';
import { GraduationCap, LogOut, User as UserIcon } from 'lucide-react';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [state, setState] = useState<AppState>({
    view: 'setup',
    selectedStandard: null,
    quiz: null,
    quizResults: [],
    analysis: null,
    slides: [],
    loading: false,
    loadingMessage: '',
  });

  // Initialize Session
  useEffect(() => {
    const currentUser = dbService.getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
    }
  }, []);

  // Global Click Tracker
  useEffect(() => {
    const handleGlobalClick = (e: MouseEvent) => {
      if (!user) return;

      const target = e.target as HTMLElement;
      // We log clicks on interactive elements
      if (target.tagName === 'BUTTON' || target.tagName === 'A' || target.closest('button') || target.closest('a')) {
        const text = target.innerText || target.getAttribute('aria-label') || 'Unknown Element';
        dbService.logAction(user.id, 'CLICK', { 
           text: text.substring(0, 50), 
           tag: target.tagName,
           x: e.clientX,
           y: e.clientY 
        });
      }
    };

    window.addEventListener('click', handleGlobalClick);
    return () => window.removeEventListener('click', handleGlobalClick);
  }, [user]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
  };

  const handleLogout = () => {
    dbService.logout();
    setUser(null);
    restart();
  };

  const handleApiError = (error: any) => {
    console.error("API Error:", error);
    let message = "An error occurred while communicating with the AI service.";

    const isQuotaError = 
      error?.status === 429 || 
      error?.code === 429 || 
      error?.message?.includes('429') || 
      error?.message?.toLowerCase().includes('quota') ||
      error?.status === 'RESOURCE_EXHAUSTED';

    if (isQuotaError) {
      message = "⚠️ API Rate Limit Exceeded. The system is busy or you have hit your quota. Please wait a moment and try again.";
    }

    alert(message);
    setState(prev => ({ ...prev, loading: false }));
  };

  const handleGenerateQuiz = async (standard: Standard, config: QuizConfig) => {
    const modeLabel = config.mode === 'item-bank' ? 'Fetching Bank Items...' : 'Generating AI Questions...';

    // Log Activity
    if (user) {
      dbService.logAction(user.id, 'QUIZ_GENERATE_START', { standard: standard.code, mode: config.mode });
    }

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: modeLabel, 
      selectedStandard: standard 
    }));

    try {
      const quiz = await generateQuiz(standard, config);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        quiz, 
        view: 'quiz',
        quizResults: [] // reset results
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const handleQuizComplete = async (results: QuizResult[]) => {
    if (!state.quiz || !state.selectedStandard) return;

    // Save to DB
    if (user) {
      dbService.saveQuizAttempt(user.id, state.quiz, results);
    }

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Analyzing Performance & Identifying Gaps...', 
      quizResults: results 
    }));

    try {
      const analysis = await analyzeGaps(state.selectedStandard, state.quiz.questions, results);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        analysis, 
        view: 'analysis' 
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const handleStartRemediation = async () => {
    if (!state.analysis || !state.selectedStandard) return;

    if (user) {
      dbService.logAction(user.id, 'REMEDIAL_START', { standard: state.selectedStandard.code });
    }

    setState(prev => ({ 
      ...prev, 
      loading: true, 
      loadingMessage: 'Creating Personalized Learning Slides...' 
    }));

    try {
      const slides = await generateRemedialSlides(state.selectedStandard, state.analysis);
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        slides, 
        view: 'remedial' 
      }));
    } catch (error) {
      handleApiError(error);
    }
  };

  const restart = () => {
    if (user) {
      dbService.logAction(user.id, 'VIEW_HOME', {});
    }
    setState({
      view: 'setup',
      selectedStandard: null,
      quiz: null,
      quizResults: [],
      analysis: null,
      slides: [],
      loading: false,
      loadingMessage: '',
    });
  };

  // --- Auth Gate ---
  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={restart}>
            <div className="bg-blue-600 p-2 rounded-lg">
              <GraduationCap className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-indigo-700 hidden md:block">
              Florida B.E.S.T. Math Architect
            </h1>
            <h1 className="text-xl font-bold text-blue-700 md:hidden">Math Architect</h1>
          </div>

          <div className="flex items-center gap-4">
             {state.selectedStandard && (
              <div className="text-sm font-medium text-slate-500 bg-slate-100 px-3 py-1 rounded-full hidden sm:block">
                {state.selectedStandard.code}
              </div>
             )}

             <div className="h-6 w-px bg-slate-200 mx-2 hidden sm:block"></div>

             <div className="flex items-center gap-3">
                <div className="flex items-center gap-2">
                   <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600">
                      <UserIcon className="w-4 h-4" />
                   </div>
                   <span className="text-sm font-bold text-slate-700 hidden sm:block">{user.fullName || user.username}</span>
                </div>
                <button 
                  onClick={handleLogout}
                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                  title="Logout"
                >
                  <LogOut className="w-5 h-5" />
                </button>
             </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {state.loading ? (
          <div className="flex flex-col items-center justify-center h-[60vh] animate-fade-in">
            <div className="relative w-24 h-24 mb-8">
              <div className="absolute inset-0 border-4 border-slate-200 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">{state.loadingMessage}</h2>
            <p className="text-slate-500">Powered by Gemini AI</p>
          </div>
        ) : (
          <>
            {state.view === 'setup' && (
              <div className="animate-slide-up">
                <QuizGenerator onGenerate={handleGenerateQuiz} isLoading={state.loading} />
              </div>
            )}

            {state.view === 'quiz' && state.quiz && (
              <div className="animate-slide-up">
                <QuizTaker quiz={state.quiz} onComplete={handleQuizComplete} />
              </div>
            )}

            {state.view === 'analysis' && state.analysis && (
              <div className="animate-slide-up">
                <GapAnalysisComponent 
                  analysis={state.analysis} 
                  onStartRemediation={handleStartRemediation} 
                  isLoadingSlides={state.loading} 
                />
              </div>
            )}

            {state.view === 'remedial' && (
              <div className="animate-fade-in">
                <RemedialSlides slides={state.slides} onRestart={restart} />
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { GradeLevel, Standard, QuizMode, Difficulty, QuizConfig, TopicNode } from '../types';
import { FLORIDA_STANDARDS, TOPIC_TREE } from '../constants';
import { dbService } from '../services/dbService';
import { Sparkles, ChevronDown, Database, Settings2, Menu, Filter, ArrowRight } from 'lucide-react';
import TopicSidebar from './TopicSidebar';

interface Props {
  onGenerate: (standard: Standard, config: QuizConfig) => void;
  isLoading: boolean;
}

const QuizGenerator: React.FC<Props> = ({ onGenerate, isLoading }) => {
  // Modes
  const [quizMode, setQuizMode] = useState<QuizMode>('item-bank');

  // Standard Mode State
  const [selectedGrade, setSelectedGrade] = useState<GradeLevel | ''>('');
  const [selectedStandardCode, setSelectedStandardCode] = useState<string>('');

  // Topic Mode State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [selectedTopic, setSelectedTopic] = useState<TopicNode | null>(null);
  const [breadcrumbs, setBreadcrumbs] = useState<string[]>([]);

  // Configuration State
  const [questionCount, setQuestionCount] = useState<number>(5);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');

  // Advanced Config State
  const [config, setConfig] = useState({
    questionTypes: {
      multipleChoice: true,
      trueFalse: false,
      fillInBlank: false
    },
    focusAreas: {
      wordProblems: true,
      visualQuestions: true,
      realWorld: false
    }
  });

  // Derived
  const filteredStandards = FLORIDA_STANDARDS.filter(s => s.grade === selectedGrade);
  const selectedStandard = FLORIDA_STANDARDS.find(s => s.code === selectedStandardCode);

  // Handlers
  const handleTopicSelect = (node: TopicNode, path: string[]) => {
     setSelectedTopic(node);
     setBreadcrumbs(path);

     // Log Topic Selection to DB
     const user = dbService.getCurrentUser();
     if (user) {
        dbService.logAction(user.id, 'TOPIC_SELECT', { topic: node.title, path: path.join('>') });
     }
  };

  const handleGenerate = () => {
    const finalConfig: QuizConfig = {
      questionCount,
      difficulty,
      mode: quizMode,
      questionTypes: config.questionTypes,
      focusAreas: config.focusAreas
    };

    if (quizMode === 'item-bank' && selectedStandard) {
      onGenerate(selectedStandard, finalConfig);
    } else if (quizMode === 'topic-based' && selectedTopic) {
      // 1. Determine Grade Level from Breadcrumbs (Root level is always Grade)
      const gradeStr = breadcrumbs[0];
      const detectedGrade = Object.values(GradeLevel).find(g => g === gradeStr) || GradeLevel.G4;

      // 2. Determine Standard Code or Create a Custom Topic Code
      const safeTitle = selectedTopic.title.replace(/[^a-zA-Z0-9]/g, '').substring(0, 5).toUpperCase();
      const standardCode = selectedTopic.associatedStandards?.[0] || `MA.TOPIC.${safeTitle}`;

      // 3. Construct the Standard Object with EXPLICIT Context
      const mappedStandard: Standard = FLORIDA_STANDARDS.find(s => s.code === standardCode) || {
        code: standardCode,
        grade: detectedGrade,
        description: `Assessment on ${selectedTopic.title}`,
        clarifications: [
           `Subject: K-12 Mathematics`,
           `Target Grade: ${gradeStr}`,
           `Topic Hierarchy: ${breadcrumbs.join(' > ')}`,
           `Ensure questions are strictly aligned to ${gradeStr} math curriculum.`
        ]
      };

      onGenerate(mappedStandard, finalConfig);
    }
  };

  useEffect(() => {
    if (quizMode === 'topic-based') {
       setIsSidebarOpen(true);
    }
  }, [quizMode]);

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-slate-50 relative -mx-4 sm:-mx-6 lg:-mx-8 -my-8">

      {/* Sidebar (Only visible in Topic Mode) */}
      {quizMode === 'topic-based' && (
        <TopicSidebar 
          data={TOPIC_TREE} 
          isOpen={isSidebarOpen} 
          onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
          selectedNodeId={selectedTopic?.id || null}
          onSelect={handleTopicSelect}
        />
      )}

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col h-full overflow-y-auto">
        <div className="max-w-5xl mx-auto w-full p-6 lg:p-10 space-y-8">

          {/* Header & Mode Switcher */}
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-slate-200 pb-6">
             <div>
                <h1 className="text-3xl font-bold text-slate-900">New Assessment</h1>
                <p className="text-slate-500 mt-1">Configure parameters to generate your quiz</p>
             </div>

             <div className="bg-white p-1 rounded-xl border border-slate-200 flex shadow-sm">
                <button
                  onClick={() => setQuizMode('item-bank')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                    quizMode === 'item-bank' 
                      ? 'bg-emerald-100 text-emerald-700 shadow-sm' 
                      : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <Database className="w-4 h-4" />
                  Item Bank
                </button>
                <button
                  onClick={() => setQuizMode('topic-based')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                    quizMode === 'topic-based' 
                      ? 'bg-blue-100 text-blue-700 shadow-sm' 
                      : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <Sparkles className="w-4 h-4" />
                  Topic AI
                </button>
             </div>
          </div>

          {/* Mobile Sidebar Toggle */}
          {quizMode === 'topic-based' && (
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="lg:hidden flex items-center gap-2 text-blue-600 font-bold bg-blue-50 px-4 py-2 rounded-lg w-fit"
            >
               <Menu className="w-4 h-4" />
               Browse Topics
            </button>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

             {/* Left Col: Context Selection */}
             <div className="lg:col-span-7 space-y-6">

                {/* Standard Mode Selection UI */}
                {quizMode === 'item-bank' && (
                  <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 space-y-6 animate-fade-in">
                      <div className="flex items-center gap-2 mb-2">
                         <span className="w-8 h-8 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-sm">1</span>
                         <h3 className="font-bold text-lg text-slate-800">Select Standard</h3>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-semibold text-slate-700 mb-2">Grade</label>
                          <select 
                            className="w-full p-3 rounded-xl border border-slate-200 bg-slate-50 font-medium"
                            value={selectedGrade}
                            onChange={(e) => {
                              setSelectedGrade(e.target.value as GradeLevel);
                              setSelectedStandardCode('');
                            }}
                          >
                            <option value="">Select...</option>
                            {Object.values(GradeLevel).map(g => <option key={g} value={g}>{g}</option>)}
                          </select>
                        </div>
                        <div>
                           <label className="block text-sm font-semibold text-slate-700 mb-2">Standard</label>
                           <select 
                            className="w-full p-3 rounded-xl border border-slate-200 bg-slate-50 font-medium disabled:opacity-50"
                            value={selectedStandardCode}
                            onChange={(e) => setSelectedStandardCode(e.target.value)}
                            disabled={!selectedGrade}
                          >
                            <option value="">Select...</option>
                            {filteredStandards.map(s => <option key={s.code} value={s.code}>{s.code}</option>)}
                          </select>
                        </div>
                      </div>

                      {selectedStandard && (
                        <div className="bg-emerald-50 p-4 rounded-xl border border-emerald-100">
                           <h4 className="font-bold text-emerald-900 mb-1">{selectedStandard.code}</h4>
                           <p className="text-sm text-emerald-800">{selectedStandard.description}</p>
                        </div>
